       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"5f5656fc-8e6a-5504-847a-da41842ac123","document_type":"judgment","category":"judicial","subcategory":"general","title":"-1قال اإلمام ابن قدامه رحمه اهلل يف الكايف ( ( : )257/6وإذا ادعى أنه أقر مكره ا لم يقبل إال ببينة ألن األصل السامة فإن ثبت أنه ال به فالقول قوله مع ميينه ). كان مقيد ا أو محبوس ا أو موك -2قال اإلمام الشافعي رحمه اهلل يف األم ( ( : )241/3ويقبل قوله إذا كان محبوس ا وإن شهدوا أنه غير مكره وإذا شهد شاهدان أن فالن ا أقر لفان وهو محبوس بكذا أو لدى سلطان بكذا فقال املشهود عليه أقررت لغم احلبس أو إلكراه السلطان فالقول قوله مع ميينه","document_number":"34359573","case_number":"3483667","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالمحكمة العامة مبحافظة األحساء ومساعد الرئيس","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/12","year":"1434","subject":"-1قال اإلمام ابن قدامه رحمه اهلل يف الكايف ( ( : )257/6وإذا ادعى أنه أقر مكره ا لم يقبل إال ببينة ألن األصل السامة فإن ثبت أنه ال به فالقول قوله مع ميينه ). كان مقيد ا أو محبوس ا أو موك -2قال اإلمام الشافعي رحمه اهلل يف األم ( ( : )241/3ويقبل قوله إذا كان محبوس ا وإن شهدوا أنه غير مكره وإذا شهد شاهدان أن فالن ا أقر لفان وهو محبوس بكذا أو لدى سلطان بكذا فقال املشهود عليه أقررت لغم احلبس أو إلكراه السلطان فالقول قوله مع ميينه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34359573 :‬تاريخه ‪1434/11/12 :‬هـ‬\n                      ‫رقم الدعوى‪3483667 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 35117455‬تاريخه ‪1435/1/16:‬ه‬\n\n\n\n ‫ســرقة ـ شــروع يف الســرقة ـ ســرقة بعــض احملتويــات مــن بعــض احملــات‬\n ‫التجاريــة ـ إشــتراك يف الســرقة ـ الرجــوع عــن اإلقــرار املصــدق شــرع ًا ـ‬\n ‫اإلكــراه باإلقــرار ـ ضــرب املتهــم ـ درء حــد الســرقة بالشــبهة ـ التعزيــر‬\n                                                            ‫بالســجن واجللــد‪.‬‬\n\n\n\n\n ‫‪-1‬قــال اإلمــام ابــن قدامــه رحمــه اهلل يف الــكايف (‪ ( : )257/6‬وإذا ادعــى‬\n ‫أنــه أقــر مكرهـ ًا لــم يقبــل إال ببينــة ألن األصــل الســامة فــإن ثبــت أنــه‬\n      ‫ال بــه فالقــول قولــه مــع ميينــه )‪.‬‬ ‫كان مقيــد ًا أو محبوسـ ًا أو مــوك ً‬\n ‫‪-2‬قــال اإلمــام الشــافعي رحمــه اهلل يف األم (‪ ( : )241/3‬ويقبــل قولــه إذا‬\n ‫كان محبوسـ ًا وإن شــهدوا أنــه غيــر مكــره وإذا شــهد شــاهدان أن فالنـ ًا‬\n ‫أقــر لفــان وهــو محبــوس بكــذا أو لــدى ســلطان بكــذا فقــال املشــهود‬\n ‫عليــه أقــررت لغــم احلبــس أو إلكــراه الســلطان فالقــول قولــه مع ميينه‬\n ‫إال أن تشــهد البينــة أنــه أقــر عنــد الســلطان غيــر مكــره ‪ ،‬وال يخــاف حــن‬\n           ‫شــهدوا أنــه أقــر غيــر مكــروه ‪ ،‬وال محبــوس بســبب مــا أقــر لهــا )‪.‬‬\n ‫‪-3‬جــاء يف املبســوط لإلمــام السرخســي رحمــه اهلل ( ‪ ( : )70/24‬لــو أن‬\n ‫ا بتهديــد ضــرب أو حبــس أو قيــد حتــى يقــر علــى‬           ‫قاضي ـ ًا أكــره رج ـ ً‬\n ‫ا ألن اإلقــرار متمثــل بــن‬       ‫نفســه بحــد أو قصــاص كان اإلقــرار باط ـ ً‬\n ‫الصــدق والكــذب وإمنــا يكــون حجــة إذا ترجــح جانــب الصــدق علــى‬\n ‫جانــب الكــذب ‪ ،‬والتهديــد بالضــرب ‪ ،‬واحلبــس مينــع رجحــان جانــب‬\n                                                                                          ‫‪162‬‬\n\f      ‫الصــدق علــى مــا قــال عمــر رضــي اهلل عنــه ‪ :‬ليــس الرجــل علــى نفســه‬\n      ‫بأمــن إذا ضربتــه أو أوثقتــه ‪ ،‬ولــم ينقــل عــن أحــد مــن املتقدمــن مــن‬\n      ‫أصحابنــا رحمهــم اهلل صحــة اإلقــرار مــع التهديــد بالضــرب واحلبــس‬\n      ‫يف حــق الســارق وغيــره إال شــيئ ًا روي عــن احلســن بــن زيــاد رضــي اهلل‬\n      ‫عنــه ‪ :‬أن بعــض األمــراء بعــث لــه ‪ ،‬وســأله عــن ضــرب الســارق ليقــر ‪،‬‬\n      ‫فقــال مــا لــم يقطــع اللحــم أو يبــن العظــم ‪ ،‬ثــم نــدم علــى مقالتــه‬\n      ‫وجــاء بنفســه إلــى مجلــس األميــر ليمنعــه مــن ذلــك ‪ ،‬فوجــده قــد‬\n      ‫ضربــه حتــى اعتــرف وجــاء باملــال فلمــا رأى املــال موضوع ـ ًا بــن يــدي‬\n                        ‫األميــر قــال ‪ :‬مــا رأيــت ظلم ـ ًا أشــبه باحلــق مــن هــذا )‪.‬‬\n      ‫‪-4‬قــال القاضــي شــريح رحمــه اهلل كمــا جــاء يف املصنــف لعبدالــرزاق‬\n      ‫(‪ ( : )192/10‬القيــد كــره ‪ ،‬والوعيــد كــره ‪ ،‬والســجن كــره ‪ ،‬والضــرب‬\n                                                                                   ‫كــره )‪.‬‬\n      ‫‪-5‬قــال أميــر املؤمنــن عمــر بــن اخلطــاب رضــي اهلل عنــه ‪ ( :‬ليــس الرجــل‬\n      ‫بأمــن علــى نفســه إن أجعتــه أو أخفتــه أو حبســته)‪ .‬أخرجــه ابــن أبــي‬\n                                                           ‫شــيبه يف املصنــف (‪.)490/6‬‬\n      ‫‪-6‬املــادة (‪ )104‬مــن نظــام املرافعــات الشــرعية ونصــت علــى ‪ ( :‬يجــب أن‬\n      ‫ا أمــام القضــاء أثنــاء الســير يف الدعــوى املتعلقــة‬  ‫يكــون اإلقــرار حاصـ ً‬\n                                                                 ‫بالواقعــة املقــر بهــا )‪.‬‬\n      ‫‪-7‬قــال ابــن قدامــة رحمــه اهلل يف املغنــى (‪ ( : )250/10‬واحلــرز مــا عــد‬\n      ‫حــرز ًا يف العــرف فإنــه ملــا ثبــت اعتبــاره يف الشــرع مــن غيــر تنصيــص‬\n                              ‫علــى بيانــه علــم أنــه رد ذلــك إلــى أهــل العــرف )‪.‬‬\n             ‫‪-8‬قول النبي صلى اهلل عليه وسلم ( ادرؤوا احلدود بالشبهات )‪.‬‬\n      ‫‪-9‬قــال اإلمــام ابــن املنــذر رحمــه اهلل كمــا جــاء يف املغنــى (‪( : )55/9‬‬\n\n\n‫‪163‬‬\n\f‫أجمع كل من أحفظ عنه من أهل العلم أن احلدود تدرأ بالشبهات)‪.‬‬\n‫‪-10‬مــا جــاء عــن ابــن عمــر رضــي اهلل عنهمــا ‪ :‬أن رســول اهلل صلــى اهلل‬\n‫عليــه وســلم قاتــل أهــل خيبــر حتــى غلــب علــى األرض والــزرع والنخــل‬\n‫واشــترط عليهــم ان ال يكتمــوا وال يغيبــوا شــيئ ًا فغيبــوا مســك ًا فيــه مــال‬\n‫وحلــي حليــي بــن أخطــب فقــال رســول اهلل صلــى اهلل عليــه وســلم لعــم‬\n‫حيــي مــا فعــل مســك حيــي الــذي جــاء بــه بنــي النظيــر فقــال أذهبتــه‬\n‫النفقــات واحلــروب فقــال العهــد قريــب واملــال أكثــر مــن ذلــك فدفعــه‬\n‫إلــى الزبيــر فمســه بعــذاب فقــال رأيــت حيي ـ ًا يف خربــة ههنــا فذهبــوا‬\n                                                         ‫فوجــدوا املســك هنــاك )‪.‬‬\n‫‪-11‬مــا روى أنــس رضــي اهلل عنــه قــال نــدب رســول اهلل صلــى اهلل عليــه‬\n‫وســلم النــاس فانطلقــوا حتــى نزلــوا بــدر ًا ووردت عليهــم روايــا قريــش‬\n‫وفيهــم غــام اســود لبنــى احلجــاج فأخــذوه فــكان أصحــاب رســول اهلل‬\n‫صلــى اهلل عليــه وســلم يســألونه عــن أبــي ســفيان وأصحابــه فيقــول ‪:‬‬\n‫مالــي علــم بأبــي ســفيان ولكــن هــذا أبــو جهــل وعتبــه وشــيبة وأميــة‬\n‫بــن خلــف يف النــاس فــإذا قــال هــذا ضربــوه ورســول اهلل صلــى اهلل عليــه‬\n‫وســلم قائــم يصلــي فلمــا رأى ذلــك انصــرف وقــال ( والــذي نفســي بيــده‬\n                   ‫لتضربــوه إذا صدقكــم وتتركــوه إذا كذبكــم ) رواه مســلم‬\n‫‪-12‬مــا رواه البخــاري ومســلم يف شــأن بريــره أن رســول اهلل صلــى اهلل‬\n‫عليــه وســلم دعاهــا فســألها فقــام علــي فضربهــا ضرب ـ ًا شــديد ًا وجعــل‬\n               ‫يقــول أصدقــي رســول اهلل فتقــول ‪ :‬واهلل مــا أعلــم إال خيــر ًا‬\n‫‪-13‬قــال ابــن فرحــون رحمــه اهلل يف تبصــره احلــكام بعــد إيــراده لقصــة‬\n         ‫بريــره ‪ ( :‬وهــذا مــن السياســة ألن ضربهــا لتقــر مبــا عندهــا )‪.‬‬\n‫‪-14‬مــا روى أبــو داود أن قومـ ًا مــن الكالعيــن ُســرق لهــم متــاع فاتهمــوا‬\n\n\n                                                                                      ‫‪164‬‬\n\f      ‫أناسـ ًا مــن احلاكــة فأتــوا النعمــان بــن بشــير صاحــب رســول اهلل صلــى‬\n      ‫اهلل عليــه وســلم فحبســهم أيام ـ ًا ثــم خلــى ســبيلهم فأتــوا النعمــان‬\n      ‫فقالــوا خليــت ســبيلهم بغيــر ضــرب وال امتحــان فقــال النعمــان ‪ :‬مــا‬\n      ‫شــئتم ‪ ،‬إن شــئتم أن أضربهــم فــإن خــرج متاعكــم فــذاك وإال أخــذت مــن‬\n      ‫ظهوركــم مثــل مــا أخــذت مــن ظهورهــم فقالــوا هــذا حكمــك ؟ فقــال‬\n                                                          ‫هــذا حكــم اهلل ورســوله )‪.‬‬\n      ‫‪-15‬قاعــدة ‪ :‬جلــب أعلــى املصلحتــن لتفويــت أدناهمــا ‪ ،‬وارتــكاب أدنــى‬\n                                                     ‫املفســدتني دفعـ ًا ألعالهمــا ‪.‬‬\n      ‫‪-16‬قــال ابــن تيميــه رحمــه اهلل يف مجمــوع الفتــاوى عــن كالمــه عــن‬\n      ‫رأي مــن رأى ضــرب املتهــم املعــروف بالفجــور ليكشــف عــن حالــه ‪( :‬‬\n      ‫ولهــم مــن املعقــول قولهــم إن املمتنــع عــن أداء واجــب إذا أصــر علــى‬\n      ‫االمتنــاع فإنــه يعاقــب ويضــرب مــره بعــد أخــرى حتــى يؤدبــه ‪ ،‬فكذلــك‬\n                             ‫املتهــم املعــروف بالفجــور يضــرب لتســتبني حالــه )‬\n\n\n\n\n‫‪165‬‬\n\f‫توجيــه االتهــام ألربعــة مقيمــن باالشــتراك يف ســرقة عــدة محــات‬\n‫جتاريــة وذلــك بكســر أقفالهــا اخلارجيــة و إحــداث تلفيــات يف األبــواب‬\n‫و االســتيالء علــى مــا بداخلهــا مــن أمــوال ‪ ،‬حيــث ورد ملركــز الشــرطة‬\n‫عــدة بالغــات عــن الســرقه ‪ ،‬البــاغ األول‪ :‬ملواطــن يتضمــن تعــرض‬\n‫مؤسســته لكســر البــاب و الســرقه مــن داخــل املؤسســة‪ ،‬البــاغ الثانــي‪:‬‬\n‫ملقيــم يتضمــن تعــرض محــل الكفتيريــا للســرقه ‪ ،‬البــاغ الثالــث‪ :‬ملقيــم‬\n‫يتضمــن تعــرض محــل الســوبر ماركــت للســرقة‪ ،‬البــاغ الرابــع‪ :‬ملقيــم‬\n‫يتضمــن محاولــة الســرقه مــن محــل بيــع قطــع الغيــار ‪ ،‬ومت القبــض علــى‬\n‫املتهمــن األربعــة املذكوريــن مــع شــخص خامــس ( مت حفــظ االتهــام‬\n‫بحقــه لعــدم كفايــة األدلــة ) وذلــك لالشــتباه بهــم بعــد تكثيــف البحــث‬\n‫والتحــري وجمــع أكبــر قــدر مــن املعلومــات ومشــاهدة التســجيالت‬\n‫التلفزيونيــة لبعــض احملــات املســروقة‪ ،‬وبتفتيــش املذكورين والســيارة‬\n‫و بتفتيــش منزلهــم عثــر علــى بعــض املســروقات ‪ ،‬وطلــب املدعــي العــام‬\n‫إثبــات مــا أســند إليهــم واحلكــم عليهــم بحــد الســرقة ‪ ،‬وقــد أنكــر‬\n‫املدعــي عليهــم مــا نســب إليهــم ‪ ،‬وجــرى الرجــوع إلــى اعترافــات املدعــى‬\n‫عليهــم املصدقــه شــرعا ورصدهــا ‪ ،‬وصــدر احلكــم بــدرء حــد الســرقة‬\n‫الختــال شــروط القطــع ‪ ،‬وقضــت احملكمــة بتعزيــر املدعــى عليهــم‬\n         ‫بالســجن واجللــد‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪..‬‬\n\n\n\n\n                                                                                  ‫‪166‬‬\n\f      ‫احلمــد هلل أمــا بعــد فلدينــا نحــن القضــاة باحملكمــة العامــة باحملكمــة‬\n      ‫العامــة مبحافظــة األحســاء ومســاعد الرئيس‪...‬و‪.........‬وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫األحســاء برقم ‪ 3483667‬وتاريخ ‪ 1434/02/19‬هـ املقيدة باحملكمة‬\n      ‫برقــم ‪ ............‬وتاريــخ ‪ 1434/02/19‬ه ـ حضــر املدعــي العــام بدائــرة‬\n      ‫التحقيــق واإلدعــاء العــام مبحافظــة األحســاء وادعــي علــى احلاضريــن‬\n      ‫معــه ‪1‬ـ البالــغ مــن العمــر (‪ ).....‬عام ـ ًا مينــي اجلنســية مبوجــب بطاقــة‬\n      ‫بديلــه رقــم ( ‪ ) ......‬أوقــف بتاريــخ ‪1433/9/19‬ه ـ وأحيــل لشــعبة ســجن‬\n      ‫ا لديهــم برقــم (‪ ).........‬مبوجــب املــادة‬  ‫محافظــة األحســاء وســجل نزي ـ ً‬\n      ‫( ‪ ) 112‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ......... 2 .‬ـ البالــغ مــن العمــر‬\n      ‫(‪ )......‬عام ـ ًا مينــي اجلنســية مبوجــب بطاقــة بديلــه رقــم ( ‪ )....‬أوقــف‬\n      ‫بتاريــخ ‪1433/9/19‬ه ـ وأحيــل لشــعبة ســجن محافظــة األحســاء وســجل‬\n      ‫ا لديهــم برقــم (‪ )........‬مبوجــب املــادة ( ‪ ) 112‬مــن نظــام اإلجــراءات‬‫نزيـ ً‬\n      ‫اجلزائيــة ‪ ........3 .‬البالــغ مــن العمــر ( ‪ ).....‬عام ـ ًا مينــي اجلنســية مبوجــب‬\n      ‫بطاقــة بديلــه رقــم (‪ )........‬أوقــف بتاريــخ ‪1433/9/19‬ه ـ وأحيــل لشــعبة‬\n      ‫ا لديهــم برقــم (‪ )........‬مبوجــب‬     ‫ســجن محافظــة األحســاء وســجل نزي ـ ً‬\n      ‫املــادة ( ‪ ) 112‬مــن نظــام اإلجــراءات اجلزائيــة ‪ 4‬ـ البالــغ مــن العمــر ( ‪.....‬‬\n      ‫) عامـ ًا مينــي اجلنســية مبوجــب بطاقــة بديلــه رقــم ( ‪ ).........‬أوقــف بتاريــخ‬\n      ‫ا‬\n      ‫‪1433/9/19‬ه ـ وأحيــل لشــعبة ســجن محافظــة األحســاء وســجل نزيـ ً‬\n      ‫لديهــم برقــم (‪ ) ................‬مبوجــب املــادة ( ‪ ) 112‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة ‪.‬قائــا يف دعــواه إنــه بتاريــخ ‪ 1433/9/15‬ه ـ تقــدم املواطــن‬\n\n‫‪167‬‬\n\f‫‪ ......../‬ببــاغ عــن ســرقة مــن داخــل مؤسســة التجاريــة وبضبــط إفــادة‬\n‫املدعــي ذكــر أن اجلنــاة قامــوا بكســر قفــل البــاب و زحزحتــه والدخــول‬\n‫إلــى داخــل املؤسســة كمــا ذكــر بــأن املســروقات عبــارة عــن صنــدوق‬\n‫بداخلــه مبلــغ ( ‪ )4000‬أربعــة آالف ريــال وآلــة احملاســبة ( الكاشــير )‬\n‫وبداخلهــا ( ‪ )1000‬ألــف ريال‪.‬ومبعاينــة املوقــع تبــن وجــود آثــار تكســير‬\n‫وزحزحــت البــاب اخلارجــي باســتخدام آلــة صلبــة ‪ -‬كمــا شــوهدت آثــار‬\n‫ملــكان الصنــدوق وآلــة احملاســبة املســروقتني‪ .‬وبتاريــخ ‪1433/9/16‬‬\n‫ه ـ تقــدم املقيــم ‪ ......../‬ببــاغ عــن ســرقة مــن داخــل كفتيريــا ‪........‬‬\n‫وبضبــط إفــادة املدعــي ذكــر بــأن البــاب اخلارجــي للمحــل قــد مت‬\n‫كســره وان مــا ســرق هــو آلــة احملاســبة وبداخلهــا مبلــغ ( ‪ )4000‬أربعــة‬\n‫آالف ريــال وإقامتــن وخمــس بطاقــات صحيــة ومفتــاح ســيارة ‪........‬‬\n‫ومفتــاح ســيارة ‪ ........‬وجوالــن‪ .‬ومبعاينــة املوقــع تبــن وجــود اثــر تكســير‬\n‫البــاب اخلارجــي بالكامــل وشــوهد أثــر مــكان آلــة احملاســبة املســروقة‬\n‫وبتاريــخ ‪1433/9/17‬ه ـ تقــدم املقيــم ‪ ........ /‬ببــاغ عــن ســرقة محــل‬\n‫( ســوبر ماركــت )‪ ،‬وبضبــط إفــادة املدعــي أفــاد بــأن اجلنــاة قامــوا‬\n‫بكســر بــاب احملــل وســرقة آلــة احملاســبة بهــا مبلــغ مــن املــال وبطاقــات‬\n ‫شــحن هاتفيــة تقــدر قيمتهــا ب ـ ( ‪ )130.000‬مئــة وثالثــون ألــف ريــال ‪.‬‬\n‫ومبعاينــة املوقــع تبــن تكســير زجــاج البــاب اخلارجــي وشــوهد أثــر‬\n‫مــكان آلــة الكاشــير املســروقة وبتاريــخ ‪1433/9/18‬ه ـ تقــدم املقيــم‬\n‫‪ - ....‬ببــاغ عــن محاولــة ســرقة محــل قطــع غيــار مبحطــة ‪ ........‬بطريــق‬\n‫الصناعيــة وبضبــط إفــادة املدعــي ذكــر بــأن اجلنــاة قامــوا بكســر بــاب‬\n‫احملــل فشــاهدهم عامــل احملطــة فــاذوا بالفــرار ولــم يقومــوا بســرقة‬\n‫شــيء ومبعاينــة املوقــع تبــن وجــود تكســير زجــاج البــاب اخلارجــي ‪ .‬وقــد‬\n\n\n                                                                                     ‫‪168‬‬\n\f              ‫مت القبــض علــى املتهمــن املذكوريــن مــع شــخص خامــس يدعــى‬\n      ‫‪ (........ /‬مت حفــظ االتهــام ملواجهتــه لعــدم كفايــة األدلــة ) وذلــك‬\n      ‫لالشــتباه بهــم بعــد تكثيــف البحــث والتحــري وجمــع اكبــر قــدر مــن‬\n      ‫املعلومــات ومشــاهدة التســجيالت التلفزيونيــة لبعض احملالت املســروقة‬\n      ‫وبتفتيــش املذكوريــن وتفتيــش الســيارة وتفتيــش منزلهــم عثــر علــى‬\n      ‫املضبوطــات التاليــة‪1‬ـ ( محفظــة لونهــا بيــج بداخلهــا مبلــغ ( ‪ )304‬ريــال‬\n      ‫‪ +‬مفتــاح منــزل ‪ +‬بطاقــة تأمــن ‪ +‬بطاقــة صــراف ‪ + .....‬كــرت حســاب‬\n      ‫‪ .....‬باســم ( ‪ + ) ........‬رخصــة إقامــة ‪ +‬كــرت شــحن عــدد ( ‪ + ) 3‬بطاقــة‬\n      ‫‪ ...‬عــدد (‪ 2 )1‬ـ محفظــة لونهــا بيــج بداخلهــا مبلــغ ( ‪ )1950‬ريــال ‪+‬‬\n      ‫كــرت بطاقــة ‪ + .....‬بطاقــة صــراف ‪ .....‬باســم (‪+ )........................‬‬\n      ‫بطاقــة ‪ .....‬للتأمــن ‪ +‬كــرت اتصــال ‪ + .....‬كــرت اتصــال ‪ .....‬عــدد (‪)2‬‬\n      ‫‪ +‬بطاقــة شــخصية باســم ( ‪ + )..................‬صــورة شــخصية ‪ +‬بطاقــة ‪.....‬‬\n      ‫عــدد ( ‪ 3 . )5‬ـ محفظــة لونهــا بنــي بداخلهــا كــرت ‪ .....‬عــدد (‪+ )2‬‬\n      ‫بطاقــة شــحن ‪ .....‬فئــة عشــرة ريــال عــدد (‪ 4 . )4‬ـ عــدد (‪ )6‬جــواالت ‪.....‬‬\n      ‫‪ +‬جــوال ‪ + .....‬بطاقــة شــحن ‪ .....‬فئــة (‪ )50‬ريــال عــدد (‪ )3‬وفئــة (‪)10‬‬\n      ‫عــدد (‪ )3‬وفئــة (‪ )20‬عــدد (‪ + )1‬بطاقــة شــحن ‪ .....‬فئــة ( ‪ )100‬عــدد (‪)1‬‬\n      ‫وفئــة (‪ )30‬عــدد (‪ )20‬وفئــة (‪ )20‬عــدد (‪ + )2‬نظــارة شمســية ‪ +‬مبلــغ‬\n      ‫(‪ )77‬ريــال ‪ +‬مبلــغ دينــار بحرينــي ‪ +‬عــدد (‪ )3‬مفــك (ســكروب ) لونــه‬\n      ‫احمــر ‪ +‬عــدد ( ‪ )3‬مطــارق ‪ +‬أداة صلبــة ( ســيخ ) ‪ +‬عــدد (‪ )2‬أداة صلبــة‬\n      ‫( ليــور ) ـ مبلــغ ( ‪ )4738‬ريــال ‪ +‬ورقــة نقديــة فئــة عشــر آالف ليــرة لبنانيــة‬\n      ‫‪ +‬ورقــة نقديــة فئــة ربــع دينــار ‪ +‬ورقــة نقديــة فئــة نصــف ريــال عمانــي ‪+‬‬\n      ‫ورقــة نقديــة فئــة خمســة آالف روبيــه اندونيســية ‪ +‬ورقــة نقديــة فئــة الــف‬\n      ‫دولــة فتنــام ‪ +‬ورقــة نقديــة فئــة مائــة عملــة غيــر معروفــة بطاقــات شــحن‬\n\n\n‫‪169‬‬\n\f‫اتصــال ‪ .....‬فئــة ( ‪ )50‬ريــال عــدد (‪ )6‬وفئــة ( ‪ )20‬عــدد (‪ )15‬وفئــة (‪)10‬‬\n‫ريــال عــدد (‪ )30‬ـ بطاقــات شــحن ‪ .....‬فئــة (‪ )20‬عــدد (‪ )6‬ريــال وفئــة‬\n‫(‪ )10‬ريــال عــدد (‪ )7‬ـ بطاقــات شــحن اتصــال ‪ .....‬فئــة (‪ )30‬عــدد ( ‪)9‬‬\n‫ـ بطاقــة شــحن ‪ .....‬فئــة (‪ )50‬ريــال عــدد ( ‪ )6‬أكيــاس صغيــرة بداخلهــا‬\n‫مــادة ( الشــمه ) ( فــرزت لهــا اوراق مســتقلة و عولــج موضوعهــا مــن قبــل‬\n‫شــرطة األحســاء) جــوال ‪ .....‬بطاقــات شــحن اتصــال ‪.....‬فئــة (‪ )50‬ريــال‬\n‫عــدد (‪ )3‬برقــم التسلســل (‪ ).....‬ورقم(‪).....‬ورقم(‪).....‬وهــي مطابقــة‬\n‫لتسلســل البطاقات املســروقة من ســوبر ماركت ‪ ...............‬ومبشــاهدة‬\n‫التســجيل التلفزيونــي لعمليــة ســرقة مؤسســة ومحــل ‪ ..............‬و ســوبر‬\n‫ماركت تبني أن الشــخصني الذين مت تصويرهما أثناء ســرقة احملالت‬\n‫املذكــورة همــا املتهمــن‪-‬و وبعــرض التســجيل املرئــي علــى املتهمــن‬\n‫اقــروا بأنهــم هــم األشــخاص الذيــن تظهــر صورهــم يف التســجيل وان‬\n‫احملــات املصــورة هــي التــي قامــوا بســرقتها فيمــا بعــد ارشــدوا جهــة‬\n‫التحقيــق علــى تلــك احملــات وقــد مت تســليم بعــض الضبوطات املســروقة‬\n‫الــى اصحابهــا وباســتجواب املدعــى عليــه الرابــع‪ -‬اقــر و صــدق إقــراره‬\n‫شــرعا مبــا يلــي( قمــت مــع و و بســرقة بقالــة ‪ ..............‬علــى طريــق‬\n‫الصناعيــة حيــث إن مــن قــام بكســر البقالــة والســرقة منهــا كل مــن و‬\n‫وكنــت انــا وبالســيارة‪ ،‬كمــا قمــت باالشــتراك مــع و مبحاولــة ســرقة‬\n‫محــل قطــع غيــار حيــث قمــت أنــا و بالنــزول للمحــل وقــام بكســر قفــل‬\n‫احملــل فحضــر احــد األشــخاص وهربنــا دون أن نقــوم بالســرقة )‬\n‫وباســتجواب املدعــى عليــه األول ‪ /‬اقــر وصــدق إقــراره شــرعا مبــا يلــي (‬\n‫قمــت انــا وزمالئــي باالشــتراك بســرقة محــل ‪ ..............‬حيــث قمــت انــا‬\n‫وا بكســر البــاب بحديــدة وقمنــا بالدخــول وســرقت انــا جوالــن وســرق‬\n\n\n                                                                                   ‫‪170‬‬\n\f      ‫صنــدوق الكاشــير ثــم خرجنــا وكان ‪ .....‬يقــود الســيارة وكان يقــوم‬\n      ‫باملراقبــة و وكان ذلــك وقــت االفطــار‪ -‬يف اليــوم التالــي قمنــا بســرقة‬\n      ‫ســوبر ماركــت ‪ ..............‬حيــث قمــت انــا و بدفــع البــاب والدخــول ألن‬\n      ‫القفــل كان مفتــوح وســرقنا مبلــغ مالــي قــدره عشــرة آالف وعدد كبير‬\n      ‫مــن بطاقــات الشــحن وصنــدوق الكاشــير وكان بقيــة زمالئنــا يف‬\n      ‫الســيارة) وباســتجواب املدعــى عليــه الثانــي اقــر وصــدق اقــراره شــرعا‬\n      ‫مبــا يلــي ‪ :‬أثنــاء وجــودي يف مدينــة الريــاض طلــب منــي مرافقتــه إلــى‬\n      ‫مدينــة االحســاء مــن اجــل ســرقة محــات جتاريــة وقــد قــام بالتخطيــط‬\n      ‫للســرقة وحضرنــا ملدينــة االحســاء يف تاريــخ ‪ 1433/9/15‬ه ـ ويف نفــس‬\n      ‫اليــوم قمنــا بســرقة محــل وكنــت انــا اقــود الســيارة امــا الباقــن فنزلــوا‬\n      ‫مــن الســيارة وقامــوا بكســر احملــل وســرقة صنــدوق الكاشــير ثــم ٌ قمنــا‬\n      ‫بالفــرار مــن املوقــع وعنــد فتــح الكاشــير وجدنــا مبلــغ ( ‪ )4000‬اربعــة‬\n      ‫آالف ريــال ‪ ،‬ويف اليــوم التالــي قمنــا بســرقة محــل حلــوم ‪..................‬‬\n      ‫حيــث كنــت انــا اقــود الســيارة وقــام كل مــن و بالنــزول للمحــل وقامــوا‬\n      ‫بكســره وقامــوا بســرقة جوالــن ‪ -‬ويف اليــوم التالــي قمنــا بســرقة ســوبر‬\n      ‫مــا ركــت علــى طريــق الصناعيــة حيــث كنــت أنــا أقــود الســيارة وقــام‬\n      ‫‪ .....‬بكســر قفــل احملــل وســرقة صنــدوق كاشــير بــه مبلــغ عشــرة آالف‬\n      ‫ريــال وعــدد مــن بطاقــات الشــحن‪-‬ويف اليــوم الــذي يليــه قمنــا مبحاولــة‬\n      ‫ســرقة محــل قطــع غيــار أنــا و و حيــث قــام و بالنــزول وكســر احملــل‬\n      ‫وقــام أشــخاص باللحــاق بهــم فهربنــا وباســتجواب املدعــى عليــه الثالــث‬\n      ‫‪ ........ /‬اقــر وصــدق اقــراره شــرعا ملــا يلــي قمــت انــا وزمالئــي بســرقة‬\n      ‫ســوبر ماركــت حيــث قــام بكســر القفــل وقمنــا بالدخــول ولــم نعثــر‬\n      ‫علــى أي مبلــغ مــا لــي ‪ ،‬ويف اليــوم التالــي قمــت انــا و‪ ........‬و بســرقة محــل‬\n\n\n‫‪171‬‬\n\f‫يدعــى ‪ ،..................‬حيــث قــام ‪ .....‬بكســر قفــل احملــل ودخلــت انــا‬\n‫وإيــاه وســرقنا صنــدوق الكاشــير حيــث حملتــه انــا وقــام ‪ .....‬بســرقة‬\n‫جوالــن وقــد أســفر التحقيــق معهــم عــن توجيــه االتهــام لهــم باالشــتراك‬\n‫يف ســرقة عــدة محــات جتاريــة وذلــك بكســر اقفالهــا اخلارجيــة‬\n‫وإحــداث تلفيــات يف األبــواب واالســتيالء علــى مــا بداخلهــا مــن امــوال‬\n‫وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬إقرارهــم املصــدق شــرعا مبــا نســب‬\n‫إليهــم واملــدون علــى الصفحــات رقــم ( ‪ 8‬ـ ‪ ) 16‬مــن ملــف التحقيــق رقــم‬\n‫(‪ -2 )8‬محاضــر تنفيــذ مهمــة املنــوه عنهــا واملرفقــة علــى الصفحــات رقــم‬\n‫(‪-3 ) 27 ، 11،16، 2‬محاضــر املعاينــة املنــوه عنهــا واملدونــة علــى‬\n‫الصفحــات رقــم ( ‪) 3 ، 2‬مــن ملفــات التحقيــق رقــم ( ‪) 4، 3 ، 2 ، 1‬‬\n‫‪ -4‬مــا جــاء يف محاضــر التفتيــش املنــوه عنهــا واملرفقــة علــى اللفــات رقــم‬\n‫(‪ )40 ، 39 ، 38‬والعثــور علــى املســروقات بحوزتهــم قرينــة قاطعــة علــى‬\n‫صحــة االتهــام ‪ -5 .‬محضــر العــرض املنــوه عنــه واملــدون علــى الصفحــات‬\n‫رقــم ( ‪ ) 2 ، 1‬مــن ملــف التحقيــق رقــم ( ‪ -6) 7‬محضــر االرشــاد املنــوه‬\n‫عنــه واملــدون علــى الصفحــات رقــم (‪ ) 16 ، 15‬مــن ملــف التحقيــق رقــم‬\n‫(‪ -7)6‬محضــر املشــاهدة املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)9‬‬\n‫مــن ملــف التحقيــق رقــم (‪ -8)5‬محضــر تعــرف املتهــم علــى صورتــه يف‬\n‫التســجيل املرئــي املــدون يف الصفحــة رقــم (‪ )15‬مــن ملــف التحقيــق رقــم‬\n‫(‪ .)5‬وبالبحــث عــن ســوابقهم لــم يعثــر لهــم علــى ســوابق جنائيــة مســجلة‬\n‫وحيــث إن مــا أقــدم عليــه املذكــورون فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫وهــو ســرقة مــال محتــرم مــن حــرزه بعــد هتكــه يزيــد عــن النصــاب‬\n‫الشــبهة لهــم فيــه وطالــب به صاحبــه ولكونهم مكلفني غير مكرهني‬\n‫وقــد انتشــر يف البــاد إقــدام البعــض مــن الوافديــن مــن إنتهــاك حرمــة‬\n\n\n                                                                                     ‫‪172‬‬\n\f      ‫العبــاد والبــاد ممــا يتطلــب الــردع والزجــر إلعــادة هيبــة األمــن لــذا‬\n      ‫أطلــب إثبــات مــا اســند إليهــم واحلكــم عليهــم بحــد الســرقة الــوارد يف‬\n      ‫اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة (علم ـ ًا بــأن احلــق اخلــاص ال‬\n      ‫يــزال قائم ـاً) وبــاهلل التوفيــق هــذه دعــواي وبســؤال املدعــي عليهــم‬\n      ‫اإلجابــة أجــاب املدعــى عليــه األول بقولــه مــا ذكــر املدعــي العــام بعضــه‬\n      ‫صحيــح وبعضــه غيــر صحيــح فالصحيــح اننــي دخلــت إلــى بقالــة ‪ .....‬وقــد‬\n      ‫كان بابهــا مغلقــا لكنــه غيــر مقفــل ففتحتــه ودخلــت وســرقت عشــرة‬\n      ‫آالف ريــال كانــت موجــودة يف درج الطاولــة وهــو غيــر مقفــل كمــا‬\n      ‫قمــت بكســر زجــاج بــاب مؤسســة‪ ........‬التجاريــة حيــث كان البــاب‬\n      ‫مقفــل ودخلــت ووجــدت صنــدوق وقمــت بســرقته وملــا فتحتــه وجــدت فيــه‬\n      ‫أربعــة آآلف ريــال كمــا دخلــت كفتريــا ‪..................‬حيــث كان بابهــا‬\n      ‫مفتــوح وســرقت جهــازي جــوال كانــت موضوعــة علــى طاولــة وقــد كان‬\n      ‫يرافقنــي يف هــذه الســرقات الثــاث املدعــى عليــه ومــا زاد عــن مــا‬\n      ‫ذكرتــه فغيــر صحيــح كمــا أجــاب املدعــى عليــه الثانــي بقولهمــا‬\n      ‫ذكــره املدعــي العــام كلــه غيــر صحيــح فلــم أســرق أي شــيء ولــم‬\n      ‫أشــترك مــع البقيــة يف الســرقة كمــا اجــاب املدعــى عليــه الثالــث بقولــه‬\n      ‫دخلــت بقالــة ‪ ........‬مــع املدعــى عليــه األول وقــد كان بابهــا مغلقــا وعليــه‬\n      ‫قفــل لــم يقفــل وأخــذ مبلــغ عشــرة آالف ريــال وأعطانــي نصفهــا ثــم ذهبنــا‬\n      ‫إلــى محــل مؤسســة‪ ........‬التجاريــة وكســر البــاب وســرق الصنــدوق‬\n      ‫ووجدنــا فيــه أربعــة آالف ريــال واعطانــي نصفهــا ودخلــت معــه كفتريــا‬\n      ‫‪..................‬وســرق جوالــن أخذتهــا منــا الشــرطة هــذا مــا فعلتــه ومــا زاد‬\n      ‫عــن ذلــك يف دعــوى املدعــي العــام فغيــر صحيــح كمــا أجــاب املدعــى‬\n      ‫عليــه الرابــع بقولــه مــا ذكــره املدعــي العــام كلــه غيــر صحيــح فلــم‬\n\n\n‫‪173‬‬\n\f‫أســرق أي شــيء ولــم أشــارك البقيــة يف الســرقة هكــذا أجــاب‬\n‫وبعرضذلــك علــى املدعــي العــام وســؤاله البينــة قــال لــدي بينــة‬\n‫ســأحضرها يف اجللســة القادمــة‪ ،‬ثــم يف جلســة أخــرى بتاريــخ‬\n‫‪1434/3/15‬ه ـ مت ســؤال املدعــي العــام هــل أحضــر البينــة قــال ليــس‬\n‫لــدي بينــة ســوى مــا جــاء يف أوراق الدعــوى واعترافــات املدعــى عليهــم ثــم‬\n‫جــرى اإلطــاع علــى إقــرار واعتــراف املدعــى عليــه األول املصــدق شــرعا‬\n‫املــدون علــى الصحيفــة رقــم ‪ 9.8‬مــن دفتــر التحقيــق لفــة ‪32‬ونصــه <<‬\n‫أقــرر أنــا املدعــو‪ ........‬وأنــا بكامــل قــواي العقليــة واملعتبــرة شــرع ًا‬\n‫وبطوعــي واختيــاري ودون إكــراه مــن احــد بــأن قبــل فتــرة خمســة أيــام‬\n‫حضــرت أنــا ويرافقنــي كل مــن املدعــو‪ ........‬و‪ ........‬و‪ ........‬مــن مدينــة‬\n‫الريــاض وكنــت اســتقل ســيارة ‪ ........‬لونهــا ‪ ........‬موديــل ‪ ........‬وكان‬\n‫يقودهــا املدعــو‪ ........‬وقمنــا بالســكن يف شــقة مفروشــة علــى طريــق‬\n‫الريــاض وأثنــاء ذلــك قمنــا يف البدايــة بســرقة محــل ‪..................‬حيــث‬\n‫قمــت انــا و بكســر البــاب بحديــده ليــور ومــن ثــم قمنــا بالدخــول للمحــل‬\n‫وســرقنا عــدد ‪ 2‬جــوال قمــت بســرقتها أنــا‪ ،‬وقــام بســرقة صنــدوق‬\n‫الكاشــير ثــم قمنــا بعــد ذلــك باخلــروج مــن احملــل حيــث كان املدعــو‬\n‫يقــود الســيارة وكل مــن املدعــو‪ ........‬و‪ ........‬باملراقبــة وكان ذلــك وقــت‬\n‫االفطــار‪ ،‬ويف يــوم التالــي قمنــا بســرقة ســوبر ماركــت حيــث قمــت أنــا‬\n‫واملدعــو‪ ........‬بالدخــول حيــث كان القفــل مفتــوح وقمنــا برفــع البــاب‬\n‫ومــن ثــم الدخــول وقمنــا بســرقة مبلــغ مالــي وقــدره عشــرة آالف ريــال‬\n‫وكذلــك عــدد كبيــر مــن بطاقــات الشــحن حيــث قــام بحمــل صنــدوق‬\n‫الكاشــير ومــن ثــم قمنــا باخلــروج وكان كل مــن‪ ........‬و‪ ........‬و‬\n‫‪ ........‬بالســيارة ومــن ثــم قمنــا بارتــكاب الفــرار كمــا أقــر بأننــا لــم نقــم‬\n\n\n                                                                                          ‫‪174‬‬\n\f      ‫بســرقة أي محــل آخــر كمــا أقــر بأنــه مت القبــض علينــا مــن قبــل البحــث‬\n      ‫اجلنائــي وقــت اإلفطــار بعــد خروجنــا مــن الصناعيــة وهــذا إقــرار منــي‬\n      ‫وعليــه جــرى التوقيــع>> ‪ ،‬كمــا مت اإلطــاع علــى إقــرار واعتــراف‬\n      ‫املدعــى عليــه الثانــي املصــدق شــرعا املــدون علــى الصحيفــة رقــم‬\n      ‫‪ 14،13،12‬مــن نفــس دفتــر التحقيــق ونصــه << قــرر أنــا املدعــو رقــم‬\n      ‫بطاقــة بديلــه (‪ )......‬أقــر واعتــرف وأنــا بكامــل قــواي العقليــة واملعتبــرة‬\n      ‫شــرع ًا وبطوعــي واختيــاري ودون إكــراه أو إجبــار مــن أحــد بأنــه أثنــاء‬\n      ‫وجودنــا يف مدينــة الريــاض طلــب منــا املدعــو منــا مرافقتــه إلــى مدينــة‬\n      ‫األحســاء مــن أجــل ســرقة محــات جتاريــة وبالفعــل قمــت أنــا ويرافقنــي‬\n      ‫كل مــن املدعــو‪ ........‬وكذلــك الوافــد‪ ........‬وكذلــك‪ ........‬حيــث قــام‬\n      ‫بالتخطيــط للســرقة وحضورنــا إلــى مدينــة األحســاء هــو املدعــو وبالفعــل‬\n      ‫حضرنــا إلــى األحســاء يف تاريــخ ‪1433/9/15‬ه ـ صباح ـ ًا وقمنــا‬\n      ‫باســتئجار شــقة يف شــارع الريــاض ويف نفــس اليــوم يف حوالــي الســاعة‬\n      ‫الســابعة مســاء قمــت أنــا ويرافقنــي كل مــن وكذلــك بالذهــاب إلــى‬\n      ‫محــل‪ ........‬ال أعلــم أيــن بالضبــط ولكــن اتضــح انــه محــل لــأدوات‬\n      ‫الصحيــة وذلــك بعــد االســتدالل عليــه مــن قبــل البحــث اجلنائــي حيــث‬\n      ‫كنــت أنــا مــن يقــود الســيارة وقــام كل مــن املرافقــن لــي بالنــزول‬\n      ‫وكســر احملــل وســرقة صنــدوق الكاشــير وبعدهــا قمنــا بالفــرار مــن‬\n      ‫املوقــع وأثنــاء فتــح الكاشــير يف الســيارة اتضــح وجــود مبلــغ مالي وقدره‬\n      ‫أربعــة آالف ريــال وكانــت بحــوزة املدعــو‪ ........‬وبعــد ذلــك قــام برمــي‬\n      ‫الكاشــير مــن الســيارة أثنــاء ســيرها يف مــكان ال اعرفــه ويف اليــوم‬\n      ‫التالــي وهــو يــوم الســبت املوافــق ‪1433/9/16‬ه ـ يف حوالــي الســاعة‬\n      ‫السادســة والنصــف وقــت اإلفطــار قمنــا بالذهــاب إلــى محــل ال أعــرف‬\n\n\n‫‪175‬‬\n\f‫اســمه ولكــن اســتطعت مــن التعــرف عليــه بعــد االســتدالل مــن قبــل‬\n‫البحــث اجلنائــي واتضــح بأنــه محــل حلــوم ‪..................‬يف ‪ ........‬وهــو نفــس‬\n‫احملــل الــذي قمنــا بســرقته وكان يرافقنــي كل مــن‪........‬و‬\n‫واملدعــو‪ ........‬حيــث كنــت أنــا مــن يقــود الســيارة وقــام كل مــن‪........‬‬\n‫وكذلك ‪ ........‬بالنزول إلى احملل وكســره وســرقة صندوق الكاشــير‬\n‫وعــدد ‪ 2‬جــوال وبعــد ذلــك قمنــا بارتــكاب الفــرار وأخبرنــا بأنــه اليوجــد‬\n‫بالصنــدوق ســوى مبلــغ مالــي وقــدره ‪ 100‬ريــال وقمنــا برمــي صنــدوق‬\n‫الكاشــير مــن الســيارة ‪ ،‬ويف اليــوم التالــي املوافــق ليــوم األحــد‬\n‫‪1433/9/17‬ه ـ ذهبــت أنــا واملدعــو‪ ........‬و‪ ........‬و‪ ........‬وقمنــا بســرقة‬\n‫ســوبر ماركــت علــى طريــق الصناعيــة حيــث كنــت أنــا مــن يقــود‬\n‫الســيارة وقــام و‪ ................‬بكســر قفــل احملــل والدخــول وســرقة‬\n‫صنــدوق الكاشــير يحتــوي علــى مبلــغ مالــي وقــدره عشــرة آالف ريــال‬\n‫وكذلــك عــدد كبيــر مــن بطاقــات الشــحن ســوا وموبايلــي ويف اليــوم‬\n‫التالــي يــوم االثنــن املوافــق ‪1433/9/18‬ه ـ قمنــا بالذهــاب إلــى طريــق‬\n‫الصناعيــة وكان ذلــك وقــت الســحور حوالــي الســاعة الثالثــة والنصــف‬\n‫فجــرا وقمنــا بالتوقــف عنــد محــل لبيــع قطــع الغيار حيــث كان يرافقني‬\n‫املدعــو‪ ........‬و‪ ........‬حيــث قــام كل مــن‪ ........‬و‪ ........‬بالنــزول وقامــوا‬\n‫بكســر احملــل وقــام أشــخاص باحلــاق بهــم ومــن ثــم قمنــا بارتــكاب‬\n‫الفــرار حيــث إنــي كنــت متوقــف عنــد وكالــة ‪ ........‬وهــذا إقــرار‬\n‫واعتــراف منــي مبــا قمنــا بــه منـ ُـذ حضورنــا مــن مدينــة الريــاض حيــث‬\n‫إننــا كنــا قادمــن مــن اجــل الســرقة حســب تخطيــط املدعــو وحــن مــا‬\n‫مت القبــض علينــا مــن قبــل البحــث اجلنائــي يف يــوم الثالثــاء املوافــق‬\n‫‪1433/9/19‬ه ـ بالصناعيــة حيــث مت القبــض علينــا وقــت اإلفطــار‬\n\n\n                                                                                          ‫‪176‬‬\n\f      ‫حوالــي الســاعة السادســة والنصــف قبــل قيامنــا بالســرقة وهــذا أقــرار‬\n      ‫واعتــراف منــي بذلــك وعليــه أوقــع‪ .‬كمــا مت اإلطــاع علــى إقــرار‬\n      ‫واعتــراف املدعــى عليــه املدعــى الثالــث املــدون علــى الصحيفــة رقــم‬\n      ‫‪ 16،15‬مــن نفــس دفترالتحقيــق ونصــه << أقــر انــا املدعــو‪ ........‬بطاقــة‬\n      ‫بديلــة رقــم‪ ........‬واعتــرف وانــا بكامــل قــواي العقليــة واملعتبــرة شــرعا‬\n      ‫وبطوعــي واختيــاري ودون اكــراه مــن أحــد بأنــه حضرنــا مــن مدينــة‬\n      ‫الريــاض يــوم اجلمعــة املوافــق ‪1433/9/15‬ه ـ وقمنــا بالســكن يف شــقة‬\n      ‫مفروشــة علــى طريــق الريــاض وكان يرافقنــي كل مــن املدعــو واملدعــو‬\n      ‫و‪ ........‬و‪ ........‬وبعــد ذلــك قمنــا باالشــتراك مــع املدعــو و حيــث قمــت انــا‬\n      ‫و‪ ........‬والوافــد اليمنــي‪ ........‬حيــث قمنــا بســرقة ســوبر ماركــت حيــث‬\n      ‫قــام بكســر القفــل وقمنــا بالدخــول ولــم نعثــر علــى أي مبلــغ مالــي ويف‬\n      ‫نفــس اليــوم التالــي قمــت انــا و‪ ........‬و‪ ........‬وبســرقة محــل يدعــى حلــوم‬\n      ‫‪..................‬حيــث قــام املدعــو بكســر القفــل وقمــت انــا واملذكــور‬\n      ‫بالدخــول وقمنــا بســرقة الكاشــير صنــدوق احملــل حيــث قمــت انــا‬\n      ‫بحملــه وقــام بســرقة جوالــن هــذا مــا قمــت بــه واالشــتراك فيــه مــع‬\n      ‫زمالئــي حيــث انــه توجــد ســرقات لــم اقــم باالشــتراك معهــم وهــذا اقــرار‬\n      ‫منــي وعليــه جــرى التوقيــع ‪ ،‬كمــا مت اإلطــاع علــى إقــرار واعتــراف‬\n      ‫املدعــى عليــه الرابــع املصــدق شــرعا املــدون علــى الصحيفــة رقــم ‪ ...‬مــن‬\n      ‫دفتــر التحقيــق لفــة رقــم ‪ 35‬ونصــه << أقــر انــا املدعــو بطاقــة بديلــة رقــم‬\n      ‫‪ ......‬وانــا بكامــل قــواي العقليــة واملعتبــرة شــرعا وبــدون إكــراه أو‬\n      ‫إجبــار مــن أحــد بأنــي قمــت باالشــترك مــع املدعــو واملدعــو واملدعــو‬\n      ‫بســرقة بقالــة ‪.....‬علــى طريــق الصناعيــة حيــث ان مــن قــام بكســر‬\n      ‫البقالــة والســرقة منهــا كل مــن و وكنــت انــا بالســيارة برفقــة املدعــو‬\n\n\n‫‪177‬‬\n\f‫كمــا أقــر بانــي قمــت باالشــتراك مــع املدعــو مبحاولــة ســرقة محــل‬\n‫قطــع غيــار حيــث قمــت انــا واملدعــو بالنــزول للمحــل وقــام بكســر قفــل‬\n‫احملــل حيــث حضــر احــد األشــخاص وقمنــا بارتــكاب الفــرار دون ان‬\n‫نقــوم بســرقة احملــل وبعــد ذلــك قمنــا بالذهــاب إلــى الشــقة وهــذا اقــراري‬\n‫وعليــه جــرى التوقيــع‪ .‬وبعــرض هــذه االعترافــات علــى املدعــى عليهــم‬\n‫أجــاب األول بقولــه هــذا االعتــراف صحيــح لكــن لــم يشــارك معنــا‬\n‫املدعــى عليهمــا وكمــا أجــاب املدعــى عليــه الثاني بقوله هــذا االعتراف‬\n‫غيرصحيــح وقــد أخــذ منــي حتــت اإلكــراه والضــرب كمــا أجــاب‬\n‫املدعــى عليــه الثالــث بقولــه هــذا االعتــراف صحيــح لكــن لــم يشــارك‬\n‫معنــا املدعــى عليهمــا و كمــا أجــاب املدعــى عليــه الرابــع بقولــه هــذا‬\n‫االعتــراف غيــر صحيــح وقــد أخــذ منــي حتــت اإلكــراه والضربثــم يف‬\n‫جلســة أخــرى فلــدي أنــا وبنــاء علــى قــرار معالــي رئيــس املجلــس األعلــى‬\n‫للقضــاء برقــم يف ‪1434/4/23‬ه ـ بتعينــي قاضيـ ًا يف احملكمــة العامــة‬\n‫باألحســاء وبنــاء علــى تكليفــي مــن قبــل فضيلــة رئيــس احملكمــة برقم‬\n‫يف ‪1434/4/24‬ه ـ للقيــام بعمــل املكتــب القضائــي الســابع لكونــي‬\n‫خلفـ ًا لفضيلــة القاضــي‪ ........‬لــذا جــرى إكمــال نظــر هــذه القضيــة مــن‬\n‫قبلــي مــع أصحــاب الفضيلــة املشــاركني معــي مســاعد الرئيــس الشــيخ‬\n‫‪ ........‬والشــيخ ‪ ........‬فقــد جــرى ســؤال املدعــى عليــه هــل كســر البــاب‬\n‫ا لــم يكــن‬     ‫ا فأجــاب قائ ـ ً‬‫احلديــد ملؤسســة حينمــا كان البــاب مقف ـ ً‬\n‫هنــاك ســوى بــاب زجــاج فقــط يف املؤسســة ولــم يكــن هنــاك بــاب حديــد‬\n‫وقــد كســرت بــاب الزجــاج ثــم دخلــت املؤسســة هــذه إجابتــي ثــم جــرى‬\n‫ســؤال املدعــى عليــه الثالــث عــن بــاب الكفتريــا يف محــل ‪..................‬‬\n‫التــي دخلهــا هــل كان مفتوح ـ ًا فأجــاب نعــم كان مفتوحــا ولــم يكــن‬\n\n\n                                                                                     ‫‪178‬‬\n\f      ‫مغلقـ ًَا هــذه إجابتــي ثــم جــرى ســؤال املدعــى عليــه الثانــي هــل لديــه بينــة‬\n      ‫ا ليــس لــدي بينــة ســوى أننــي‬   ‫علــى اإلكــراه علــى إقــراره فأجــاب قائ ـ ً‬\n      ‫تعرضــت للضــرب واحلبــس اإلنفــرادي وأخبرنــي احملقــق بــأن أوقــع علــى‬\n      ‫األوراق لكــي أخــرج مــن احلبــس وبســؤال املدعــى عليــه الرابــع هــل لديــه‬\n      ‫البينــة علــى اإلكــراه علــى إقــراره فأجــاب بقولــه ليــس لديــه بينــة ســوى‬\n      ‫أننــي تعرضــت للضــرب واحلبــس اإلنفــرادي وأخبرنــي احملقــق بــأن أوقــع‬\n      ‫علــى األوراق لكــي أخــرج مــن احلبــس هكــذا أجــاب‪ .‬ولتأمــل ودراســة‬\n      ‫القضيــة رفعــت اجللســة‪ ،‬ثــم يف جلســة أخــرى وبعــد تأمــل ودراســة أوراق‬\n      ‫املعاملــة وبعــد االطــاع علــى وجهــة نظــر فضيلــة العضــو القضائــي‬\n      ‫املشــارك الشــيخ ‪ ........‬ولكــون املدعــى عليــه األول واملدعــى عليــه‬\n      ‫الثالــث قــد أقــر كل واحــد منهمــا وهمــا بكامــل قواهمــا العقليــة‬\n      ‫واملعتبــرة شــرع ًا وبطوعهمــا واختيارهمــا دون إكــرا ٍه مــن أحــد أنهمــا‬\n      ‫ســرقا مــن مــال محتــرم ليــس لهمــا فيــه شــبهة ولكــون مــا أقدمــا عليــه‬\n      ‫فعــل محــرم معاقــب عليــه شــرع ًا ولكــون هــذا املــال أخــرج مــن غيــر‬\n      ‫حــرزه املعتبــر شــرع ًا وذلــك لكــون البــاب الــذي كســره املدعــى عليــه‬\n      ‫األول يف مؤسســة التجاريــة وســرق منــه مبلــغ أربعــة آالف ريــال مــن زجاج‬\n      ‫وهــو يف العــادة والعــرف ليــس بحــرز حتفــظ فيــه مثــل هــذه األمــوال حيــث‬\n      ‫إن العــرف املتعــارف عليــه أن يكــون البــاب مــن حديــد وقــد اتفق الفقهاء‬\n      ‫علــى اعتبــار العــرف يف احلــرز والرجــوع فيــه إلــى أهلــه ‪ ،‬قــال اإلمــام ابــن‬\n      ‫قدامــة رحمــه اهلل يف املغنــي (‪:)250/10‬واحلــرز مــا عــد حــرز ًا يف العــرف‬\n      ‫فإنــه ملــا ثبــت اعتبــاره يف الشــرع مــن غيــر تنصيــص علــى بيانــه علــم أنــه‬\n      ‫رد ذلــك إلــى أهــل العــرف ا ‪ .‬ه ـ ولكــون البــاب الــذي دخــل منــه املدعــى‬\n      ‫عليهمــا األول والثالــث علــى بقالــة ‪ ........‬وســرق منهــا املدعــى عليــه األول‬\n\n\n‫‪179‬‬\n\f‫ا حســب مــا ذكــره املقــر يف‬       ‫مبلــغ عشــرة آالف ريــال لــم يكــن مقف ـ ً‬\n‫إقــراره ولــم يــأت املدعــي العــام بخالفــه ولقيــام املدعــى عليــه األول‬\n‫بســرقة جوالــن مــن محــل ‪..................‬وقيــام املدعــى عليه الثالث بســرقة‬\n‫الكاشــير يف محــل ‪..................‬وحيــث ذكــرا أن البــاب لــم يكــن‬\n‫ا ولكــون مــا تقــدم شــبهة يــدرأ بهــا احلــد علــى املدعــى عليــه األول‬  ‫مقفـ ً‬\n‫واملدعــى عليــه الثالــث وملــا جــاء يف احلديــث «ادرأوا احلــدود بالشــبهات»‬\n‫وملــا أجمــع عليــه أهــل العلــم مــن درء احلــدود بالشــبهات قــال اإلمــام ابــن‬\n‫املنــذر رحمــه اهلل كمــا جــاء يف املغنــي (‪ : )55/9‬أجمــع كل مــن أحفــظ‬\n‫عنــه مــن أهــل العلــم أن احلــدود تــدرء بالشــبهات ‪ .‬وحيــث إن للمدعــى‬\n‫عليهما الثاني والرابع إقرارات مبشــاركة األول والثالث يف الســرقات‬\n‫املذكــورة وألن إقراراتهمــا ال توجــب احلــد وإمنــا التعزيــر ومــا ادعيــاه مــن‬\n‫اإلكــراه البينــة لهمــا عليــه وال نــرى أن ســجنهما يف الوقــت الراهــن علــى‬\n‫اإلكــراه لتغيــر الزمــان فأصبــح مــن األمورالالزمــة التحفــظ علــى‬\n‫املتهمــن أثنــاء التحقيــق معهــم منع ـ ًا مــن فرارهــم وضيــاع احلقــوق وال‬\n‫يكــون ذلــك إال يف مقــر التوقيــف كمــا أن التعليمــات نصــت علــى عــدم‬\n‫إكــراه احملقــق معهــم علــى االعتــراف أو إيذائهــم النفســي أوالزمــان‬\n‫اليقتصــر علــى املتهمــن فقــط ومــا ُذكــر مــن أن عــدم أخــذ إقــرارات‬\n‫ويضيــع احلقــوق فــا‬\n                    ‫ّ‬      ‫املتهمــن بدعــوى اإلكــراه ســيعطل األحــكام‬\n‫يصــح لكــون القاضــي ينظــر للقضيــة مــن جميــع جوانبهــا وال يقتصــر‬\n‫علــى مســتند واحــد ومــا ُذكــر مــن أن كالم الفقهــاء اجتهــاد منهــم‬\n‫وليــس مبني ـ ًا علــى نــص فــكل هــذا اليسـ ّـوغ مخالفــة هــؤالء األئمــة‬\n‫والشــك أن الرجــوع لفهــم الســلف وتطبيقاتهــم القضائيــة هــو خيــر معــن‬\n‫للقاضــي للوصــول للحقيقــة وقــد كان القاضــي شــريح رحمــه اهلل كما‬\n\n\n                                                                                       ‫‪180‬‬\n\f      ‫جــاء يف مصنــف عبدالــرزاق (‪ )192/10‬يقــول‪ « :‬القيــد كــره‪ -‬والوعيــد‬\n      ‫كــره‪ -‬والســجن كــره‪ -‬والضــرب كــره»‪ .‬وقبلــه أميــر املؤمنــن عمــر‬\n      ‫بــن اخلطــاب رضــي اهلل عنــه قــال‪ :‬ليــس الرجــل بأمــن علــى نفســه إن‬\n      ‫أجعتــه أو أخفتــه أوحبســته‪.‬أخرجه ابــن أبي شــيبة يف املصنف (‪.)490/6‬‬\n      ‫ونظــام املرافعــات الشــرعية يف املــادة ‪ 104‬ينــص علــى أن اإلقــرار الــذي‬\n      ‫يؤاخــذ بــه املــرء‪ ،‬هــو اإلقــرار احلاصــل أمــام القاضــي أثنــاء ســير‬\n      ‫ا أمــام القضــاء‬    ‫الدعــوى‪ ،‬ونصهــا‪ :‬يجــب أن يكــون اإلقــرار حاص ـ ً‬\n      ‫أثنــاء الســير يف الدعــوى املتعلقــة بالواقعــة املقــر بهــا ‪.‬وقــد أكــدت هــذا‬\n      ‫الالئحــة التنفيذيــة لنظــام املرافعــات إذ قالــت‪ :‬اإلقــرار القضائــي هــو مــا‬\n      ‫يحصــل أمــام ناظــر الدعــوى‪ ،‬أثنــاء الســير فيهــا‪ ،‬متعلقـ ًا بالواقعــة املقــر‬\n      ‫بهــا‪ :‬فقيــد قبــول اإلقــرار بقيديــن‪ -1‬أن يكــون اإلقــرار أمــام ناظــر‬\n      ‫الدعــوى‪ -2‬أن يكــون اإلقــرار يف أثنــاء الســير يف الدعــوى املتعلقــة‬\n      ‫بالواقعــة املقــر بهــا‪ .‬واإلقــرارات التــي يقــر بهــا املســجون لــدى رجــال‬\n      ‫ـاض‬‫الضبــط يتخلــف عنهــا القيــد األول‪ .‬واإلقــرارات املصدقــة مــن قـ ٍ‬\n      ‫يتخلــف عنهــا القيــد الثانــي املرجــع إقــرار الســجني‪ .‬ولكــون املدعــى‬\n      ‫عليهمــا األول والثالــث أنكــرا مشــاركة املدعــى عليهمــا الثاني والرابع‬\n      ‫وإعانتهمــا لهمــا يف الســرقة ولقــوة التهمــة املوجهــة علــى املدعــى عليهــا‬\n      ‫الثانــي والرابــع يف إعانتهمــا علــى الســرقة ولتســترهما علــى املدعــى‬\n      ‫عليهمــا األول والثالــث‪ .‬لــذا أرى أن يعــزر املدعــى عليهمــا الثانــي والرابــع‬\n      ‫بســجن كل واحــد منهمــا ســنة كاملــة مــن تاريــخ إيقافهمــا ويجلــد كل‬\n      ‫واحــد منهمــا ســتون جلــدة علــى ثــاث دفعــات كل دفعــة عشــرون جلــدة‬\n      ‫و بــن كل دفعــة والتــي تليهــا أســبوعان‪ .‬هــذه وجهــة نظــري) ا ‪ .‬ه ـ وبعــد‬\n      ‫تأمــل ودراســة أوراق املعاملــة وبعــد االطــاع علــى وجهــة فضيلــة القاضي‬\n\n\n‫‪181‬‬\n\f‫املشــارك الشــيخ ‪ ........‬ولكــون املدعــى عليــه األول واملدعــى عليــه‬\n‫الثالــث قــد أقــر كل واحــد منهمــا وهمــا بكامــل قواهمــا العقليــة‬\n‫واملعتبــرة شــرع ًا وبطوعهمــا واختيارهمــا دون إكــرا ٍه مــن أحــد أنهمــا‬\n‫ســرقا مــن مــال محتــرم ليــس لهمــا فيــه شــبهة ولكــون مــا أقدمــا عليــه‬\n‫فعــل محــرم معاقــب عليــه شــرع ًا ولكــون هــذا املــال أخــرج مــن غيــر‬\n‫حــرزه املعتبــر شــرع ًا وذلــك لكــون البــاب الــذي كســره املدعــى عليــه‬\n‫األول يف مؤسســة ‪.....‬التجاريــة وســرق منــه مبلــغ أربعــة آالف ريــال مــن‬\n‫زجــاج وهــو يف العــادة والعــرف ليــس بحــرز حتفــظ فيــه مثــل هــذه األمــوال‬\n‫حيــث إن العــرف املتعــارف عليــه أن يكــون البــاب مــن حديــد وقــد اتفــق‬\n‫الفقهــاء علــى اعتبــار العــرف يف احلــرز والرجــوع فيــه إلــى أهلــه ‪ ،‬قــال‬\n‫اإلمــام ابــن قدامــة رحمــه اهلل يف املغنــي (‪ :)250/10‬واحلــرز مــا عــد حرز ًا‬\n‫يف العــرف فإنــه ملــا ثبــت اعتبــاره يف الشــرع مــن غيــر تنصيــص علــى بيانــه‬\n‫علــم أنــه رد ذلــك إلــى أهــل العــرف ا ‪ .‬ه ـ ولكــون البــاب الــذي دخــل منــه‬\n‫املدعــى عليهمــا األول والثالــث علــى بقالــة ‪.....‬وســرق منهــا املدعــى عليــه‬\n‫ا حســب مــا ذكــره املقــر‬  ‫األول مبلــغ عشــرة آالف ريــال لــم يكــن مقفـ ً‬\n‫يف إقــراره ولــم يــأت املدعــى العــام بخالفــه ولقيــام املدعــى عليــه األول‬\n‫بســرقة جوالــن مــن محــل ‪..................‬وقيــام املدعــى عليه الثالث بســرقة‬\n‫الكاشــير يف محــل ‪..................‬وحيــث ذكــرا أن البــاب لــم يكــن‬\n‫ا ولكــون مــا تقــدم شــبهة يــدرأ بهــا احلــد علــى املدعــى عليــه األول‬\n                                                                           ‫مقفـ ً‬\n‫واملدعــى عليــه الثالــث وملــا جــاء يف احلديــث «ادرؤوا احلــدود بالشــبهات»‬\n‫وملــا أجمــع عليــه أهــل العلــم مــن درء احلــدود بالشــبهات قــال اإلمــام ابــن‬\n‫املنــذر رحمــه اهلل كمــا جــاء يف املغنــي (‪ : )55/9‬أجمــع كل مــن أحفــظ‬\n‫عنــه مــن أهــل العلــم أن احلــدود تــدرء بالشــبهات ‪ .‬وحيــث إن للمدعــى‬\n\n\n                                                                                       ‫‪182‬‬\n\f      ‫عليهما الثاني والرابع إقرارات مبشــاركة األول والثالث يف الســرقات‬\n      ‫املذكــورة وألن إقراراتهمــا ال توجــب احلــد وإمنــا التعزيــر ومــا ادعيــاه مــن‬\n      ‫اإلكــراه البينــة لهمــا عليــه وال نــرى أن سجنهمااجلســدي وهــذا هــو‬\n      ‫األصــل ومــن ادعــى خــاف ذلــك فعليــه البينــة وال بينــة هنــا ومــا ذكــره‬\n      ‫الفقهــاء رحمهــم اهلل مــن اعتبــار الســجن قرينــة على اإلكراه ال يســتقيم‬\n      ‫يف هــذا الزمــان ملــا قدمنــا مــن أنــه إذا لــم يتحفــظ علــى املتهــم فإنــه يف‬\n      ‫الغالــب يفــر مــن احملاكمــة فتضيــع حقــوق اهلل وحقــوق النــاس ومــا‬\n      ‫ذكــره الفقهــاء لــم يســتندوا فيــه إلــى أدلــة مــن الكتــاب والســنة وإمنــا‬\n      ‫محــض اجتهــاد وقــد يكــون ذلــك مناســب ًا يف زمانهــم أمــا يف هــذا الزمان‬\n      ‫الــذي كثــر فيــه الظلــم والبغــي واإلجــرام فــا ميكــن أن جنعــل مجــرد‬\n      ‫ســجن املتهــم قرينــة علــى اإلكــراه وال ينكــر تغيــر األحــكام بتغيــر‬\n      ‫ويحــدث للنــاس مــن األحــكام والعقوبــات مبقــدار مــا يحدثــون‬       ‫األزمــان ُ‬\n      ‫مــن الفجــور حتــى لــو ســلمنا بــأن الســجن قرينــة علــى اإلكــراه فإننــا‬\n      ‫نــرى إن أكــراه املتهــم بالضــرب أوغيــره علــى الفعــل ســائغ شــرعا ولذلك‬\n      ‫شــواهد مــن الشــريعة اإلســامية منهــا مــا جــاء عــن ابــن عمــر رضــي اهلل‬\n      ‫عنهمــا أن رســول اهلل صلــى عليــه وســلم قاتــل أهــل خيبــر حتــى غلــب على‬\n      ‫األرض والــزرع والنخــل واشــترط عليهــم ان ال يكتمــوا وال يغيبــوا شــيئ ًا‬\n      ‫فغيبــوا مســك ًا فيــه مــال وحلــي حليــي بــن أخطــب فقــال رســول اهلل صلــى‬\n      ‫اهلل عليــه وســلم لعــم حيــي مــا فعــل مســك حيــي الــذي جــاء بــه بنــي‬\n      ‫النظيــر فقــال أذهبتــه النفقــات واحلــروب فقــال العهــد قريــب واملــال‬\n      ‫أكثــر مــن ذلــك فدفعــه إلــى الزبيــر فمســه بعــذاب فقــال رأيــت حييـ ًا يف‬\n      ‫خربــة ههنــا فذهبــوا فوجــدوا املســك هنــاك ووجــه الداللــة منــه أنــه ملــا‬\n      ‫قويــت القرينــة عنــد النبــي صلــى اهلل عليــه وســلم وهــي قــرب العهــد‬\n\n\n‫‪183‬‬\n\f‫وكثــرة املــال غلــب علــى ظنــه كــذب ابــن أبــي احلقيــق فأمــر الزبيــر‬\n‫بتعذيبــه فــدل علــى اعتبــار إقــراره إذ لولــم يعتبــر إقراره ملــا كان لتعذيبه‬\n‫فائــدة ومــن ذلــك مــا روى أنــس رضــي اهلل عنــه قــال نــدب رســول اهلل‬\n‫صلــى عليــه وســلم النــاس فانطلقــوا حتــى نزلــوا بــدر ًا ووردت عليهــم‬\n‫روايــا قريــش وفيهــم غــام أســود لبنــي احلجــاج فأخــذوه فــكان أصحــاب‬\n‫رســول اهلل صلــى عليــه وســلم يســألونه عــن أبــي ســفيان وأصحابــه‬\n‫فيقــول مالــي علــم بأبــي ســفيان ولكــن هــذا أبــو جهــل وعتبــه وشــيبة‬\n‫وأميــة بــن خلــف يف النــاس فــإذا قــال هــذا ضربــوه ورســول اهلل صلــى‬\n‫عليــه وســلم قائــم يصلــي فلمــا رآى ذلــك أنصــرف وقــال ‪ (:‬والــذي نفســي‬\n‫بيــده لتضربــوه إذا صدقكــم وتتركــوه إذا كذبكــم ) رواه مســلم‬\n‫ووجهــه الداللــة فيــه كســابقه ومــن ذلــك أيضـ ًا مــارواه البخــاري ومســلم‬\n‫يف شــأن بريــره ان رســول اهلل صلــى عليــه وســلم دعاهــا فســألها فقــام‬\n‫علــي فضربهــا ضربـ ًا شــديد ًا أو جعــل بقولــه أصدقــي رســول اهلل فتقــول‬\n‫واهلل مــا أعلــم إال خيــراً‪ ...‬احلديــث ووجــه االســتدالل مــن هــذا احلديــث أن‬\n‫النبــي صلــى اهلل عليــه وســلم لــم ينكــر علــى علـ ّـي رضــي اهلل عنــه ضربــه‬\n‫لبريــره لتكشــف عمــا تعلمــه مــن امــر عائشــة حيــث كانــت لصيقــة بهــا‬\n‫فلــو لــم يكــن قــول املتهــم معتبــر ًا بعــد الضــرب ملــا كان يف ضربهــا‬\n‫فائــدة وملــا أقــر النبــي صلــى اهلل عليــه وســلم علي ـ ًا علــى ذلــك قــال ابــن‬\n‫فرحــون يف تبصــره احلــكام بعــد إيــراده لقصــة بريــرة ( وهــذا مــن‬\n‫السياســة ألن ضربهــا لتقــر مبــا عندهــا) ومــن ذلــك أيض ـ ًا مــا روى أبــو‬\n‫داود أن قوم ـ ًا مــن الكالعيــن ُســرق لهــم متــاع فاتهمــوا أناســا مــن‬\n‫احلاكــة فأتــوا النعمــان بــن بشــير صاحــب النبــي صلــى اهلل عليــه وســلم‬\n‫اهلل نحســبهم أيام ـ ًا ثــم خلــى ســبيلهم فأتــوا النعمــان فقالــوا خليــت‬\n\n\n                                                                                         ‫‪184‬‬\n\f      ‫ســبيلهم بغيــر ضــرب وال امتحــان فقــال النعمــان ‪ :‬مــا شــئتم ‪ ،‬إن شــئتم‬\n      ‫أن أضربهــم فــإن خــرج متاعكــم فــذاك وإال أخــذت مــن ظهوركــم مثــل‬\n      ‫مــا أخــذت مــن ظهورهــم فقالــوا هــذا حكمــك؟ فقــال هــذا حكــم اهلل‬\n      ‫ورســوله‪ .‬ووجــه االســتدالل أن حبــس النعمــان بــن بشــير للمدعــى عليهــم‬\n      ‫واســتعداده لضربهــم حتــى يخرجــوا املتــاع بالشــرط الــذي أشــار إليــه‬\n      ‫دليــل علــى تعذيــب املتهــم ليكشــف عــن حقيقــة مــا أتهــم بــه‪ .‬وهــذا هــو‬\n      ‫الــذي تقتضيــه املصلحــة ألن أكثــر املجرمــن يرتكــب جرميتــه بعيــد ًا‬\n      ‫عــن أعــن النــاس حيــث تتعــذر إقامــة البينــة عليهــا يف أكثــر احلــاالت فلو‬\n      ‫لــم نقــل بجــواز ضربهــم والتشــديد عليهــم لقيــام القرائــن علــى صحــة مــا‬\n      ‫نســب إليهــم لتمكــن كثيــر مــن املجرمــن مــن ارتــكاب جرائهــم‬\n      ‫واإلفــات مــن العقــاب ويف ذلــك مــن الفســاد مــا ال يعلمــه إال اهلل كمــا‬\n      ‫أنــه عنــد تعــارض مصلحــة الفــرد ومصلحــة املجتمــع تقــدم مصلحــة‬\n      ‫املجتمــع علــى مصلحــة الفــرد إذ هــي األكثــر نفع ـ ًا واألبعــد أثــر ًا ومــن‬\n      ‫القواعــد املقــررة شــرع ًا جلــب أعلــى املصلحتــن لتفويــت أدناهمــا‬\n      ‫وأرتــكاب أدنــى املفســدتني دفع ـ ًا ألعالهماقــال ابــن تيميــة يف مجمــوع‬\n      ‫الفتــاوي عنــد كالمــه عــن رأي مــن رأى ضــرب املتهــم املعــروف بالفجــور‬\n      ‫ليكشــف عــن حالــه ( ولهــم مــن املعقــول قولهــم إن املمتنــع مــن أداء‬\n      ‫واجــب إذا أصــر علــى االمتنــاع فإنــه يعاقــب ويضــرب مــرة بعــد أخــرى‬\n      ‫حتــى يؤديــه ‪ ،‬فكذلــك املتهــم املعــروف بالفجــور فإنــه يضــرب لتســتبني‬\n      ‫حالــه) ا ‪.‬ه ـ لــذا وجلميــع مــا تقــدم فقــد قررنــا باإلجمــاع مــا يلــي أوال‪ -:‬رد‬\n      ‫دعــوى املدعــي العــام مبطالبتــه إقامــة حــد الســرقة علــى كل مــن األول‬\n      ‫والثالــث الختــال شــروط القطــع ثاني ـاً‪ -:‬تعزيــر املدعــى عليهمــا األول‬\n      ‫والثالــث املذكوريــن بســجن كل واحــد منهمــا ثمــان ســنوات اعتبــار ًا‬\n\n\n‫‪185‬‬\n\f‫مــن تاريــخ إيقافهمــا وجلــد كل واحــد منهمــا ثمامنائــة جلــدة علــى ســت‬\n‫عشــرة دفعــة كل دفعــة خمســن جلــدة وبــن كل دفعتــن خمســة عشــر‬\n‫يوم ـ ًا ثالث ـاً‪ -:‬قررنــا باألغلبيــة تعزيــر املدعــى عليهمــا الثانــي والرابــع‬\n‫بســجن كل واحــد منهمــا ثــاث ســنوات اعتبــار ًا مــن تاريــخ إيقافهمــا‬\n‫وجلــد كل واحــد منهمــا أربعمائــة جلــدة علــى ثمــان دفعــات كل دفعــة‬\n‫خمســن جلــدة وبــن كل دفعتــن خمســة عشــر يوم ـ ًا وبــه حكمنــا‬\n‫وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليهــم قــرر املدعــي العــام‬\n‫عــدم القناعــة وطلــب تقــدمي الئحــة اعتراضيــة وقــرر املدعــى عليهمــا‬\n‫األول والثالــث عــدم القناعــة وعــدم تقــدمي الئحــة اعتراضيــة وقــررا‬\n‫املدعــى عليهمــا الثانــي والرابــع القناعــة باحلكــم وبــاهلل التوفيــق ‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                        ‫‪ 1434/11/02‬هـ الساعة احلادية عشرة‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامة مبحافظة األحســاء‬\n‫برقــم وتاريــخ ‪1435/1/1‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪000000‬‬\n‫‪/00/‬خ‪ 1‬وتاريــخ ‪1435/1/ 8‬ه ـ املرفــق بهــا القــرار الشــرعي ذو الرقــم‬\n‫والتاريــخ ‪1434/ 11/ 12‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة‬\n‫باحملكمــة الشــيخ‪ ........ /‬والشــيخ‪ ........ /‬والشــيخ‪ ........ /‬اخلــاص‬\n‫كل مــن‪، ........-1:‬مينــي‬ ‫ٍ‬      ‫بدعــوى‪ ........ /‬املدعــي العــام ضــد‪........ /‬‬\n‫اجلنســية ‪، ........-2‬مينــي اجلنســية ‪،........-3‬مينــي اجلنســية ‪، ........-4‬مينــي‬\n‫اجلنســية يف قضيــة ســرقة وقــد تضمــن قــرار حكــم أصحــاب الفضيلــة‬\n‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n\n\n                                                                                        ‫‪186‬‬\n\f      ‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‪1435/1/16‬‬\n                                                                                ‫هـــ ‪.‬‬\n\n\n\n\n‫‪187‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":162,"source_page_end":187,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b8c5685ad63aa599771206320676915227a3c94cedb58262aff15a7cf2f466c4","normalized_text_hash":"06e8a778593823a7a24db38f304bd4d53f86f341f12dd2edc007ef13854ef042","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p162-34359573"},{"id":"aeae7547-3262-546d-bb42-76bec0564f69","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقه سيارة وأغنام وبطارية سيارة -مقاومه قوات الشرطة -اشتراك يف السرقة -رجوع عن االعتراف بالسرقة -إثبات اإلدانة بالقرائن -حد السرقة لعدم ثبوت املوجب الشرعي -التعزير بالسجن واجللد -احلكم بالبراءة -صرف النظر لعدم االختصاص","document_number":"34189490","case_number":"3497072","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة دومة اجلندل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/16","year":"1434","subject":"سرقة -سرقه سيارة وأغنام وبطارية سيارة -مقاومه قوات الشرطة -اشتراك يف السرقة -رجوع عن االعتراف بالسرقة -إثبات اإلدانة بالقرائن -حد السرقة لعدم ثبوت املوجب الشرعي -التعزير بالسجن واجللد -احلكم بالبراءة -صرف النظر لعدم االختصاص","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34189490 :‬تاريخه ‪1434/04/16 :‬هـ‬\n                    ‫رقم الدعوى ‪3497072 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‬\n           ‫‪ 34322979:‬تاريخه ‪1434/9/20:‬هـ‬\n\n\n\n ‫ســرقة ‪-‬ســرقه ســيارة وأغنــام وبطاريــة ســيارة ‪ -‬مقاومــه قــوات الشــرطة‬\n ‫‪ -‬اشــتراك يف الســرقة ‪ -‬رجــوع عــن االعتــراف بالســرقة ‪ -‬إثبــات اإلدانــة‬\n ‫بالقرائــن ‪ -‬حــد الســرقة لعــدم ثبــوت املوجــب الشــرعي‪ -‬التعزيــر‬\n ‫بالســجن واجللــد ‪ -‬احلكــم بالبــراءة ‪ -‬صــرف النظــر لعــدم االختصاص‬\n                                                                     ‫املكانــي ‪.‬‬\n\n\n\n\n                                         ‫‪-1‬قاعدة ‪ :‬األصل براءة الذمة ‪.‬‬\n                          ‫‪-2‬املادة (‪ )131‬من نظام اإلجراءات اجلزائية ‪.‬‬\n                  ‫‪-3‬ما قرره أهل العلم من اشتراط احلرز يف السرقة ‪.‬‬\n ‫‪-4‬املــادة (‪ )106‬مــن نظــام املرافعــات الشــرعية والتــي نصــت علــى عــدم‬\n                                          ‫جتزئــة اإلقــرار علــى صاحبــه ‪.‬‬\n\n\n\n\n ‫توجيــه االتهــام خلمســة أشــخاص األول والثانــي والثالــث بتشــكيل‬\n ‫عصابــة لســرقة عــدة ســيارات وأغنــام وبطاريتــن والتســبب يف إحــداث‬\n ‫تلفيــات يف الســيارة املســروقة وتغييــر معاملهــا والهــرب مــن رجــال‬\n ‫األمــن ‪ ،‬واملدعــى عليــه األول بســرقة حراثــة‪ ،‬واملدعــى عليــه الرابــع‬\n ‫باملشــاركة بســرقة الســيارات ‪ ،‬واملدعــى عليــه اخلامــس بالتحريــض‬\n\n                                                                                   ‫‪188‬‬\n\f      ‫والتســتر علــى ســرقه حراثــة‪ ،‬وتبــن وجــود ســوابق للمدعــى عليهــم‬\n      ‫‪،‬كمــا وردت عــدة بالغــات عــن تعــرض املبلغــن للســرقة ‪ ،‬وقــد‬\n      ‫جــاء يف البــاغ األول أن املدعــى عليــه األول قــام بتحميــل حراثــة‬\n      ‫متوقفــة منــذ ســنة أمــام أحــد الــورش علــى ســطحة و الذهــاب بهــا إلــى‬\n      ‫مزرعــة ال تخصــه وضبطــت إفــادة عامــل الورشــة و صاحــب الســيارة‬\n      ‫الســطحة أنــه مت االشــتباه بســيارة قادمــة للمحافظــة مــن اجلهــة الغربيــة‬\n      ‫وباســتيقافهما رفــض قائدهــا الوقــوف متجــاوز ًا نقطتــن أمنيتــن‪ ،‬وبعــد‬\n      ‫مطــاردة علــى األقــدام مت القبــض عليهــم و اتضــح أنهــم املتهمــون األول‬\n      ‫و الثانــي و الثالــث ‪ ،‬وبتفتيــش الســيارة عثــر علــى ثــاث لوحــات نقــل‬\n      ‫خــاص مســروقة‪ ،‬واتضــح أن الســيارة التــي بحوزتهــم مســروقة و أنــه مت‬\n      ‫تغيــر بعــض مالمحهــا ‪،‬كمــا مت القبــض علــى الرابــع و اخلامــس الحقـ ًا‬\n      ‫‪ ،‬وطلــب املدعــي العــام إقامــة حــد الســرقة بحــق املدعــى عليــه األول‬\n      ‫والثانــي والثالــث ‪ ،‬وتعزيــر املدعــى عليــه الرابــع واخلامــس ‪ ،‬وحضــر‬\n      ‫املدعــى عليهــم مــا عــدا اخلامــس ‪ ،‬وأنكــر املدعــى عليهــم مــا نســب‬\n      ‫إليهــم ‪ ،‬وجــرى الرجــوع إلــى محضــر القبــض ‪ ،‬واعتــرف املدعــى عليــه‬\n      ‫األول و الثانــي و الثالــث حتقيق ـ ًا ‪ ،‬ولعــدم وجــود أدلــة ضــد املدعــى‬\n      ‫عليــه الرابــع ‪ ،‬وملــا جــاء يف خطــاب هيئــة التحقيــق مــن أن األدلــة الترقــى‬\n      ‫لتوجيــه االتهــام ضــد املدعــى عليــه الرابــع ‪ ،‬وذلــك لكــون املدعــى عليــه‬\n      ‫اخلامــس مطلــق الســراح و يقيــم خــارج النطــاق املكانــي للمحكمــة‬\n      ‫ناظــرة القضيــة ‪ ،‬فقــد صــدر احلكــم بصــرف النظــر عــن إقامــة حــد‬\n      ‫الســرقة وتعزيــر املدعــى عليهــم األول والثانــي والثالــث بالســجن واجللــد‬\n      ‫‪،‬وبــراءة املدعــى عليــه الرابــع ‪،‬وقضــت احملكمــة بصــرف النظــر عــن‬\n      ‫دعــوى املدعــي العــام جتــاه املدعــى عليــه اخلامــس لعــدم االختصــاص‬\n                        ‫املكانــي ‪ُ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n‫‪189‬‬\n\f‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة باحملكمــة العامة مبحافظة‬\n‫دومــة اجلنــدل‪ ..........‬و‪ ..........‬و‪ ..........‬و‪ ..........‬وبنــاء علــى املعاملــة‬\n‫احملالــة برقــم‪ ..........‬وتاريــخ ‪ 0000/00/0‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 00000000‬وتاريــخ ‪ 0000/00/00‬ه ـ فقــد حضــر املدعــي العــام‬\n‫ال مــن ‪، ..........-1‬البالــغ مــن‬  ‫وفيهــا قــدم الئحــة دعــوى عامــة ضــد ك ً‬\n‫العمــر (‪ )00‬عامـاً‪ ..........‬اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪)..........‬‬\n‫‪، ..........-2‬البالــغ مــن العمــر (‪ )..........‬عامـ ًا ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة رقــم (‪، ..........-3 )..........‬البالــغ مــن العمــر (‪)..........‬‬\n‫عام ـ ًا ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪...... -4 )..........‬‬\n‫‪،‬البالــغ مــن العمــر (‪ )..........‬عام ـ ًا ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة رقــم (‪، .................. -5)..........‬البالــغ مــن العمــر (‪ )..........‬عامـ ًا‬\n‫ا فيهــا‬ ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )..........‬قائ ـ ً‬\n‫بصفتــي مدعيـ ًا عامـ ًا يف دائــرة التحقيــق واالدعــاء العــام مبحافظــة دومــة‬\n‫ا ‪ :‬إنــه يف يــوم اجلمعــة املوافــق ‪0000/0/0‬ه ـ‬      ‫اجلنــدل أدعــي عليهــم قائـ ً‬\n‫تقــدم لشــرطة محافظــة دومــة اجلنــدل املواطــن‪ ........../‬ببــاغ مفــاده أنــه‬\n‫يف يــوم أمــس اخلميــس املوافــق ‪0000/0/0‬ه ـ الحــظ أن حراثــة والــده‬\n‫الواقفــة منــذ ســنة تقريب ـ ًا أمــام أحــد الــورش بصناعيــة دومــة اجلنــدل‬\n‫غيــر موجــودة وقــد تعرضــت للســرقة وال يتهــم أحــد بذلــك وأضــاف أنــه‬\n‫ســأل أحــد عمــال الورشــة مــن اجلنســية اليمنيــة عنهــا فأفــاده أن صاحــب‬\n‫ســطحة حملهــا معــه جــوال رقمــه[‪ ]0000000000‬وبضبــط إفــادة الوافــد‬\n‫‪ ........../‬ـ ـ مينــي اجلنســية ـ ـ أفــاد أن األول أحــد زبائنــه الذيــن يتــرددون‬\n\n                                                                                                ‫‪190‬‬\n\f      ‫علــى محلــه وطلــب منــه أن يبحــث لــه عــن صاحــب ســطحه لنقــل احلراثــة‬\n      ‫اخلاصــة بــه فطلــب هــو مــن الوافــد ‪ .......... /‬االتصــال بــاألول ‪.......... /‬‬\n      ‫لنقــل حراثتــه إلــى موقــع آخــر علــى جوالــه رقــم [‪ ]..........‬وأضــاف أنــه ال‬\n      ‫عالقــة لــه باحلراثــة ســوى مــا ذكــره بأنــه لــأول عــدة ســيارات مــن ‪ ....‬و‬\n      ‫‪ ، .....‬وبضبــط إفــادة الوافــد ‪ ( .......... /‬صاحــب الســطحة ) أفــاد أنــه‬\n      ‫عندمــا كان واقفـ ًا يف محطــة ‪ ....‬اســتدعاه عامــل مينــي اجلنســية يدعــى‬\n      ‫‪ .......... /‬وقــال لــه ‪ :‬إن صاحــب هــذه احلراثــة وأشــار عليهــا يريــد حملهــا‬\n      ‫فهــل تســتطيع ذلــك فأجابــه بقولــه نعــم وأعطــاه رقــم جــوال املدعــى عليــه‬\n         ‫األول‪ .......... /‬رقم[‪]..........‬واتصــل عليــه وقــال لــه املدعــى عليــه األول‬\n      ‫‪ : .......... /‬أريــدك أن حتمــل احلراثــة علــى مهلــك وتوصلهــا ملزرعتــي‬\n      ‫مقابــل (‪ )250‬ريــا ًال واتفقــا علــى حمــل احلراثــة وواعــده علــى طريــق‬\n      ‫ووصــل هنــاك يف متــام الســاعة الرابعــة والنصــف مــن مســاء يــوم األربعــاء‬\n      ‫املوافــق ‪0000/0/0‬ه ـ وكانــت بقيــادة األول ‪ .......... /‬ســيارة مــن نــوع‬\n      ‫‪ .....‬لونهــا ‪ ..........‬وســار أمامــه وتبعــه حتــى وصــا إلــى مزرعتــه حســب‬\n      ‫ادعائــه وطلــب منــه إنزالهــا داخــل املزرعــة يف املــكان الــذي حــدده ‪،‬‬\n      ‫وبضبــط إفــادة املواطــن ‪ .......... /‬حيــال املزرعــة التــي عثــر فيهــا علــى‬\n      ‫احلراثــة املســروقة أفــاد أن املزرعــة تعــود لوالــده املتوفــى وهــي شــراكة‬\n      ‫بينــه وبــن أخوتــه وهــو املســئول عنهــا ولــم يشــاهد احلراثــة املســروقة‬\n      ‫فيهــا وال يعلــم شــيئ ًا عنهــا ‪ ،‬ويف يــوم اخلميــس املوافــق ‪0000/0/00‬ه ـ‬\n      ‫تقــدم ملركــز شــرطة بســكاكا الوافــد ‪ .......... /‬ـ ـ ســوداني اجلنســية‬\n      ‫ـ ـ ببــاغ مفــاده أنــه تعرضــت ســيارة كفيلــه مــن نــوع ‪ ....‬حتمــل اللوحــة‬\n      ‫رقــم [‪ ] ..........‬ســنة الصنــع (‪1990‬م) للســرقة مــن أمــام منزلــه بحــي ‪....‬‬\n      ‫وأضــاف أنهــا كانــت مقفلــة وال يتهــم أحــد بســرقتها ‪ ،‬ويف يــوم األحــد‬\n\n\n‫‪191‬‬\n\f  ‫املوافــق ‪0000/0/00‬ه ـ تقــدم لشــرطة محافظــة دومــة اجلنــدل الوافــد‬\n‫‪ ، .......... /‬هنــدي اجلنســية ‪ ،‬ببــاغ مفــاده أنــه يف حوالــي الســاعة الثانيــة‬\n‫والنصــف مــن صبــاح يــوم األحــد املوافــق ‪0000/0/0‬ه ـ وأثنــاء قدومــه‬\n‫علــى ســيارة احملطــة (‪ ) ..........‬كانــت ســيارة املؤسســة مــن نــوع ‪ ....‬ســنة‬\n‫الصنــع (‪1998‬م) حتمــل لوحــة ســعودية رقــم [‪ ]0000‬واقفــة بجانــب‬\n‫الســكن وشــاهد شــخص ًا ملثــم يفتــح الســيارة وركبهــا وســرقها وهرب‬\n‫بهــا وأضــاف بــأن الشــخص كان ملثم ـ ًا بشــماغ أحمــر ويلبــس ثوب ـ ًا‬\n‫أبيــض نحيــف اجلســم عمــره مــا بــن ‪20‬عام ـ ًا إلــى ‪25‬عام ـ ًا ولــم يشــاهد‬\n‫وجهــه وبــأن الســيارة كانــت مفتوحــة مــن جهــة بــاب الســائق وقــام‬\n‫بتشــغيلها بــأي مفتــاح وال يتهــم أحــد بســرقتها ‪،‬ويف يــوم األربعــاء املوافــق‬\n‫‪0000/0/00‬ه ـ تقــدم لشــرطة محافظــة دومــة اجلنــدل املواطــن ‪.......... /‬‬\n‫ببــاغ مفــاده أنــه عنــد الســاعة السادســة والنصــف مــن مســاء ذلــك اليــوم‬\n‫أبلغــه راعــي غنمــه عــن قيــام صاحــب ســيارة مــن نــوع ‪ ...‬بســرقة (‪)4‬‬\n‫أربعــة خــراف لونهــا ‪ ..........‬ولــون رأســها ‪ ..........‬مــن الشــبك الواقــع بقريــة‬\n‫‪ ، ..........‬وبضبــط إفــادة الوافــد ‪ ، .......... /‬نيبالــي اجلنســية ‪ ،‬حيــال‬\n‫بــاغ املواطــن ‪ ...... /‬أفــاد أنــه الحــظ ســيارة مــن نــوع ‪ .....‬ســرق صاحبهــا‬\n‫خراف ـ ًا مــن كفيلــه يف قريــة ‪ ، ..........‬ويف يــوم اجلمعــة املوافــق‬\n‫‪0000/0/00‬ه ـ تقــدم لشــرطة محافظــة دومــة اجلنــدل املواطــن ‪.......... /‬‬\n‫ببــاغ مفــاده تعــرض ســيارة والــده مــن نــوع ‪ .....‬لونــه ‪ ..........‬يحمــل اللوحــة‬\n‫رقــم [‪ ]0000‬ســنة الصنــع (‪2009‬م) للســرقة مــن أمــام املنــزل وقد كانت‬\n‫مقفلــة واملفتــاح بداخلهــا يف محــل التشــغيل ‪ -‬وباالنتقــال للموقــع‬\n‫ومبعاينتــه اتضــح عــدم وجــود آثــار تفيــد التحقيــق ‪ ،‬ويف يــوم الســبت‬\n‫املوافــق ‪0000/0/00‬ه ـ تقــدم ملخفــر شــرطة الوافــد ‪ ، .......... /‬نيبالــي‬\n\n\n                                                                                            ‫‪192‬‬\n\f      ‫اجلنســية ‪ ،‬ببــاغ مفــاده أنــه ســرقت مــن مزرعــة كفيلــه التــي يعمــل فيهــا‬\n      ‫بطاريتــان مقــاس (‪ )1120‬أمبيــر تقــدر قيمتهــا بــ(‪ )900‬ريــال وأضاف أن‬\n      ‫املزرعــة ال يحيطهــا عقــم ترابــي وال شــبك ‪ ،‬وباالنتقــال إلــى مزرعــة‬\n      ‫املواطــن ‪ .......... /‬تبــن أنهــا تقــع علــى الطريــق الســريع شــرق مركــز‬\n      ‫شــرطة ‪ ..............‬وتبلــغ مســاحتها [‪800‬م ‪800‬م] وال توجــد بهــا حــدود أو‬\n      ‫عقــم أو حاجــز ترابــي ومبعاينتهــا اتضــح وجــود أثــر ســيارة كانــت تســير‬\n      ‫حــول جهــاز الــري احملــوري (الرشــاش) يف منتصــف املشــروع الزراعــي‬\n      ‫ومبتابعــة األثــر اتضــح وصولهــا إلــى مكينــة الرشــاش وتبعــد عــن جهــاز‬\n      ‫الــري احملــوري بحوالــي (‪1200‬م) واتضــح أنــه مت فــك البطاريتــن‬\n      ‫املركبتــن مــن املكينــة وخــرج اجلنــاة مــن املــكان الــذي دخلــوا منــه ‪،‬‬\n      ‫ومبعاينــة املشــروع الزراعــي مــن قبــل قصــاص األثــر اتضــح أنــه بعــد‬\n      ‫مشــاهدة اآلثــار املوجــودة يف املشــروع أنهــا آثــار للجانــي الــذي قــام‬\n      ‫بالســرقة وكذلــك وجــدت آثــار ســيارة يســتفاد منهــا حــال وجــود متهــم‬\n      ‫‪ ،‬وباإلطــاع علــى محضــر تنفيــذ مهمــة رقــم (‪ )0000‬املعــد مــن قبــل‬\n      ‫الدوريــات األمنيــة املتضمــن أنــه يف متــام الســاعة اخلامســة مــن صبــاح يــوم‬\n      ‫األحــد املوافــق ‪0000/0/00‬ه ـ وردهــم بــاغ مــن البحــث اجلنائــي حيــال‬\n      ‫متابعتهــم ســيارة مــن نــوع ‪ ......‬ســنة الصنــع (‪ ).....‬وارتطــم قائدهــا بــدوار‬\n      ‫احلــراج واتضــح فيمــا بعــد أنــه يســتقلها املتهمــون األول والثانــي والثالــث‬\n      ‫وعثــر بحوزتهــم علــى لوحــات لســيارات أخــرى رقــم [‪ ]0000‬ورقــم‬\n      ‫[‪ ]0000‬ورقــم [‪ ]0000‬ورقــم [‪ ]000‬و [‪ ]000‬موديــل [‪1998‬م] ‪ ،‬وجــرى‬\n      ‫التعميــم للبحــث عــن اجلنــاة واملســروقات ‪ ،‬وعليــه ورد محضــر شــعبة‬\n      ‫التحريــات والبحــث اجلنائــي بشــرطة دومــة اجلنــدل بــدون رقــم ‪..........‬‬\n      ‫وبتاريــخ ‪0000/0/00‬ه ـ املتضمــن أنــه يف متــام الســاعة اخلامســة وخمــس‬\n\n\n‫‪193‬‬\n\f‫عشــرة دقيقــة مــن صبــاح يــوم األحــد مت االشــتباه بســيارة مــن نــوع ‪....‬‬\n‫ســنة الصنــع [‪ ].....‬بــدون لوحــة خلفيــة قادمــة مــن اجلهــة الغربيــة باجتــاه‬\n‫احملافظــة وباســتيقافها رفــض قائدهــا الوقــوف فجــرى إبــاغ العمليــات‬\n‫عنهــا وجتــاوز قائدهــا النقطــة األمنيــة األولــى رافض ـ ًا الوقــوف واجتــه‬\n‫مســرع ًا حتــى جتــاوز النقطــة األمنيــة الثانيــة علــى تقاطــع حلــوة رافضـ ًا‬\n‫الوقــوف واجتــه للمخــرج اجلنوبــي للمحافظــة باجتــاه املطــار وعند وصوله‬\n‫جســر [ كبــري ] ‪ ..........‬ســلك طريــق ‪ ..........‬ومبتابعتهــا مت اســتيقافها‬\n‫برفقــة الدوريــات األمنيــة فــاذ قائدهــا ومرافقــوه بالفــرار وبعــد مطــاردة‬\n‫علــى األقــدام مت القبــض عليهــم واتضــح أنهــم املتهمــون األول والثانــي‬\n‫والثالــث وبتفتيــش الســيارة عثــر بداخلهــا علــى (‪ )3‬ثــاث لوحــات نقــل‬\n‫خــاص هــي كالتالــي ‪ ]0000 [:‬ولوحــة رقــم [‪ ]0000‬تعــود لســيارة‬\n‫مســروقة حســب تعميــم شــرطة العزيزيــة رقــم [‪ ]0000‬وتاريــخ‬\n‫‪0000/0/0‬ه ـ ولوحــة رقــم [‪ ]000‬واتضــح أن اللوحــة األماميــة حتمــل‬\n‫الرقــم [‪ ]000‬تخــص ســيارة ‪ ....‬باســم املواطــن ‪ .......... /‬هــذا وبالرجــوع‬\n‫لرقــم هيــكل الســيارة التــي بقيادتهــم مــن واقــع احلاســب اآللــي اتضــح‬\n‫أنهــا الســيارة املســروقة مــن احملطــة ومبعاينتهــا اتضــح أنهــا تعرضــت‬\n‫لتحريــف اخلطــوط اجلانبيــة كمــا أن متــت مالحظــة آثــار (زبــل) غنــم‬\n‫بصنــدوق حوضهــا ‪ ،‬وباســتجواب املدعــى عليــه األول ‪ .......... /‬واقعــة‬\n‫القبــض أفــاد أن الســيارة مــن نــوع ‪ .....‬ســنة الصنــع [‪ ].....‬تعــود للمواطــن‬\n‫‪ .......... /‬واشــتراها منــه قبــل ثالثــة أيــام مقابــل مبلــغ قــدره (‪ )8000‬ريــال‬\n‫دفــع منهــا (‪ )3000‬ريــال وبقــي عليــه (‪ )5000‬ريالواتفقــا علــى أن يدفعهــا‬\n‫بعــد العيــد وينقــل ملكيــة الســيارة إليــه وأضــاف أنــه حوالــي الســاعة‬\n‫اخلامســة والنصــف وأثنــاء توجههــم إلــى االســتراحة الواقعــة بالقــرب مــن‬\n\n\n                                                                                         ‫‪194‬‬\n\f      ‫البحيــرة وأثنــاء طلوعهــم كبــري ‪ ....‬شــاهد دوريــة مــن خلفــه فهــرب‬\n      ‫حتــى ارتطــم بالــدوار ومت القبــض عليهــم وبالنســبة للوحــات الســيارات ال‬\n      ‫يعلــم عنهــا وال تعــود لــه وســبب هروبــه أنــه ال يحمــل لوحــة خلفيــة وال‬\n      ‫يوجــد عقــد مبايعــة بينــه وبــن واســتمارتها معــه وبســؤاله عــن ســرقة‬\n      ‫بطاريتــي املشــروع الزراعــي نفــى قيامــه بالســرقة ‪ ،‬وبســؤاله عــن ســرقة‬\n      ‫احلراثــة أفــاد أن املدعــى عليــه اخلامــس‪ .......... /‬أخبــره أن احلراثــة تعــود‬\n      ‫لــه وطلــب منــه أي نقلهــا إلــى مزرعتــه الواقعــة فذهــب هــو إلــى مــكان‬\n      ‫احلراثــة فوجدهــا واقفــة يف الصناعيــة علــى الشــارع بجــوار محــل بنشــر‬\n      ‫يعمــل فيــه عامــل مينــي اجلنســية فطلــب منــه أن يجهــز لــه ســطحه وأحضــر‬\n      ‫لــه شــخص ًا مصــري اجلنســية ســائق ســطحه واتفــق معــه علــى أن ينقــل‬\n      ‫احلراثــة إلــى مزرعــة اخلامــس ‪ .......... /‬مقابــل مبلــغ وقــدره (‪ )250‬ريــال‬\n      ‫واتصــل هــو علــى اخلامــس ‪ .......... /‬ليخبــره بــأن احلراثــة وصلــت إلــى‬\n      ‫املزرعــة وليدفــع احلســاب للســائق فلــم يــرد علــى اتصالــه وبعــد عــدة أيــام‬\n      ‫اتصــل بــه اخلامــس ‪ .......... /‬وطلــب منــه أن يذهــب إلــى ســائق الســطحة‬\n      ‫املوجــود يف مركــز الشــرطة ليدفــع لــه احلســاب فأجابــه بقولــه ( مالــي‬\n      ‫شــغل فيهــا ) ولــم يقابلــه بعــد ذلــك ولــم يتصــل عليــه كمــا أفــاد أنــه لــم‬\n      ‫يكــن يعلــم أنهــا عائــدة للمواطــن ‪ .......... /‬وأضــاف أنــه تعــرف علــى‬\n      ‫اخلامــس قبــل ثــاث ســنوات بســجن ســكاكا وال يعلــم ملــاذا نقلهــا‬\n      ‫وبســؤاله حيــال واقعــة ســرقة الســيارة مــن نــوع ‪ ....‬رقــم اللوحــة [‪]000‬‬\n      ‫أقــر بالواقعــة بأنــه بــاع ســيارة حيــث أخبــره الثانــي بأنــه ســرق ســيارة مــن‬\n      ‫نــوع ‪ ....‬ســنة الصنــع (‪ ).....‬وباعهــا علــى ‪ /‬مقابــل [‪ ]6000‬ســتة آالف ريــال‬\n      ‫اســتلم منهــا علــى الفــور (‪)4000‬أربعــة آالف ريــال ثــم اســتلم بعــد عــدة‬\n      ‫أيــام مبلــغ وقــدره (‪ )600‬ســتمائة ريــال وباعهــا علــى املذكــور ألن لديــه‬\n\n\n‫‪195‬‬\n\f‫ورشــة وســيارات للتشــليح ‪ ،‬وبســؤاله حيــال واقعــة ســرقة الســيارة مــن‬\n‫نــوع ‪ ....‬ســنة الصنــع [‪ ].....‬حتمــل اللوحــة رقــم [‪ ]0000‬وواقعــة ســرقة‬\n‫األغنــام أقــر بأنــه يف أحــد األيــام مــن شــهر رمضــان شــاهد ســيارة مــن‬\n‫نــوع ‪ .....‬ســنة الصنــع [‪ ]....‬مــع الثانــي الــذي ذكــر لــه أنــه ســرقها مــن‬\n‫أحــد الشــركات يف دومــة اجلنــدل لكــي يقــوم عليهــا بســرقات أخــرى‬\n‫كمــا أقــر بأنــه يف يــوم األربعــاء املوافــق ‪0000/0/00‬ه ـ كان علــى تلك‬\n‫الســيارة ويرافقــه كل مــن الثالــث ‪ .......... /‬والثانــي ‪ .......... /‬وكان هــو‬\n‫يقودهــا وتوجهــوا إلــى ‪ ..........‬بعــد أخــذوا الســيارة مــن اســتراحة الثانــي‬\n‫‪ .......... /‬الواقعــة يف ‪ ....‬فقــد كانــت واقفــة هنــاك وعنــد وصولهــم إلــى‬\n‫‪ ..........‬وقفــوا عنــد أحــد الوايتــات الواقفــة هنــاك وشــاهدوا شــبك غنــم‬\n‫وقــال لهــم الثانــي ‪ .......... /‬سنســرق هــذه االغنــام وتوقفــوا بالقــرب مــن‬\n‫الشــبك الــذي كان مقفــا بســلك حديــدي وكان هــو يراقــب الوضــع‬\n‫لهمــا حتــى ال ينكشــف أمرهــم وترجــل كل مــن الثانــي‪.......... /‬‬\n‫والثالث‪ .......... /‬وأخذوا (‪ )5‬خمســة من األغنام وعادوا إلى االســتراحة‬\n‫‪ .....‬وحملــوا األغنــام علــى ســيارة الثانــي ‪ .......... /‬األخــرى مــن نــوع ‪.....‬‬\n‫لونــه ‪ ..........‬ليذهبــوا بهــا إلــى ‪ ..........‬لبيعهــا وقــد ذكــر لــه الثانــي ‪/‬‬\n‫‪ ..........‬أنــه قــد باعهــا بــ[‪ ]1500‬ريــال ووزع عليهــم وأعطــاه هــو (‪)300‬‬\n‫ثالثمائــة ريــال وأضــاف أنــه يعــرف الثانــي ‪ .......... /‬منــذ حوالــي عــام‬\n‫وكان يعمــل معــه يف شــركة ‪ ..........‬التابعــة لشــركة ‪ ..........‬ومعرفتــه‬\n‫بالثالــث ‪ .......... /‬معرفــة حديثــة وال يعــرف عنــه شــيئ ًا إال أنــه اشــترك‬\n‫معــه ومــع الثانــي ‪ .......... /‬يف ســرقة األغنــام وال يتذكــر مــن قــام بقــص‬\n‫شــريط الشــبك احلديــدي لألغنــام ‪ ،‬وبضبــط إفــادة ‪ .......... /‬أفــاد أن‬\n‫األول ‪ .......... /‬عــرض عليــه ســيارة ســنة الصنــع (‪ )1995‬وهــي الســيارة‬\n\n\n                                                                                          ‫‪196‬‬\n\f      ‫نفســها التــي اســتلمها جهــة الضبــط وأخبــره بأنــه يرغــب يف بيعهــا تشــليح‬\n      ‫فقــال لــه أحضــر الســيارة وبالفعــل أحضرهــا وشــاهدها واشــتراها‬\n      ‫مقابــل (‪ )6000‬ســتة أالف ريــال اســتلم منهــا فــور ًا أربعــة آالف والباقــي‬\n      ‫اســتلم منــه بعــد ذلــك (‪ )600‬ريــال وبقــي لــه (‪ )1400‬ألــف وأربعمائــة‬\n      ‫ريــال وقــد اشــترط هــو علــى األول ‪ .......... /‬مراجعــة املــرور إســقاطها‬\n      ‫ألنــه أحضــر الســيارة بــدون لوحــات وبــدون اســتمارة فاســتعد بذلــك‬\n      ‫بحجــة أنــه يعــرف صاحبهــا وقــد أوكلــه عليهــا وأضــاف أنــه ال توجــد‬\n      ‫بينهمــا ورقــة مبايعــة وأنــه ال يعلــم أن الســيارة مســروقة ‪،‬وباســتجواب‬\n      ‫املدعــى عليــه الثانــي ‪ .......... /‬حيــال واقعــة القبــض أفــاد أنــه يف متــام‬\n      ‫الســاعة اخلامســة والنصــف وأثنــاء توجههــم إلــى اســتراحته الوقعــة قــرب‬\n      ‫‪ ...‬وعنــد خروجهــم مــن كبــري ‪ ...‬اســتوقفتهم دوريــة فهــرب األول‪/‬‬\n      ‫‪ ..........‬ألنــه ال يحمــل لوحــة خلفيــة وحصــل االرتطــام ويعــرف األول ‪/‬‬\n      ‫‪ ..........‬معرفــة قدميــة وقويــة والســيارة تعــود لــأول وقــد اشــتراها قبــل‬\n      ‫ثالثــة أيــام وبإعــادة اســتجوابه حيــال واقعــة القبــض أفــاد أنــه ال يعــرف‬\n      ‫متــى بــدأت العالقــة بــن رفيقــه األول ‪ .......... /‬والثالث ‪ .......... /‬وأضاف‬\n      ‫أن الســيارة التــي ضبطــت معهــم تعــود لــأول ‪ /‬حيــث أخبره أنه اشــتراها‬\n      ‫قبــل ثالثــة أيــام وأنــه لــم يســتخدمها وشــاهدها ألول مــرة يــوم اخلميــس‬\n      ‫حيــث حضــر لــه األول ‪ .......... /‬عليهــا إلــى االســتراحة بدومــة اجلنــدل‬\n      ‫واملــرة الثانيــة عندمــا حضــر إليــه األول ‪ .......... /‬عنــد منزلــه يــوم القبــض‬\n      ‫عليــه واجتهــا إلــى منــزل الثالــث ‪ .......... /‬وأخذاهــا وبعــد صــاة الفجــر‬\n      ‫بســاعة قبــض عليهــم وأضــاف أن الثالــث ‪ .......... /‬كان يشــرب الدخــان‬\n      ‫وكان غيــر صائــم ألنــه مريــض بالســكر أمــا هــو واألول ‪.......... /‬‬\n      ‫كانــا صائمــن ونفــى اشــتراكه يف ســرقة اخلــراف وكذلــك نفــى‬\n\n\n‫‪197‬‬\n\f‫قيامــه بســرقة البطاريتــن ‪ ،‬وبإعــادة اســتجوابه ‪ .......... /‬أقــر بســرقة ‪....‬‬\n‫مــن محطــة ‪ .....‬حتمــل لوحــة ســعودية رقــم [‪ ]..........‬مبشــاركة املدعــى‬\n‫عليــه األول ‪ .......... /‬والرابــع ‪ .......... /‬وقامــوا بتغييــر معاملهــا‬\n‫وبإســتخدامها لســرقة عــدد (( ‪ ))5‬خمــس خــراف مــن أغنــام املدعــو‪/‬‬\n‫‪ ..........‬وبيعهــا علــى أحــد األشــخاص كمــا أقــر بســرقة ‪.....‬يحمــل لوحــة‬\n‫ســعودية رقــم [ ‪ ]..........‬مبحافظــة دومــة اجلنــدل وباســتجواب املدعــى‬\n‫عليــه الثالــث‪ /‬حيــال واقعــة القبــض ـ أفــاد أنــه يف متــام الســاعة اخلامســة‬\n‫والنصــف وأثنــاء توجههــم إلــى االســتراحة العائــدة للثانــي الواقعــة قــرب‬\n‫‪ ...‬مت اســتيقافهم مــن قبــل الدوريــات األمنيــة فلــم يقــف لهــم رفيقــه األول‬\n‫‪ .......... /‬وأخبرهــم أنــه ال يريــد الوقــوف للدوريــة ألنــه مطلــوب والذ‬\n‫بالهــرب حتــى وصولهــم وارتطامهــم بالــدوار ومت القبــض عليهــم وأضاف‬\n‫أن الســيارة تعــود لــأول ‪ .......... /‬وأنــه عنــد ركــوب الســيارة شــاهد‬\n‫لوحــة فســأله عنهــا فأجابــه بقولــه اتركهــا هــذه لوحــة الســيارة كمــا‬\n‫افــاد أن األول لــم يكــن صائمـ ًا وكان يشــرب الدخــان كمــا افــاد بأنــه‬\n‫ال يعــرف األول إال يف يــوم الســبت الســابقة ليــوم القبــض ويعــرف الثانــي‬\n‫منــذ ســنة تقريب ـ ًا ونفــى قيامــه مــع رفيقيــه بســرقة خمــس خــراف ‪.‬‬\n‫وباســتجواب املدعــى عليــه الرابــع ‪ .......... /‬حيــال وقائــع الســرقات‬\n‫أنكــر مــا نســب إليــه وأفــاد أنــه لــم يســرق شــيئ ًا ولــم يشــارك يف الســرقة‬\n‫وأضــاف أنــه تعــرف علــى الثانــي ‪ .......... /‬يف الســجن ولــم يقابلــه إال مــرة‬\n‫واحــدة عنــد محــل زينــة ســيارات يف ســكاكا ولــم يقابلــه بعدهــا نهائيـ ًا‬\n‫وال توجــد بينهمــا أي اتصــاالت هاتفيــة ‪ ،‬وأنــه ال يعــرف األول ‪.......... /‬‬\n‫وال تربطــه بــه أي عالقــة ‪ ،‬وباســتجواب املدعــى عليــه اخلامــس ‪.......... /‬‬\n‫حيــال واقعــة ســرقة احلراثــة نفــى صحــة مــا ذكــره األول ‪ .......... /‬وال‬\n\n\n                                                                                        ‫‪198‬‬\n\f      ‫يعلــم ســبب نقلــه للحراثــة إلــى مزرعتــه وأفــاد بأنــه يعــرف األول ‪.......... /‬‬\n      ‫منــذ ســنتني حيــث تعــرف عليــه يف ســجن ســكاكا وبعــد خروجهمــا‬\n      ‫مــن الســجن تقابــا وحضــر إليــه يف املزرعــة أكثــر مــن مــرة وبينهمــا‬\n      ‫تواصــل مــن خــال اجلــوال وأضــاف أنــه يعمــل يف بيــع وشــراء املعــدات‬\n      ‫الزراعيــة والســكراب بشــكل رســمي وأنــه ال توجــد بينهمــا عــداوة أو‬\n      ‫مشــاكل ‪ 1 .‬ـ ـ بعــرض الســيارة التــي يقودهــا املتهمــن أثنــاء ســرقتهم‬\n      ‫لألغنــام علــى الوافــد ‪ ( .......... /‬راعــي األغنــام ) اســتطاع التعــرف عليهــا‬\n      ‫وأفــاد بأنهــا مطابقــة للســيارة التــي قامــت بســرقة األغنــام ‪ ]2.‬ـ ـ بعــد‬\n      ‫القبــض علــى املتهمــن وبقيادتهــم ‪ .....‬حتمــل لوحة ســعودية رقــم [‪]..........‬‬\n      ‫أقــر قصــاص األثــر بــأن اآلثــار املوجــودة يف مزرعــة املواطــن ‪.......... /‬‬\n      ‫مطابقــة آلثــار الســيارة التــي كانــت بقيــادة املتهمــن ‪ ]3.‬ـ ـ مبواجهــة‬\n      ‫املدعــى عليــه الثانــي ‪ .......... /‬مبــا جــاء يف أقــوال الثالــث ‪ /‬بــأن املفطــر‬\n      ‫هــو األول ‪ .......... /‬أفــاد أنــه يعتقــد أنــه الثالــث [لــم يثبــت جلهــة التحقيــق‬\n      ‫اإلفطــار يف نهــار رمضــان] ‪ ]4. .‬ـ ـ مبجابهــة األول ‪ .......... /‬والرابــع ‪/‬‬\n      ‫ال منهمــا علــى أقوالــه‬   ‫‪ ..........‬بشــأن واقعــة ســرقة احلراثــة أصــر ك ً‬\n      ‫الســابقة ‪ ]5 .‬ـ ـ مت االســتدالل علــى موقــع الســيارة املســروقة مــن الوافــد‬\n      ‫‪ .......... /‬وهــي مــن نــوع ‪ ..........‬حتمــل لوحــة ســعودية رقــم [ ‪ ]..........‬مــن‬\n      ‫قبــل املدعــى عليــه األول ‪ ]6 .......... /‬ـ ـ مت االســتدالل علــى موقــع الســيارة‬\n      ‫املســروقة العائــدة للمواطــن ‪ .......... /‬مــن نــوع ‪ ..........‬يحمــل لوحــة‬\n      ‫ســعودية رقــم [ ‪ ]..........‬مــن قبــل املدعــى عليــه األول ‪ .......... /‬وذلــك يف‬\n      ‫مزرعــة مهجــورة يف قريــة ‪ ..........‬وعثــر عنــد موقــع آثــار الســيارة املخفيــة‬\n      ‫علــى آثــار أقــدام اتضــح أنهــا مطابقــة آلثــار أقــدام املدعــى عليــه الثانــي ‪/‬‬\n      ‫‪ ]7 ..........‬ـ ـ مبجابهــة املدعــى عليــه األول ‪ .......... /‬باملدعــى عليــه الثالــث‬\n\n\n‫‪199‬‬\n\f‫‪ .......... /‬حيــث اعتــراف األول بســرقة عــدد ((‪ ))5‬خمســة خــراف مــن‬\n‫األغنــام وقيــام الثانــي مبشــاركته بســرقة األغنــام نفــى ذلــك واتضــح‬\n‫علــى الثانــي ‪ .......... /‬االرتبــاك أثنــاء املجابهــة ‪ ]8.‬ـ ـ مبجابهــة املدعــى‬\n‫عليــه الثانــي ‪ .......... /‬باملدعــى عليــه الثالــث ‪ .......... /‬حيــث اعتــرف‬\n‫الثانــي ‪ .......... /‬بســرقة عــدد ((‪ ))5‬رؤوس مــن األغنــام وقيــام الثالــث‬\n‫باملشــاركة يف الســرقة نفــى الثالــث ذلــك واتضــح علــى الثانــي ‪.......... /‬‬\n‫االرتبــاك أثنــاء املجابهــة ‪ ]9 .‬ـ ـ رفــض الوافــد ‪ .......... /‬اســتالم ســيارة‬\n‫كفيلــه مــن نــوع ‪ .....‬حتمــل لوحــة ســعودية رقــم ‪ ]..........‬ســنة الصنــع [‪]....‬‬\n‫وذلــك ألن حالتهــا غيــر جيــدة وتعرضــت للتغيــر ويرفــض اســتالمها إال‬\n‫بعــد فحصهــا وإعــادة النواقــص ‪ ]10.‬ـ ـ اســتلم املواطــن ‪ .......... /‬الســيارة‬\n‫املســروقة وهــي مــن نــوع ‪ ....‬حتمــل لوحــة ســعودية رقــم [‪ ]..........‬واتضــح‬\n‫أنهــا تعرضــت للصــدم وبهــا أضــرار ويطالــب املتســببني بذلــك بإصالحها‬\n‫‪ ]11.‬ـ ـ مت مخاطبــة شــرطة محافظــة دومــة اجلنــدل إلصــدار مخالفــات‬\n‫مروريــة علــى املتهمــن حيــال جتاوزهــم النقطــة األمنيــة وتغييــر مالمــح‬\n‫الســيارات املســروقة والعبــث بهــا ‪ ،‬وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫ل ــلمدعى عليهــم ‪ .......... /‬بتشــكيل عصابــة لســرقة عــدة ســيارات‬\n‫واســتخدامها لســرقة عــدد (‪ )5‬رؤوس مــن األغنــام وســرقة عــدد‬\n‫بطاريتــن مقــاس [‪ ]1120‬أمبيــر والتســبب يف إحــداث تلفيــات يف‬\n‫الســيارات املســروقة وتغييــر معاملهــا والهــرب مــن رجــال األمــن ولــ‪/‬‬\n‫‪ ..........‬بســرقة احلراثة ولـ‪ /‬باملشــاركة يف ســرقة الســيارات ولـ ‪.......... /‬‬\n‫بالتحريــض والتســتر علــى ســرقة حراثــة ‪ ،‬وباإلطــاع علــى صحيفــة‬\n‫ســوابقهم عثــر للمتهــم األول علــى أربع ســوابق ( محاولــة لواط ‪ ،‬التهديد‬\n‫‪ ،‬مضاربــة داخــل الســجن ‪ ،‬اســتدراج ‪ ،‬تهمــة لــواط ‪ ،‬حيــازة واســتعمال‬\n\n\n                                                                                         ‫‪200‬‬\n\f      ‫مخــدرات ) أمــا الثانــي عثــر لــه علــى ســابقة واحــدة (ســطو) أمــا الثالــث‬\n      ‫عثــر لــه علــى خمــس ســوابق ( مخــدرات ‪ ،‬حيــازة واســتعمال مخــدرات ‪،‬‬\n      ‫شــرب املســكرات ‪ ،‬هــروب مــن الســلطة ‪ ،‬التهجــم علــى شــخص يف‬\n      ‫مقــر عملــه ‪ ،‬متاجــرة باألســلحة ) أمــا الرابــع عثــر لــه علــى ســابقتي‬\n      ‫(ســرقة) وعثــر للخامــس علــى ســابقة ســرقة ‪ ،‬وحيــث إن مــا أقــدم عليــه‬\n      ‫املذكــورون وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n      ‫عليــه شــرع ًا وهــو ســرقة مــال محتــرم مــن حــرزه بعــد هتكــه ال شــبه لهــم‬\n      ‫فيــه يزيــد علــى النصــاب ممــا يتعــن معــه إحالتهــم إلــى احملكمــة العامــة‬\n      ‫وفق ـ ًا للمــواد [‪ ]129،127،126‬مــن نظــام اإلجــراءات اجلزائيــة لــذا‬\n      ‫أطلــب إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم عليهــم مبــا يلــي ‪ ]1‬ـ ـ حــد‬\n      ‫الســرقة للمتهــم األول والثانــي والثالــث الــوارد ذكرهــا يف ســورة املائــدة‬\n      ‫اآليــة (‪ ]3.)68‬ـ ـ عقوبــة تعزيريــة للمتهمــن الرابــع واخلامــس ( تنــازل‬\n      ‫املواطــن ‪ .......... /‬عــن حقــه فيمــا يتعلــق بســرقة األغنــام ‪.‬تنــازل املواطــن‬\n      ‫‪ .......... /‬عــن حقــه فيمــا يتعلــق ببالغــه بســرقة ســيارة والــده ) هــذه‬\n      ‫دعــواي وبعــرض الدعــوى علــى املدعــى عليهــم األول والثانــي والثالــث‬\n      ‫والرابــع قــرروا جميعـ ًا إنــه ال صحــة لدعــوى املدعــي العــام هكــذا قــرروا‬\n      ‫وحيــث لــم يحضــر املدعــى عليــه اخلامــس فقــد رفعــت اجللســة إلحضــار‬\n      ‫املدعــى عليــه اخلامــس وطلــب البينــة مــن املدعــي العــام علــى دعــواه ويف‬\n      ‫جلســة أخــرى حضــر املدعــي العــام واملدعــى عليهــم األول والثانــي‬\n      ‫والثالــث والرابــع ولــم يحضــر املدعــى عليــه اخلامــس ‪ ....‬والــذي تبــن أنــه‬\n      ‫يقيــم بــ‪ ...‬ولــم يقــم املدعــي العــام بإحضــار شــهود يف هــذه الدعــوى هــذا‬\n      ‫وقــد جــرى منــا الرجــوع إلــى أدلتــه املرفقــة باملعاملــة فوجدنــا محضــر‬\n      ‫القبــض علــى اللفــة ‪ 33‬وهــذا نصــه ( يف متــام الســاعة اخلامســة وخمــس‬\n\n\n‫‪201‬‬\n\f‫عشــرة دقيقــة مــن صبــاح هــذا اليــوم األحــد املوافــق ‪000/00/00‬ه ـ مت‬\n‫االشــتباه بســيارة ‪ ....‬موديــل ‪ ....‬بــدون لوحــه خلفيــة قادمــة مــن اجلهــة‬\n‫الغربيــة باجتــاه احملافظــة ومت طلــب الوقــوف منــه ورفــض وجــرى ابــاغ‬\n‫العمليــات عــن تلــك املركبــة وجتــاوز النقطــة االمنيــة االولــى رافض ـ ًا‬\n‫الوقــوف واجتــه مســرع ًا حتــى جتــاوز النقطــة األمنيــة الثانيــة والتــي‬\n‫كانــت بتقاطــع حلــوه ورفــض الوقــوف ايض ـ ًا واجتــه للمخــرج اجلنوبــي‬\n‫للمحافظــة باجتــاه املطــار وعنــد وصولــه كبــري ‪ ....‬ســلك طريــق ‪....‬‬\n‫ومتــت متابعتــه حتــى اســتوقفنا تلــك الســيارة برفقــة الدوريــات االمنيــة‬\n‫وقــد الذ قائــد املركبــة ومرافقــوه بالفــرار ومت القبــض عليهــم بعــد‬\n‫ال من‪1:‬ـ‪2..........‬ـ‪(..........‬مطلــوب‬ ‫مطــاردة علــى االقــدام واتضــح أنهــم ك ً‬\n‫علــى اثــر قضيــة جنائية ســابقة) ‪3‬ـ‪..........‬وبتفتيــش املركبة عثر بداخلها‬\n‫علــى (‪ )3‬ثالثــة لوحــات نقــل خاص كالتالي‪ )..........( )..........( :‬الســيارة‬\n‫مســروقة حســب تعميــم مديــر شــرطة العزيزيــة رقــم ‪ ..........‬وتاريــخ‬\n‫‪0/0/0000‬ه ـ (‪ )..........‬واتضــح أن اللوحــة االماميــة حتمــل الرقــم‬\n‫(‪ )..........‬تخــص ســيارة ‪ ....‬باســم املواطــن‪ ++.......... /‬هــذا وبالرجــوع‬\n‫لرقــم هيــكل تلــك الســيارة التــي بقيادتهــم مــن واقــع احلاســب اآللــي‬\n‫أتضــح أنهــا الســيارة املســروقة مــن محطــة ‪ ..........‬ومبعاينــة تلــك املركبة‬\n‫اتضــح أنهــا تعرضــت لتحريــف اخلطــوط اجلانبيــة كمــا انــه متــت مالحظــة‬\n‫اثــار (لزبــل) الغنــم بحــوض تلــك الســيارة ونظــر ًا لوجــود ســرقات اغنــام‬\n‫جــرى توثيــق ذلــك بهــذا احملضــر وبــه حــرر واهلل املوفــق أ‪.‬ه ـ كمــا جرى‬\n‫منــا اإلطــاع علــى اعترافــات املدعــى عليــه األول علــى اللفــه ‪ 00‬ص‪0‬‬\n‫وهــذا نصــه ( أقــر أنــا املدعــو‪ .......... /‬ســعودي اجلنســية بالهويــة الوطنيــة‬\n‫رقــم ‪ ..........‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا وبــدون إجبــار أو‬\n\n\n                                                                                          ‫‪202‬‬\n\f      ‫إكــراه مــن أحــد انــه يف يــوم االربعــاء بحــدود الســاعة اخلامســة تقريب ـ ًا‬\n      ‫مــن يــوم االربعــاء املوافق‪0000/00/00‬ه ـ أثنــاء تواجــدي بدومــة اجلنــدل‬\n      ‫ال من‪..........‬و‪..........‬علــى ســيارة ‪ ....‬يعــود وذهبنــا لــل‪....‬‬\n                                                                         ‫حضــر لــي ك ً‬\n      ‫وقمنــا بإيقــاف ‪ ...‬داخــل اســتراحه بــال‪ ....‬وخرجنــا بســيارة نــوع ‪....‬‬\n      ‫كان مخفيهــا داخــل اســتراحته كان ســارقها قبــل فتــره واجتهنــا لقرية‬\n      ‫‪ ....‬حتــى وصلنــا مزارعهــا شــمال القريــة وكان غرضنــا الســرقة وال‬\n      ‫حظنــا شــبك أغنــام بجانــب مزرعــة وعنــده وايــت وال يوجــد عنــده أحــد‬\n      ‫وتوقفنــا عنــده وكنــت أنــا اقــود الســيارة ونزلنــا وحمــل‪ ..........‬و‪..........‬‬\n      ‫عــدد خمســة خرفــان مــن الشــبك وأنــا كنــت أراقــب ومتهيــىء للتحــرك‬\n      ‫وحتركنــا الســتراحة بالــ‪ .....‬وقــت اإلفطــار ودخلنــا داخــل االســتراحة‬\n      ‫وحملنــا اخلرفــان بــال‪ ....‬الــذي يعــود وأخفينــا الســيارة املســروقة‬\n      ‫باالســتراحة واجتهنــا الســتراحة الثانيــة الواقعــة ‪ ....‬ونزلــت أنــا و وذهــب‬\n      ‫لغــرض تصريــف اخلرفــان وبيعهــا علــى شــخص يعرفــه يفيــد أنــه بقــارا‬\n      ‫وبقيــت أنــا و باالســتراحة وبحــدود الســاعة العاشــرة تقريبـ ًا عــاد وكان‬\n      ‫معــه مبلــغ ألــف وخمســمائة ريــال وأعطانــي ثالثمائــة ريــال (‪ )300‬هــذا‬\n      ‫وعلــى اقــراري أوقــع االســم‪ )..........:‬واعترافــه علــى اللفــه ‪ 00‬ص‪ 0‬وهــذا‬\n      ‫نصــه ( أقــر واعتــرف أنــا ‪ ........../‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم (‪ )..........‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا دون‬\n      ‫جبــر أو اكــراه بأننــي قمــت ببيــع ســيارة ‪ ...‬موديــل ‪ ...‬كان قــد ســرقها‬\n      ‫حســب مــا أخبرنــي بــه ولــم يخبرنــي بتفاصيــل الســرقة واتضــح أنهــا‬\n      ‫موديــل ‪ ....‬حيــث قمــت ببيعهــا علــى املدعــو‪ .......... /‬حيــث اخــذت دور‬\n      ‫الوســيط وذلــك مقابــل ســتة أالف ريــال اســتلمت منهــا علــى الفــور أربعــة‬\n      ‫أالف ريــال ثــم عــدت بعــد أيــام واســتلمت ســتمائة ريــال وباقــي عنــده‬\n\n\n‫‪203‬‬\n\f‫مبلــغ ألــف وأربــع مائــة ريــال وقــد اختــرت املدعــو لوجــود ورشــه لديــه‬\n‫وملعرفتــي أن لديــه عــدد مــن الســيارات املشــلحه وعلــى مــا تقــدم جــرى‬\n‫التوقيــع‪ :‬املقــر مبــا فيــه) كمــا وجدنــا أقوالــه علــى اللفــه ‪ 0‬ص‪ 0‬وهــذا‬\n‫نصهــا ( كان املدعــو‪ .......... /‬قــد طلــب منــي نقــل هــذه احلراثــة حيــث‬\n‫ذكــر لــي بــأن احلراثــه عائــده لــه ويريــد أن بنقلهــا الــى مزرعتــه الواقعــة‬\n‫‪ ...‬وبالفعــل قمــت بالذهــاب إلــى مــكان احلراثــة حيــث كانــت واقفــه يف‬\n‫الصناعيــة علــى الشــارع وكان بجوارهــا محــل بنشــر ويعمــل فيــه عامــل‬\n‫مينــي وقلــت لــه بــأن يحضــر لــي ســطحه وأحضــر لــي شــخص مصــري ال‬\n‫أعرفــه ســوى أنــه ســائق ســطحه واتفقــت معــه علــى أن يقــوم بنقــل احلراثة‬\n‫الــى مزرعــة ‪ ....‬مببلــغ ‪ 250‬ريــال وبعدهــا قمــت باالتصــال علــى لكــي‬\n‫اخبــره بــان احلراثــة وصلــت للمزرعــة وان يقــوم بدفــع حســاب ســائق‬\n‫الســطحه ولــم يــرد علــى تلفونــي وبعدهــا بكــم يــوم اتصــل علــى وقــال‬\n‫اذهــب إلــى ســائق الســطحه حيــث كان متواجــد بالشــرطة لكــي أقــوم‬\n‫بدفــع احلســاب وقلــت لــه مالــي شــغل فيهــا وبعدهــا لــم أقابلــه ولــم اتصــل‬\n‫عليه)واعترافــه علــى اللفــه ‪ 00‬ص‪ 0‬وهــذا نصــه ( أقــر أنــا املدعــو‪/‬‬\n‫‪ ..........‬ســعودي مبوجــب الســجل بالهويــة املوضحــه رقــم ‪ ..........‬وأنــا‬\n‫بكامــل قــواي العقليــة املعتبــرة شــرع ًا أنــه يــوم اجلمعــة املوافــق ( بــدون )‬\n‫كنــت أنــا و نتمشــى بالــوادي علــى ‪ ....‬يعــود مررنــا مــن عنــد ســيارة نــوع‬\n‫‪ ...‬امــام منــزل وكنــت أنــا الســائق وقــال وقــف عنــد ‪ ....‬وكان مفتــوح‬\n‫ونــزل ‪ .....‬وقــال حتــرك ســوف أحلقــك علــى ‪ ....‬حيــث الحــظ أن مفتــاح‬\n‫اجليــب عليــه وتقابلنــا باملزرعــة وقمنــا بإخفــاء ‪ ....‬بحــوش بيــت مهجــور ‪....‬‬\n‫وكان مفتــاح ‪ ...‬مــع ‪ ....‬مخفيــه معــه باملنــزل هــذا وعلــى اقــراري اوقــع‪.‬‬\n‫االســم‪ ).......... :‬كمــا وجدنــا اعتــراف املدعــى عليــه الثانــي علــى اللفــه‬\n\n\n                                                                                         ‫‪204‬‬\n\f      ‫ص وهــذا نصــه ( أقــر واعتــرف أنــا املوقــع أدناه ســعودي اجلنســية بالهوية‬\n      ‫رقــم (‪ )..........‬وأنــا بكامــل قــواي العقليــة واملعتبــرة شــرع ًا دون جبــر أو‬\n      ‫إكــراه أننــي قمــت أنــا وكذلــك املدعــو‪ .......... /‬بســرقة ســيارة ‪...‬‬\n      ‫موديــل ‪98‬م مــن موقــع بالقــرب مــن محطــة ‪ ....‬حيــث ركــب مــكان‬\n      ‫ســائق الســيارة وشــغل الســيارة باســتخدام مفتاح آخر حيث أنها تشــتغل‬\n      ‫بــأي مفتــاح واجتهنــا بهــا ‪ ....‬وكان ذلــك بحــدود تاريــخ العاشــر مــن هــذا‬\n      ‫الشــهر شــهر رمضــان لعــام ه ـ كمــا أننــا قمنــا قبــل ذلــك بآخــر شــهر‬\n      ‫شــعبان تقريب ـ ًا وال أعــرف التاريــخ بالتحديــد بســرقة ســيارة ‪ ....‬موديــل‬\n      ‫‪90‬م مــن شــركة تقــع ‪ ...‬مبدينــة ســكاكا حيــث كان املفتــاح عليهــا‬\n      ‫ثــم قــام بعــد ذلــك بيومــن ببيــع الســيارة علــى املدعــو باالضــارع وذلــك‬\n      ‫بعــد أن تركنــا عــن الســيارة اخلــط اجلانبــي مقابــل اربعــة آالف ريــال‬\n      ‫وتفاصيــل البيــع لــدى كمــا قمــت أنــا واملدعــو بســرقة ‪ .....‬موديــل ‪2009‬م‬\n      ‫مــن ‪ ...‬حيــث الحــظ املفتــاح علــى ‪ ...‬بينمــا كنــا علــى ســيارتي ‪ ....‬ونــزل‬\n      ‫ال بــل نزلــت أنــا وأخــذت ‪ ....‬املســروق مــن موقعــه واجتهنــا ‪....‬ووضعهــا‬\n      ‫مبزرعــة والــد ‪ ..........‬كمــا قمــت انــا وكذلــك باالجتــاه ‪ ..........‬حيــث‬\n      ‫شــاهدنا أغنــام بشــبك بالقــرب مــن مزرعــة‪ ..........‬وذلــك يــوم األربعــاء‬\n      ‫املوافــق ‪0000/00/00‬ه ـ وقمنــا بســرقة عــدد خمســة رؤوس أغنــام علــى‬\n      ‫الســيارة ‪ ....‬موديــل ‪98‬م التــي ســبق وأن ذكــرت أننــا ســرقناها واجتهنــا‬\n      ‫لورشــتي بــال‪ ....‬ونقلنــا اخلرفــان علــى ســيارتي ‪ ....‬واجتهنــا جميعنــا إلــى‬\n      ‫‪....‬حيــث قابلنــا شــخص يعرفــه وهــو معــروف باســم‪ .......... /‬والــذي‬\n      ‫اتضــح أنــه يدعــى حســب الصــور التــي شــاهدتها حيــث قــام ببيــع تلــك‬\n      ‫األغنــام عليــه مقابــل الــف وخمســمائة ريــال واهلل علــى مــا أقــول شــهيد‬\n      ‫املقــر مبــا فيــه‪ ).......... /‬واعترافــه علــى اللفــة ص وهــذا نصــه ( أقــر أنــا‬\n\n\n‫‪205‬‬\n\f‫املدعــو‪ .......... /‬ســعودي اجلنســية بالهويــة رقــم ‪ ..........‬وأنــا بكامــل‬\n‫قــواي العقليــة املعتبــرة شــرع ًا وبــدون إجبــار أو إكــراه أنــه قبــل شــهر‬\n‫بآخــر شــهر ‪ 9‬املاضــي اتصــل علــي املدعــو‪ .......... /‬وأخبرنــي بــأن عنــده‬\n‫ســياره قــام بســرقتها مــن شــركة ‪ ....‬نوعهــا ‪....‬موديــل ‪ 90‬وحضــر وبقيت‬\n‫عنــدي يومــان لكــي ابيعهــا لــه وقمــت بإعطائهــا املدعــو‪ .......... /‬علــى ان‬\n‫يقــوم ببيعهــا وباعهــا علــى املدعــو‪ .......... /‬مببلــغ ســتة اآلف ريال (‪)6000‬‬\n‫وأعطــى املبلــغ وأعطانــي مبلــغ خمســمائة ريــال (‪ )500‬علمـ ًا أن لم يســتلم‬\n‫مــن قيمــة الســيارة إال أربعــة أالف وباقــي ألفــا ريــال (‪ )2000‬هــذا وعلــى‬\n‫إقــراري أوقــع‪ .‬االســم‪ ).......... :‬واعترافــه علــى اللفــة ‪ ....‬ص ‪ ...‬وهــذا‬\n‫نصــه ( أقــر واعتــرف أنــا املوقــع أدنــاه‪ .......... /‬ســعودي مبوجــب الهويــة‬\n‫رقــم (‪ )..........‬أقــر وانــا بكامــل قــواي املعتبــرة شــرع ًا دون جبــر أو‬\n‫ال مــن‪ .......... /‬بســرقة عــدد‬ ‫اكــراه أننــي قمــت مبشــاركة زمالئــي ك ً‬\n‫خمســة خــراف مــن شــبك أغنــام يقــع ‪....‬بالقــرب مــن مزرعــه وذلــك يــوم‬\n‫األربعــاء املوافق‪0000/0/00‬هـ ـ قبــل صــاة املغــرب بحــدود ســاعتني‬\n‫وقمنــا بتحميلهــا علــى ســيارة ‪....‬موديــل ‪98‬م كانــت مــع وهــو ســائق‬\n‫الســيارة ثــم اجتهنــا إلــى ورشــتي بــال‪ ....‬وقمنــا باســتبدال الســيارة حيــث‬\n‫نقلنــا اخلرفــان بالــ‪ ....‬العائــد لــي واجتهنــا باخلرفــان الى ‪....‬وقابلنا شــخص‬\n‫يدعــى بأحــد املــزارع التــي تقــع جنــوب ‪....‬واســتلم اخلرفــان وقــام بتســليمنا‬\n‫مبلــغ ألــف وخمســمائة ريــال اقتســمناها أنــا وزمالئــي بالتســاوي حيــث‬\n‫نصيــب كل واحــد خمســمائة ريــال وعلــى مــا تقــدم جــرى التوقيــع‪ .‬املقــر‬\n‫مبــا فيــه‪).......... /‬كمــا وجدنــا اعتــراف املدعــى عليــه الثالــث علــى‬\n‫اللفــه ص وهــذا نصــه ( أقــر أنــا املدعو‪ ........../‬ســعودي اجلنســية بالهوية‬\n‫رقــم ‪ 0000000000‬أقــر واعتــرف بــدون إجبــار مــن أحــد أو إكــراه وأنــا‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫بكامــل قــواي العقليــة املعتبــرة شــرع ًا أنــه يــوم االربعــاء بحــدود الســاعة‬\n      ‫اخلامســة مســاء ًا تقريب ـ ًا املوافــق ‪0000/00/00‬ه ـ كنــت مرافق ـ ًا‬\n      ‫واملدعــو‪ .......... /‬علــى ســياره ‪ ....‬وذهبنــا لقريــة ‪....‬حتــى وصلنــا املــزارع‬\n      ‫ووجدنــا شــبك بجانــب أحــد املــزارع يوجــد بــه أغنــام وتوقفنــا بجانبــه‬\n      ‫وقمنــا بتحميــل عــدد خمســة خــراف وعنــد وصولنــا لقريــة ال ــ‪ ....‬قمنــا‬\n      ‫بتحميــل اخلــراف بســياره ثانيــه ‪ ....‬يعــود ‪....‬واجتهنــا لســكاكا (‪)....‬‬\n      ‫ال مــن و هــذا‬     ‫لغــرض بيــع اخلرفــان علــى شــخص يعرفونــه زمالئــي ك ً‬\n      ‫وعلــى إقــراري واعتــرايف أوقــع‪ .‬االســم‪ ).......... :‬كمــا وجدنــا احملضــر‬\n      ‫املرفــق علــى اللفــة ‪ ..‬ص‪ .‬وهــذا نصــه ( احلمــدهلل والســام علــى رســول‬\n      ‫اهلل وبعــد إنــه بعــد اعتــراف املتهــم ببيــع ســيارة موديــل ‪ 90‬نــوع ‪ ....‬علــى‬\n      ‫املواطــن وبعــد التأكــد مــن أن الســيارة التــي قــام ببيعهــا هــي الســيارة‬\n      ‫املســروقة مــن املقيــم‪ .......... /‬ســوداني اجلنســية وقــد مت التعميــم عنهــا‬\n      ‫مــن قبــل مركــز شــرطة العزيزيــة وحتمــل لوحــة رقــم ( ‪ )..........‬وبنــاء‬\n      ‫عليــه فقــد مت انتقالــن الــى موقــع الســيارة الــذي تبــن أنهــا ورشــة تقــع يف‬\n      ‫قريــة ‪....‬تعــود للمدعــو‪ .......... /‬الــذي أقــر بشــرائها مــن املدعــو‪.......... /‬‬\n      ‫هــذا وقــد عثــر علــى الســيارة املذكــوره داخــل الورشــة وقــد مت تغييــر‬\n      ‫بعــض معالــم الســيارة وبعــد التأكــد ومطابقــة رقــم الهيــكل ثبــت أنهــا‬\n      ‫الســيارة املســروقة واملعمــم عليهــا مــن قبــل شــرطة العزيزيــة مبوجــب‬\n      ‫التعميــم رقــم ‪ 0000‬يف ‪0000/00/00‬ه ـ ومت ســحب الســيارة للحجــز‬\n      ‫بالشــرطة علم ًا أن الســيارة كانت متعطله وال تعمل ومت نقلها بواســطة‬\n      ‫ســيارة نقــل واهلل املوفــق رئيــس رقبــاء ‪ .......... /‬ورئيــس رقبــاء‪ .......... /‬و‬\n      ‫مديــر شــعبة التحريــات والبحــث اجلنائــي ) كمــا وجدنــا محضــر‬\n      ‫املواجهــة بــن األول والثالــث علــى اللفــة ‪ 00‬ص‪ 00‬وهــذا نصــه ( يف متــام‬\n\n\n‫‪207‬‬\n\f‫الســاعة العاشــرة مســاء يــوم اجلمعــة التاريــخ أعــاه متــت املجابهــة بــن‬\n‫ال مــن املتهــم‪ .......... /‬بزميلــه املتهــم‪ .......... /‬حيــث أقــر املتهــم األول‪/‬‬\n                                                                                    ‫ك ً‬\n‫‪ ..........‬أنــه قــام بســرقة عــدد خمســة خــراف مــن شــبك أغنــام يقــع شــمال‬\n‫قريــة ‪....‬بالقــرب مــن احــدى املــزارع وكان يشــاركه بتلــك الســرقة‬\n‫ال مــن زميــاه املتهمــان‪ .......... /‬املذكــور وكذلك ‪ .......... /‬وبعرض‬            ‫ك ً‬\n‫مــا ذكــره أثنــاء املجابهــة أنكــر املتهــم ‪....‬املذكــور جملــة وتفصيــا‬\n‫وأصــر علــى مشــاركة لهــم بالســرقة وحــاول إقناعــه باإلعتــراف مبــا‬\n‫فعلــوه ولكــن أصــر علــى أنــكاره ويتضــح لنــا مــن خــال املجابهــة صــدق‬\n‫وارتبــاك والــذي أســتمر بالنظــر لزميلــه بعينيــه وكأنــه يعاقبــه علمـ ًا أنــه‬\n‫مت القبــض عليهــم جميعـ ًا بســياره مســروقه وهــي نفســها الــذي اســتخدم‬\n‫بســرقة األغنــام‪ .‬هــذا ومت ضبــط احملضــر والتوقيــع عليــه املتهــم األول‬\n‫املتهــم الثانــي) كمــا وجدنــا محضــر االســتدالل علــى اللفــة ص وهــذا‬\n‫نصــه ( احلمــدهلل والصــاة والســام علــى رســول اهلل وبعــد مت انتقالنــا‬\n‫نحــن رجــال الضبــط اجلنائــي املوقعــن أدنــاه إلــى موقع الســيارة املســروقة‬\n‫نوعهــا ‪ ....‬موديــل ‪2009‬م حــوض رقــم اللوحــة (‪ )..........‬برفقــة أحــد اجلنــاة‬\n‫املتهــم حيــث قــام بإرشــادنا إلــى املوقــع الــذي مت إخفــاء الســيارة فيــه‬\n‫واتضــح اآلتــي‪ :‬مت االنتقــال يف متــام الســاعة الرابعــة والنصــف عصــر ًا‬\n‫مــن يــوم األربعــاء ‪0000/00/00‬ه ـ إلــى موقــع اخفــاء ‪ ....‬يف مزرعــه‬\n‫مهجــوره تقــع شــمال ‪ ..........‬بحوالــي ســتة كيلومتــر تعــود ووجــد ‪....‬‬\n‫مخبــأ داخــل غــرف مهجــوره وبالتأكــد منــه اتضــح أنــه نفس ‪....‬املســروق‬\n‫ومبطابقــة أوراق إثبــات الســيارة مت معاينــة الســيارة واتضــح ســامتها‬\n‫وأن اجلنــاه قــد قامــوا بثنــي اللوحــة اخللفيــة وفــك اللوحــة األماميــة ومت‬\n‫إخفائهــا خلــف مقعــد الســائق وقــد مت رفــع البصمــات مــن الســيارة‬\n\n\n                                                                                           ‫‪208‬‬\n\f      ‫قصــاص األثــر وتصويــر الســيارة‬      ‫ومعاينــة آثــار األقــدام مــن قبــل ّ‬\n      ‫قصــاص‬ ‫وإحضارهــا للشــرطة وبإحضــار املتهــم ومطابقــة آثــاره مــن قبــل ّ‬\n      ‫األثــر طابقــة آثــار املتهــم اآلثــار التــي عثــر عليهــا عنــد الســيارة هــذا ومت‬\n      ‫ضبــط هــذا احملضــر حفظ ـ ًا للواقــع والتوقيــع عليــه ‪ .‬وبعــرض محضــر‬\n      ‫ا أمــا مــاورد يف‬ ‫القبــض وأقــوال املدعــى عليــه األول عليــه أجــاب قائ ـ ً‬\n      ‫محضــر القبــض فهــو صحيــح ولكننــي قــد أخــذت الســيارة املســروقة‬\n      ‫التــي كانــت بقيادتــي مــن املدعــى عليــه الثانــي ولــم أكــن أعلــم أنهــا‬\n      ‫مســروقه وأمــا مــا يتعلــق بالســيارة التــي رقــم لوحتهــا (‪ )..........‬فإننــي‬\n      ‫كنــت وســيط ًا يف هــذه الســيارة بــن املدعــى عليــه وصاحــب الورشــة‬\n      ‫حيث مت بيع هذه الســيارة على وكان يقول لصاحب الورشــة ســأكمل‬\n      ‫أوراقهــا عنــد املــرور بعــد العيــد كمــا أفيدكــم بــأن جميــع هــذه‬\n      ‫االقــرارات مختومــة ببصمتــي وتوقيعــي ولكنهــا حتــت الضــرب‬\n      ‫واإلكــراه هــذا مالــدي وبعــرض احملضــر وإقــرارات املدعــى عليــه الثاني‬\n      ‫ا ( جميــع هــذه اإلقــرارات مختومــة بتوقيعــي‬        ‫‪ ..........‬عليــه قــرر قائ ـ ً‬\n      ‫وبصمتــي وال صحــة ملــا جــاء فيهــا حيــث إننــي كنــت حتــت التهديــد‬\n      ‫واإلكــراه هــذا مالــدي وبســؤاله عمــا جــاء يف أقــوال املدعــى عليــه األول‬\n      ‫ضــده قــال ال صحــة لذلــك وبســؤاله عــن ســبب هروبــه مــن الدوريــة وهــو‬\n      ‫لــم يفعــل شــيئ ًا قــال إننــي هربــت مــن الدوريــة ملــا ذكــره مــن أن الســيارة‬\n      ‫بــدون لوحــه هكــذا قــرر وبعــرض احملضــر واإلقــرار املنســوب للمدعــى‬\n      ‫عليــه الثالــث عليــه أجــاب بقولــه مــا ذكــره يف احملضــر مــن أنــه مت‬\n      ‫القبــض عليــه مــع املدعــى عليــه األول والثانــي فهــذا صحيــح وأمــا ماعــدا‬\n      ‫ذلــك ممــا نســب إلـ ّـي مــن الســرقة فهــذا غيــر صحيــح كمــا أفيــد بأننــي‬\n      ‫قــد بصمــت ووقعــت علــى إقــراري حتــت التهديــد والضــرب هــذا مالــدي‬\n\n\n‫‪209‬‬\n\f‫وعنــد هــذا احلــد فقــد طلبنــا البينــة مــن املدعــى عليهــم األول والثانــي‬\n‫والثالــث علــى مــا دفعــوا بــه كمــا طلبنــا مــن املدعــي العــام مزيــد بينــه‬\n                                                      ‫على دعواه ورفعت اجللسة‬\n‫ويف جلســة أخــرى وفيهــا حضــر املدعــي العــام واملدعــى عليهــم األول‬\n‫والثانــي والثالــث والرابــع ولــم يحضــر املدعــى عليــه اخلامــس املقيــم‬\n‫بســكاكا ولــم يتــم إحضــار مزيــد بينــة مــن املدعــي العــام علــى دعــواه‬\n‫ســوى مــا يف أوراق املعاملــة كمــا أنــه لــم يقــم املدعــى عليهــم بإحضــار‬\n‫بينــة علــى مــا دفعــوا بــه لــذا فقــد قررنــا إمهالهــم ويف يــوم اإلثنــن‬\n‫املوافق‪0000/00/00‬ه ـ ه حضــر املدعــي العــام واملدعــى عليهــم األول‬\n‫والثانــي والثالــث والرابــع ولــم يحضــر املدعــى عليــه اخلامــس والــذي يقيم‬\n‫بســكاكا وباالطالع على أوراق املعاملة لم جند يف نســخة االتصاالت‬\n‫مــا يفيــد بوجــود اتصــاالت بــن املدعــى عليــه الثانــي واملدعى عليــه الرابع‬\n‫كمــا أنــه قــد جــرى منــا االطــاع علــى أقــوال املدعــى عليــه اخلامــس‬\n‫علــى اللفــة ‪ 0‬صفحــة‪ 0‬والتــي تتضمــن إنــكاره ملــا دفــع بــه املدعــى عليــه‬\n‫األول مــن أن اخلامــس هــو مــن طلــب منــه أخــذ احلراثــة مــن الصناعيــة‬\n‫وال بينــة لــأول علــى هــذا الدفــع كمــا تقــدم فبنــاء علــى جميــع ماتقــدم‬\n‫مــن الدعــوى واإلجابــة وبنــاء علــى محضــر القبــض املرصــود يف اجللســة‬\n‫املاضيــة واملتضمــن أنــه مت القبــض علــى املدعــى عليهــم األول والثانــي‬\n‫والثالــث يف ســيارة مســروقة وأنــه كان يوجــد معهــم لوحــات لســيارات‬\n‫أخــرى أ‪.‬ه ـ ونظــر ًا العتــراف املدعــى عليــه األول حتقيق ـ ًا بذهابــه مــع‬\n‫املدعــى عليهمــا الثانــي والثالــث علــى ســيارة مســروقة لغــرض الســرقة‬\n‫وأنهــم وجــدوا شــبك أغنــام وســرقوا منــه خمســة خــراف وأنــه كان ردء ًا‬\n‫يف ذلــك واســتلم مــن قيمــة هــذه اخلــراف مبلــغ ثالثمائــة ريــال واعترافــه‬\n\n\n                                                                                      ‫‪210‬‬\n\f      ‫أيض ـ ًا ببيعــه ســيارة مســروقة اســتلمها مــن الثانــي واســتلم قيمتهــا بعــد‬\n      ‫ذلــك مــن املشــتري والعترافــه أيضـ ًا بأخــذ حراثــة غيــر مملوكــة لــه مــن‬\n      ‫الصناعيــة وعــدم إحضــاره البينــة علــى مــا دفــع بــه مــن أن اخلامــس هــو‬\n      ‫مــن طلــب منــه ذلــك علــى أنهــا مملوكــة لــه مــع إنــكار اخلامــس لهــذا‬\n      ‫الدفــع والعترافــه أيضــا بالتعــاون مــع املدعــى عليــه الثانــي يف ســرقة‬\n      ‫‪ ....‬وإخفائــه يف بيــت مهجــور وبنــاء علــى اعتــراف املدعــى عليــه الثانــي‬\n      ‫أنــه قــام مبشــاركة بعــض مــن املدعــى عليهــم يف ســرقة ســيارة بالقــرب‬\n      ‫مــن محطــة ‪....‬وكذلــك ســرقة ســيارة أخــرى مــن ‪....‬وأنــه كذلــك قــام‬\n      ‫هــو واألول بســرقة ‪....‬مــن ‪....‬وأخــذ هــذا ‪....‬وأخفــاه يف ‪ ..........‬واعترافــه‬\n      ‫أيضـ ًا مبشــاركة املدعــى عليــه األول والثالــث يف ســرقة خمســة خــراف‬\n      ‫مــن شــبك أغنــام ثــم ذهــب بهــا إلــى ورشــته بالــ‪ ....‬وكانــت هــذه الســرقة‬\n      ‫علــى ســيارة مســروقة وأنــه قــام هــو واألول ببيعهــا يف ‪....‬كمــا أنــه قــد‬\n      ‫اعتــرف أيض ـ ًا ببيــع ســيارة علــى طــرف ثالــث وهــو يعلــم أنهــا مســروقة‬\n      ‫وأنــه اســتلم مــن قيمتهــا خمســمائة ريــال وبنــاء علــى اعتــراف املدعــى‬\n      ‫عليــه الثالــث واملتضمــن اعترافــه بســرقة خمســة خــراف وحتميلهــا وأنــه‬\n      ‫اجتــه مــع املدعــى عليهمــا األول والثانــي وباعوهــا يف ‪....‬ولكــون املدعــى‬\n      ‫عليــه الثالــث مت القبــض عليــه مــع املدعــى عليهمــا األول والثانــي يف‬\n      ‫الســيارة املســروقة ولعــدم وجــود أدلــة ضــد املدعــى عليــه الرابــع حيــث‬\n      ‫إن إقــرارات املدعــى عليــه الثانــي تعتبــر حجــة قاصــرة عليــه وبنــاء علــى‬\n      ‫خطــاب هيئــة التحقيــق واإلدعــاء العــام املوجــه لشــرطة محافظــة دومــة‬\n      ‫اجلنــدل برقــم ه ـ ف ‪/0/0‬س‪ 00‬وتاريــخ ‪0000/00/0‬ه ـ واملرفــق علــى‬\n      ‫اللفــه ‪ 00‬واملتضمــن أن األدلــة الترقــى لتوجيــه اإلتهــام ضــد املدعــى‬\n      ‫عليــه الرابــع ‪ 0‬أ‪.‬ه ـ وحيــث لــم يــرد ذكــر املدعــى عليــه الرابــع إال يف‬\n\n\n‫‪211‬‬\n\f‫إقــرارات الثانــي ‪ 0‬وألن األصــل البــراءة والســامة ولكــون املدعــى‬\n‫عليــه اخلامــس يقيــم يف ‪....‬بســكاكا وبنــاء علــى املــادة ‪ 131‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة بشــأن االختصــاص املكانــي وحيــث إنــه ال بينــه‬\n‫للمدعــي العــام ســوى مــامت رصــده كمــا أنــه ال بينــة للمدعــى عليهــم‬\n‫علــى مادفعــوا بــه وبنــاء علــى اطالعنــا علــى ســجل ســوابق املدعــى عليهــم‬\n‫املرصــودة يف الئحــة الدعــوى وملــا قــرره أهــل العلــم مــن اشــتراط احلــرز‬\n‫يف الســرقة وعــدم حتقــق شــرط احلــرز يف هــذه الســرقات لكــون شــبك‬\n‫األغنــام خــارج البنيــان وخــارج املزرعــة و ال حــارس عنــده وهــذا ال يعــد‬\n‫حــرزا معتبــرا كمــا أن اعتــراف املدعــى عليــه الثانــي بســرقة ســيارة ‪....‬‬\n‫موديــل ‪1990‬م مــن شــركة ‪....‬يتضمــن أن املفتــاح كان موجــودا عليهــا‬\n‫وهــذا يعتبــر إقــرارا مجــزءا يؤخــذ كلــه أو يتــرك كلــه لكونــه يف‬\n‫واقعــة واحــدة كمــا يف املــادة السادســة بعــد املائــة مــن نظــام املرافعــات‬\n‫الشــرعية والتــي نصــت علــى عــدم جتــزء اإلقــرار علــى صاحبــه وحيــث‬\n‫إن مــا قــام بــه املدعــى عليهــم األول والثانــي والثالــث مــن الســرقات‬\n‫الــواردة يف اعترافاتهــم جرميــة يســتحقون العقوبــة عليهــا وهــو اعتــداء‬\n‫علــى األمــوال املعصومــة وأخــذ للمــال دون حــق لــذا وجلميــع مــا تقــدم‬\n‫فقــد ثبــت لدينــا إدانــة املدعــى عليــه األول واملدعــى عليــه الثانــي واملدعــى‬\n‫عليــه الثالــث بســرقة خمســة خــراف مــن دون حــرز كمــا ثبــت لدينــا‬\n‫إدانــة املدعــى عليــه األول والثانــي باالشــتراك يف ســرقة ‪ ....‬غيــر محــرز‬\n‫وإخفائــه يف بيــت مهجــور واالشــتراك يف بيــع ســيارة مســروقة واســتالم‬\n‫قيمتهــا كمــا ثبــت لدينــا إدانــة األول بســرقة حراثــة غيــر محــرزة وإدانــة‬\n‫الثانــي أيضــا باالشــتراك يف ســرقة ســيارة ‪....‬موديــل ‪1998‬م مــن محطــة‬\n‫‪....‬وســرقة ســيارة أخــرى مــن ‪....‬بســكاكا ولــم يثبــت لدينــا مــا عدا ذلك‬\n\n\n                                                                                        ‫‪212‬‬\n\f      ‫بحــق املدعــى عليهــم األول والثانــي والثالــث والرابــع وقــد قررنــا مــا يلــي‬\n      ‫أوال رددنــا دعــوى املدعــي العــام يف مطالبتــه بحــد الســرقة لعــدم ثبــوت‬\n      ‫املوجــب الشــرعي لذلــك‪ .‬ثانيــا قررنــا تعزيــر كال مــن املدعــى عليهمــا‬\n      ‫األول والثانــي بســجن كل واحــد منهمــا ثــاث ســنوات ونصــف حتتســب‬\n      ‫منهــا مــدة اإليقــاف وجلــد كل واحــد منهمــا خمســمائة جلــدة مفرقــة‬\n      ‫علــى عشــر دفعــات متســاوية بــن كل دفعــة والثانيــة خمســة عشــر يومــا‬\n      ‫علــى أن يكــون اجللــد يف الدفعــات األولــى والثالثــة واخلامســة أمــام أحــد‬\n      ‫اجلوامــع الكبيــرة باحملافظــة‪ .‬ثالثــا قررنــا تعزيــر املدعــى عليــه الثالــث‬\n      ‫بســجنه ســنة ونصــف حتتســب منهــا مــدة إيقافــه وجلــده ثالثمائــة جلــدة‬\n      ‫مفرقــة علــى ســت دفعــات متســاوية بــن كل دفعــة واألخــرى عشــرة أيــام‬\n      ‫علــى أن يكــون اجللــد يف الدفعــة األولــى والثالثــة واخلامســة أمــام أحــد‬\n      ‫اجلوامــع الكبيــرة باحملافظــة‪ .‬رابعــا حكمنــا ببــراءة املدعــى عليه الرابع‬\n      ‫لعــدم ثبــوت الدعــوى ضــده‪ .‬خامســا حكمنــا بــرد دعــوى املدعــي العــام‬\n      ‫ضــد املدعــى عليــه اخلامــس لعــدم االختصــاص املكانــي وبجميــع مــا‬\n      ‫تقــدم حكمنــا وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليهــم قرر‬\n      ‫املدعــي العــام عــدم القناعــة باحلكــم مــع تقــدمي الئحــة اعتراضيــة كمــا‬\n      ‫قــرر املدعــى عليــه األول واملدعــى عليــه الثانــي عــدم القناعــة باحلكــم‬\n      ‫مــع تقــدمي الئحــة اعتراضيــة وقــررر املدعــى عليــه الثالــث واملدعــى عليــه‬\n      ‫الرابــع القناعــة باحلكــم وجــرى إفهــام املعترضــن باســتالم نســخة‬\n      ‫مــن القــرار بعــد عشــرة أيــام وأن مــدة االعتــراض ثالثــون يوم ـ ًا حســب‬\n      ‫التعليمــات ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                                                           ‫آلــه وصحبــه‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد أطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائيــة‬\n\n\n‫‪213‬‬\n\f‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باجلــوف علــى املعاملــة الواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بدومة اجلندل برقــم ‪0000000000‬‬\n‫وتاريــخ ‪0000/00/00‬هـ ـ املرفــق بهــا القــرار الشــرعي الصــادر مــن‬\n‫أصحــاب الفضيلــة القضــاة الشــيخ‪ ..........‬و‪ ..........‬و‪ ..........‬املســجل برقــم‬\n‫‪ ..........‬وتاريــخ ‪ 0000/0/0‬اخلــاص بدعــوى املدعــي العــام ضــد ‪..........‬‬\n‫ورفقــاه يف قضيــة ســرقة وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة‬\n‫علــى النحــو املفصــل فيــه‪ ،‬وباإلطــاع على ماأجاب بــه أصحاب الفضيلة‬\n‫ـاء علــى قرارنــا الســابق‬‫وأحلقــوه بالضبــط وصورتــه والقــرار وســجله بنـ ً‬\n‫رقــم ‪ 0000000‬يف ‪0000/0/00‬هــ‪ .‬جــرت املصادقــة علــى احلكــم بعــد‬\n‫اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم‪،.‬‬\n\n\n\n\n                                                                                       ‫‪214‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":188,"source_page_end":214,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"94f071f44d0d6064a7444608a9e25d2f03cb005b07bb8c01cd116b6531acc715","normalized_text_hash":"67d762007670ccbc3d6fd6aa9b5ae92aaf33212d4abbd26db12b13e363c24d4b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p188-34189490"},{"id":"bcfe780e-8e3c-5703-b3da-dc624e1d43a7","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقه -نشل -سرقة مبلغ مالي من شخص -القبض على السارق ووجود املسروق بحوزته -إيداع مبلغ مالي بيت املال -صرف النظر عن حد السرقة لعدم وجود موجبها -التعزير بالسجن واجللد","document_number":"33212243","case_number":"32544933","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة وباالشتراك مع فضيلة الشيخ","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/04/26","year":"1434","subject":"سرقه -نشل -سرقة مبلغ مالي من شخص -القبض على السارق ووجود املسروق بحوزته -إيداع مبلغ مالي بيت املال -صرف النظر عن حد السرقة لعدم وجود موجبها -التعزير بالسجن واجللد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33212243 :‬تاريخه ‪1433/04/26 :‬هـ‬\n                           ‫رقم الدعوى ‪32544933 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                       ‫‪ 3430133‬تاريخه ‪1434/2/5:‬ه‬\n\n\n\n      ‫ســرقه ‪ -‬نشــل ‪ -‬ســرقة مبلــغ مالــي مــن شــخص ‪ -‬القبــض علــى الســارق‬\n      ‫ووجــود املســروق بحوزتــه ‪ -‬إيــداع مبلــغ مالــي بيــت املــال ‪ -‬صــرف النظــر‬\n      ‫عــن حــد الســرقة لعــدم وجــود موجبهــا‪ -‬التعزيــر بالســجن واجللــد‬\n                                                                          ‫واملصــادرة ‪.‬‬\n\n\n\n\n      ‫‪-1‬أجمع أهل العلم على أن قطع الســارق إمنا يجب إذا شــهد بالســرقة‬\n      ‫شــاهدان حــران مســلمان ووصفــا مــا يوجــب القطــع ‪ .‬انظــر اإلجمــاع‬\n      ‫البــن املُنــذر كتــاب أحــكام الســراق (ص‪ ، )68‬واملغنــى البــن قدامــه بــاب‬\n                                                 ‫القطــع يف الســرقة (‪. )463/12‬‬\n\n\n\n      ‫ـاج يف‬‫الئحــة الدعــوى ضــد املدعــى عليــه مقيــم بنشــل مبلــغ مالــي مــن حـ ّ‬\n      ‫ســاحات احلــرم املكــي الشــريف ووجــود مبالــغ ماليــه كبيــره بحوزتــه ـ‬\n      ‫حيــث قُ بــض علــى املدعــى عليــه مــن قبــل مآميــر البحــث لقيامــه بفتــح زر‬\n      ‫اجليــب األميــن اخللفــي لبنطــال أحــد األشــخاص عنــد مشــربيات بــاب رقــم‬\n      ‫(‪ )85‬يف احلــرم املكــي الشــريف بيــده اليمنــى وأخــرج مبلــغ مــن املــال‬\n         ‫ووضعــه يف جيبــه العلــوي فتــم القبــض عليــه واملبلــغ املنشــول بحوزتــه‪،‬‬\n      ‫و بتفتيشــه وجــد بحوزتــه مبالــغ كبيــرة بعمــات مختلفــة‪ ،‬وطلــب‬\n\n‫‪215‬‬\n\f‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بإقامــة حــد الســرقة‬\n‫ومصــادرة املبالــغ ـ كمــا تبــن وجــود ســوابق علــى املدعــى عليه‪،‬وقــد‬\n‫أنكــر املدعــى عليــه مــا نســب إليــه وذكــر بــأن املبالــغ الكبيــرة‬\n‫املضبوطــة بحوزتــه عائــده لــه لــذا أحضــر املدعــي العــام شــاهدين معــدي‬\n‫محضــر القبض‪،‬وإلنــكار املدعــى عليــه وألن الشــهادة غيــر موصلــة‬\n‫صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــى العــام بإقامــة حــد‬\n‫الســرقة علــى املدعــى عليــه لعــدم وجــود موجبهــا ولقــوة التهمــة املوجهــة‬\n‫للمدعــى عليــه مت تعزيــره بالســجن واجللــد ومصــادرة املبالــغ املضبوطــة‬\n                    ‫بحوزته‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪..‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة مبكــة‬\n‫املكرمــة وباالشــتراك مــع فضيلــة الشــيخ ‪...‬وفضيلــة الشــيخ ‪...‬القضــاة‬\n‫باحملكمــة العامــة مبكــة املكرمــة حــاال وبنــاء علــى املعاملــة احملالة لنا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبكة املكرمة برقــم ‪32544933‬‬\n‫وتاريــخ ‪1432/11/20‬ه ـ املقيــدة باحملكمــة برقــم ‪321485330‬‬\n‫وتاريــخ ‪1432/11/20‬ه ـ ففــي يــوم االحــد املوافق‪1433/01/16‬ه ـ‬\n‫ا‬‫أفتتحــت اجللســة الســاعة ‪ 12 : 02‬وفيهــا حضــر املدعــي العــام ‪...‬قائـ ً‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبكــة املكرمــة أدعــي‬\n‫علــى احلاضــر ‪... /‬ـ ـ (‪ )55‬عام ـ ًا ـ ـ مصــري اجلنســية مبوجــب جــواز ســفر‬\n‫رقــم (‪ )...‬موقــوف بســجون مكــة املكرمــة ـ ـ مبوجــب أمــر توقيــف رقــم‬\n‫(‪ )7/4/20/184‬وتاريــخ ‪1432/9/10‬ه ـ بتاريــخ ‪1432/9/8‬ه ـ قبــض‬\n‫علــى املدعــى عليــه مــن قبــل مأميــر البحــث لقيامــه بفتــح زرار اجليــب‬\n\n                                                                                     ‫‪216‬‬\n\f      ‫األميــن اخللفــي لبنطلــون أحــد األشــخاص عنــد مشــربيات بــاب رقــم (‪)85‬‬\n      ‫يف احلــرم املكــي الشــريف بيــده اليمنــى وأخــرج مبلــغ مــن املــال ووضعــه‬\n      ‫يف جيبــه العلــوي فتــم القبــض عليــه واملبلــغ املنشــول بحوزتــه وتبــن أن‬\n      ‫مقــداره (‪ )694‬ســتمائة وأربعــة وتســعون ريــا ًال ســعودي ًا ومبلــغ (‪)110‬‬\n      ‫مائــة وعشــرة دينــار أردنــي وبتفتيــش املدعــى عليــه وجــد بحوزتــه مبلــغ‬\n      ‫وقــدره (‪ )52525‬اثنــان وخمســون ألــف وخمســمائة وخمســة وعشــرون‬\n      ‫ريــال ســعودي ومبلــغ (‪ )300‬ثالثمائــة جنيــة مصــري وهاتــف نقال من نوع‬\n      ‫‪ ..........‬باستجواب املدعى عليه أفاد بأنه دخل املسجد احلرام وقد وجد‬\n      ‫مبلغ ـ ًا مــن املــال فئــة الريــال واخلمســة الريــاالت ال يزيــد مجموعهــا عــن‬\n      ‫(خمســن) ريــا ًال ســاقطة علــى األرض فأخــذ املبلــغ مــن أجــل تعريفــه فتــم‬\n      ‫القبــض عليــه ومبســاءلته عــن املبلــغ املالــي الكبيــر مــن العملــة احملليــة‬\n      ‫وقــدره (‪)52525‬اثنــان وخمســون ألــف وخمســمائة وخمســة وعشــرون‬\n      ‫ريــال ســعودي وبقيــة املضبوطــات األخــرى التــي وجــدت بحوزتــه عنــد‬\n      ‫تفتيشــه فذكــر أنهــا عائــدة لــه أحضرهــا مــن بــاده مــن أجــل شــراء‬\n      ‫مســتلزمات نســائية وكاميــرات تصويــر لتصديرهــا لبــاده وال يوجــد‬\n      ‫مــا يثبــت صحــة مــا ادعــى بــه وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n      ‫للمدعــى عليــه بنشــل مبلــغ وقــدره (‪ )694‬ســتمائة وأربعــة وتســعون ريــال‬\n      ‫ســعودي ومبلــغ (‪ )110‬مائــة وعشــرة دينــار أردنــي املؤيــد بقــرار جلنــة إدارة‬\n      ‫الهيئــة رقــم (‪ )2595‬لعــام ‪1432‬ه ـ ‪ . .‬وذلــك لألدلــة والقرائــن التاليــة‪1‬ـ‬\n      ‫مــا جــاء مبحضــر القبــض عليــه ووجــود املبلــغ املنشــول بحوزتــه وشــهادة‬\n      ‫مآميــر البحــث رقــم (‪ )731‬ورقــم (‪ )1914‬ورقــم (‪ )1636‬املثبتــة بنفــس‬\n      ‫احملضــر لفــة (‪2 )6‬ـ مــا جــاء يف ســند اســتالم املجنــي عليه‪.../‬أردنــي‬\n      ‫اجلنســية املبلــغ املالــي املنشــول العائــد لــه وتنازلــه عــن املتهــم لفــة (‪)5‬‬\n\n\n‫‪217‬‬\n\f‫‪3‬ـ منــوذج معادلــة العملــة األجنبيــة بالريــال الســعودي (‪4 )8‬ـ عــدم إثبــات‬\n‫املدعــى عليــه لعائديــه املبلــغ الكبيــر لــه وعــدم تســجيل املبلــغ يف املطــار‬\n‫حســب التعليمــات املبلغــة مــن الدولــة للقادمــن مــن اخلــارج ممــا يــدل علــى‬\n‫إن مــا بحوزتــه حصــل عليهــا بطريقــة النشــل ‪5‬ـ مــا ورد يف أقــوال املدعــى‬\n‫عليــه املدونــة علــى ص ‪ 3/2‬لفــة (‪ )1‬وبالبحــث عــن ســوابق املذكــور‬\n‫وجــد لــه (أربــع) ســوابق منهــا (اثنتــن) نشــل والثالثــة تزويــر وثائــق‬\n‫رســمية وانتحــال شــخصية الغيــر والرابعــة عــوده بعــد اإلبعــاد وحيــث‬\n‫أن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا مــن‬\n‫التعــرض لقاصــدي البيــت احلــرام وإيذائهــم بنشــل مــا يف جيوبهــم دون‬\n‫مراعــاة حلرمــة املــكان فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو أخــذ‬\n‫مــال محتــرم مــن حــرزه بعــد هتكــه يزيــد عــن النصــاب ال شــبهة لــه فيــه‬\n‫لــذا فأننــي أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد الســرقة‬\n‫الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة يف ضــوء قــرار‬\n‫مجلــس القضــاء األعلــى رقــم (‪ )46/412‬وتاريــخ ‪1418/11/17‬ه ـ‬\n‫كمــا أطلــب إيــداع املبلــغ املالــي املضبــوط معــه والبالــغ (‪ )52525‬اثنــن‬\n‫وخمســون ألــف وخمســمائة وخمســة وعشــرون ريــاال ًســعودي ًا والــذي‬\n‫لــم يثبــت مشــروعية مصــدره يف بيــت املــال وفقـ ًا للمــادة (‪ )92‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة والتوجيــه حيالــه املدعــي العــام وكيــل دائــرة (أ)‬\n‫‪ ..........‬أ‪.‬ه ـ وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أنكــر مــا‬\n‫ا وقــال الصحيــح أننــي وجــدت مبلغ ـ ًا علــى‬    ‫نســب إليــه جمل ـ ًة وتفصي ـ ً‬\n‫األرض ال أعــرف قــدره فأخذتهــا بغــرض التعريــف بهــا ويف أثنــاء ذلــك‬\n‫قبــض علــي رجــال املباحــث وأمــا مبلــغ اثنــن وخمســن ألــف وخمســمائة‬\n‫وخمســة وعشــرين ريــا ًال ومبلــغ ثالثمائــة جنيــه كلهــا ملــك لــي هكــذا‬\n\n\n                                                                                       ‫‪218‬‬\n\f      ‫قــال وبعــرض إســتجوابه واملــدون بعاليــه عليــه أقــر بــه وصــادق عليــه‬\n      ‫وقــال هــو الصحيــح هكــذا قــال فطلبــت مــن املدعــي العــام البينــة علــى‬\n      ‫ـاء عليــه رفعتــويف‬‫صحــة دعــواه وعــد باحضارهــا يف اجللســة القادمــة وبنـ ً‬\n      ‫اجللســة التاليــة يف متــام الســاعة ‪ 11.20‬حضــر املدعــي العــام وحضــر‬\n      ‫ال مــن‬\n            ‫حلضــوره املدعــى عليــه ‪...‬وقــد أحضــر املدعــي العــام للشــهادة ك ً‬\n      ‫‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬و ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ولــدى ســؤالهما عمــا لديهمــا مــن‬\n      ‫ا أشــهد هلل تعالــى أننــي‬   ‫شــهادة أســتعد كل واحــد منهمــا مبفــرده قائ ـ ً‬\n      ‫قــد رأيــت املدعــى عليــه ‪ ...‬مصــري اجلنســية خلــف أحــد األشــخاص مــن‬\n      ‫اجلنســية األردنيــة بالقــرب مــن مشــربيات زمــزم يف ســاحة احلــرم التــي‬\n      ‫تفتــح علــى وقــف امللــك عبدالعزيــز ورأيــت املدعــى عليــه وهــو ميــد يــده‬\n      ‫إلــى اجليــب اخللفــي لبنطلــون الشــخص وقــام بفــك زر اجليــب وأخــرج منــه‬\n      ‫مبلغ ـ ًا مــن املــال قــدره ســتمائة وأربعــة وتســعون ريــا ًال ســعودي ًا ووضعهــا‬\n      ‫يف جيبــه األمامــي فتــم القبــض عليــه واملبلــغ يف جيبــه وكان املدعــى‬\n      ‫عليــه يلبــس ثوب ـ ًا وحتــت الثــوب بنطلــون وبعــد تفتيشــه وجدنــا يف جيــب‬\n      ‫بنطلونــه األمامــي مبلــغ أثنــن وخمســن ألــف وخمســمائة ريــال مــن فئــة‬\n      ‫اخلمســمائة ريــال ورقــة واحــده إال أنهمــا قــاال لــم نــر املدعــى عليــه وهــو‬\n      ‫يدخــل يــده يف جيــب الشــخص املجنــى عليــه هكــذا شــهدا وللتأمــل‬\n      ‫رفعــت اجللســة ‪ .‬وبــاهلل التوفيــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم حــرر يف ‪1433/01/23‬ه ـ ‪ .‬احلمــد هلل والصــاة والســام‬\n      ‫علــى رســول اهلل وبعــد فلــدي أنــا ‪...‬القاضــي باحملكمــة العامــة مبكــة‬\n      ‫املكرمــة حــا ًال وباالشــتراك مــع فضيلــة الشــيخ ‪...‬وفضيلة الشــيخ ‪...‬ففي‬\n      ‫يــوم األحــد املوافــق ‪1433/04/18‬ه ـ أفتتحــت اجللســة يف متــام الســاعة‬\n\n\n‫‪219‬‬\n\f‫احلاديــة عشــر والنصــف وفيهــا حضــر املدعــي العــام كمــا حضــر املدعــى‬\n‫عليــه فجــرى عــرض الشــهود ومــا جــاء يف شــهادتهم علــى املدعــى عليــه‬\n‫فأجــاب قائــا هــذه الشــهادة غيــر صحيحــة وأمــا الشــهود فــا أعــرف‬\n‫عــن حالهــم شــيئ ًا هكــذا قــال فبعــد ســماع الدعــوى واإلجابــة ونظــرا‬\n‫إلنــكار املدعــى عليــه دعــوى املدعــي العــام ونظــرا ألن بينــة املدعــي‬\n‫العــام غيــر موصلــة إال أنهــا قرينــة قويــة موجبــة لتغليــظ العقوبــة يف حــق‬\n‫املدعــى عليــه ونظــرا ألن املدعــي العــام يطالــب بإقامــة حــد الســرقة علــى‬\n‫املدعــى عليــه وقــد أجمــع أهــل العلــم علــى أن قطــع يــد الســارق إمنــا يجــب‬\n‫إذا شــهد بالســرقة شــاهدان حــران مســلمان ووصفــا مــا يوجــب القطــع‬\n‫ينظــر يف ذلــك اإلجمــاع البــن املنــذر كتــاب أحــكام الســراق ص ‪ 68‬و‬\n‫املغنــي بــاب القطــع يف الســرقة جــ‪ 463/12‬ونظــرا لوجــود مبلــغ كبيــر‬\n‫يف حــوزة املدعــى عليــه ولــم جتــر العــادة باصطحــاب النــاس األمــوال‬\n‫الكبيــرة معهــم وإمنــا يحفظونهــا يف أماكــن الئقــة بحفظهــا كمــا أن‬\n‫وجــود هــذا املبلــغ مــع املدعــى عليــه وهيئتــه ال تــدل علــى حمــل مثلــه أو‬\n‫متلكــه ملثــل هــذا املبلــغ لــذا فقــد قررنــا مــا يلــي ‪ :‬أوال ‪ :‬صــرف النظــر‬\n‫عــن دعــوى املدعــي العــام بإقامــة حــد الســرقة علــى املدعــى عليــه لعــدم‬\n‫وجــود موجبهــا ‪ .‬ثانيــا ‪ :‬ثبــت لدينــا قــوة التهمــة املوجهــة للمدعــى عليــه‬\n‫مــن قبــل املدعــي العــام ‪ .‬ثالثــا ‪ :‬تعزيــر املدعــى عليــه بســجنه ملــدة ســنتني‬\n‫مــن تاريــخ إيقافــه وجلــده ألــف وخمســمائة جلــدة مفرقــة علــى فتــرات‬\n‫بــن كل فتــرة والتــي تليهــا مــا ال يقــل عــن أســبوع مبقــدار خمســن جلــدة‬\n‫لــكل فتــرة ‪ .‬رابع ـ ًا ‪ :‬إيــداع املبلــغ املضبــوط مــع املدعــى عليــه يف بيــت‬\n‫املــال هــذا مــا ظهــر لنــا وبــه حكمنــا وبعــرض ذلــك علــى الطرفــن قنع به‬\n‫املدعــى عليــه وقــرر املدعــي العــام االعتــراض بالئحــة فافهــم بتعليمــات‬\n\n\n                                                                                         ‫‪220‬‬\n\f      ‫االســتئناف حيــال ذلــك ففهــم وبــاهلل التوفيــق ‪ .‬وصلــى اهلل علــى نبينــا‬\n       ‫محمــد وعلــى آلــه وصحبــه وســلم تســليما‪ .‬حــرر يف ‪1433/04/18‬ه ـ ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد فلــدي انــا‬\n      ‫فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة حــا ًال‬\n      ‫ـاء علــى‬‫وباالشــتراك مــع فضيلــة الشــيخ ‪ ..........‬وفضيلــة الشــيخ ‪...‬وبنـ ً‬\n      ‫املعاملــة الــواردة لنــا بشــرح فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n      ‫املكرمــة رقــم ‪ 33/3528642‬يف ‪ 1433/08/13‬ه ـ الــواردة مــن‬\n      ‫محكمــة االســتئناف برقــم ‪ 331309042‬قــي ‪1433/08/13‬ه ـ‬\n      ‫واملرفــق بهــا قــرار الدائــرة اجلزائيــة اخلماســية الرابعــة رقــم ‪33359648‬‬\n      ‫يف ‪1433/07/28‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪...‬املتضمــن مــا‬\n      ‫يلــي « وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n      ‫باألكثريــة إعادتهــا ألصحــاب الفضيلــة حــكام القضيــة حيــث ورد يف‬\n      ‫حكمهــم يف الفقــرة الرابعــة قولهــم إيــداع املبلــغ املضبــوط مــع املدعــى‬\n      ‫عليــه يف بيــت املــال فهــل مقصــوده بذلــك مصــادرة املبلــغ أو جعلــه يف بيــت‬\n      ‫املــال أمانــه حلــن حضــور مــن يطالــب بــه وال بــد مــن توضيــح ذلــك كمــا‬\n      ‫أن فضيلــة الشــيخ ‪...‬أشــترك يف نظــر القضيــة مؤخــر ًا ولــم يشــر إلــى‬\n      ‫أنــه أطلــع علــى الدعــوى املقدمــة مــن املدعــي العــام وإجابــة املدعــي عليــه‬\n      ‫عليهــا كمــا أن كبــر املبلــغ املضبــوط مــع املدعــى عليــه يوجــه التهمــة‬\n      ‫ـاء علــى ذلــك فاجلــزاء احملكــوم بــه علــى‬ ‫القويــة لــه فيمــا نســب إليــه فبنـ ً‬\n      ‫ا ونظــر ًا حلرمــة الزمــان و املــكان « أ‪.‬ه ـ ‪ .‬عليــه‬ ‫املدعــى عليــه يعتبــر قليـ ً‬\n      ‫جنيــب أصحــاب الفضيلــة بــأن إيــداع املبلــغ املقصــود بــه مصــادرة املبلــغ‬\n      ‫املضبــوط بحــوزة املدعــى عليــه للجهــل بأعيــان مالكــه ونود اإلشــارة أنه‬\n      ‫وجــد ســقط يف مقدمــة الضبــط مت إحلاقــه يدوي ـ ًا علــى القــرار وضبطــه‬\n\n\n‫‪221‬‬\n\f‫وذلــك أن اجللســة قــد انعقــدت مــن بدايتهــا برآســة فضيلــة الشــيخ ‪...‬و‬\n‫باإلشــترك مــع فضيلــة الشــيخ ‪...‬وفضيلــة الشــيخ ‪...‬ونشــير إلــى قناعتنــا‬\n‫مبناســبة العقوبــة للجرميــة الصــادرة مــن املدعــى عليــه وعليــه فليــس لدينــا‬\n‫ســوى مــا حكمنــا بــه ســابق ًا وحتــى ال يخفــى جــرى ضبطــه ‪ .‬وبــاهلل‬\n‫التوفيــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                           ‫يف ‪1433/11/09‬ه ـ ‪.‬‬\n        ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد ‪-:‬‬\n‫فقد جرى منا نحن قضاة الدائرة اجلزائية اخلماســية الرابعة مبحكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‪33/1528642‬‬\n‫وتاريــخ ‪1433/12/28‬ه ـ املرفــق بهــا القــرار رقــم‪ 33212243‬وتاريــخ‬\n‫‪1433/4/26‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n‫العامــة مبكــة الشــيخ‪ ... /‬والشــيخ‪... /‬والشــيخ‪... /‬املتضمــن دعــوى‬\n‫املدعــي العــام ضــد‪... /‬مصــري اجلنســية ‪ ،‬املتهــم بالنشــل ‪ ،‬احملكــوم‬\n                                                            ‫فيــه مبــا دون باطنــه ‪.‬‬\n‫واملالحــظ عليــه بقــرار محكمــة االســتئناف رقــم ‪ 33359648‬تاريــخ‬\n‫‪1433/7/28‬ه ـ وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضية‬\n‫‪ ،‬تقــررت املوافقــة علــى احلكــم بعــد اإليضــاح األخيــر‪ .‬وبــاهلل التوفيــق ‪،‬‬\n                   ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪222‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":215,"source_page_end":222,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"85130469c685a256a4bc51c09822e83a6cba35064feb6c119613b4f59e634ce1","normalized_text_hash":"c62b5417248abdd541af395ffcd6cd46889e6e0e9ee6792497c1ea702ae74dfd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p215-33212243"},{"id":"63bc514a-5f82-5526-bf67-8075ea4f3b2b","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة بعض محتويات غرفة بداخل فندق -املطالبة بإقامة حد السرقة -انتفاء شرط احلرز -صرف النظر عن دعوى املدعي العام -التعزير بالسجن واجللد .","document_number":"33205932","case_number":"33107611","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/04/21","year":"1434","subject":"سرقة -سرقة بعض محتويات غرفة بداخل فندق -املطالبة بإقامة حد السرقة -انتفاء شرط احلرز -صرف النظر عن دعوى املدعي العام -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 33205932 :‬تاريخه ‪1433/04/21 :‬هـ رقم‬\n                              ‫الدعوى ‪33107611 :‬‬\n ‫رقم قرار التصديق من محكمة االستئناف ‪3435891 :‬‬\n                          ‫تاريخه ‪1434/02/12 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة بعــض محتويــات غرفــة بداخــل فنــدق ‪ -‬املطالبــة بإقامــة‬\n      ‫حــد الســرقة ‪-‬انتفــاء شــرط احلــرز ‪ -‬صــرف النظــر عــن دعــوى املدعــي‬\n                                               ‫العــام ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪-1‬قــال ابــن قدامــه رحمــه اهلل يف كتابــة املغنــى (‪ ( : )182/14‬فأمــا‬\n      ‫شــهادة أحدهمــا علــى صاحبــه فتقبــل نــص عليــه أحمــد وهــذا قــول‬\n      ‫عامــة أهــل العلــم ولــم أجــد فيــه خالف ـ ًا وذلــك لقــول اهلل تعالــى ‪﴿:‬‬\n      ‫َنف ِسـ ُـك ْم َأ ْو ا ْل َوال َِد ْيـ ِـن‬                     ‫ـط ُشـ َـه َد َاء ِ َّ ِ‬\n                                             ‫ل َو َلـ ْـو َع َلــى أ ُ‬                     ‫ن ِبا ْلقِ ْسـ ِ‬\n                                                                                                          ‫كو ُنــوا َق َّوامِ ـ َ‬   ‫ُ‬\n      ‫ال ْق َر ِبـَـن﴾ فأمــر بالشــهادة عليهــم ولــو لــم تقبــل ملــا أمــر بهــا وألنهــا‬                                   ‫َو ْ َ‬\n      ‫إمنــا ردت للتهمــة يف إيصــال النفــع وال تهمــة يف شــهادته عليــه فوجــب‬\n      ‫أن تقبــل كشــهادة األجنبــي بــل أولــى فــإن شــهادته لنفســه ملــا ردت‬\n      ‫للتهمــة يف إيصــال النفــع إلــى نفســه كان إقــراره عليهــا مقبــو ًال ) ‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليهمــا بســرقة مجموعــة مــن اجلــوازات‬\n      ‫واإلقامــات ومبلــغ مالــي وجهازيــن جــوال وجهــاز حاســب آلــي محمــول‬\n      ‫‪ ،‬حيــث تقــدم أحــد املواطنــن ببــاغ ملركــز الشــرطة مفــاده تعــرض‬\n      ‫الغرفــة التــي يســكنها بإحــدى الفنــادق للســرقة ‪ ،‬كمــا تقــدم مواطــن‬\n‫‪223‬‬\n\f‫آخــر يفيــد بتعــرض غرفتــه للســرقة ‪ ،‬وعليــه مت االنتقــال و املعاينــة رفــق‬\n‫األدلــة اجلنائيــة إلــى املوقــع ووصفــه وعثــر علــى بعــض املســروقات ملقــاه‬\n‫خلــف الفنــدق ‪ ،‬وقبــض علــى املدعــى عليهمــا بعــد يــوم مــن الواقعــة‬\n‫وباســتجواب الثانــي أقــر بالســرقة و مرافقــه األول لــه إال أنــه باســتجواب‬\n‫األول أنكــر ‪ ،‬لــذا طلــب املدعــي العــام إثبــات مــا أســند إليهمــا و‬\n‫احلكــم عليهمابإقامــة حــد الســرقة ‪ ،‬حيــث أقــر املدعــى عليــه الثانــي‬\n‫‪ ،‬وأنكــر املدعــى عليــه األول‪ ،‬وبعــد املرافعــة والنتفــاء شــرط احلــرز‬\n‫صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي العــام يف إقامــة حــد‬\n‫الســرقة‪ ،‬وحكمــت احملكمــة بتعزيــر املدعــى عليهــا بالســجن واجللــد‬\n                              ‫‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد يف يــوم األربعــاء ‪1433/3/23‬ه ـ لدينــا نحــن‬\n‫القضــاة باحملكمــة العامــة بتبــوك ‪...‬وفضيلــة القاضــي ‪ ...‬وفضيلــة‬\n‫القاضي ‪...‬وبناء على ورود املعاملة إلى احملكمة العامة بتبوك بخطاب‬\n‫رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة تبــوك رقــم ‪ 2147‬يف‬\n‫‪1433/2/8‬ه ـ واملقيــدة يف احملكمــة العامــة بتبــوك برقــم ‪33280780‬‬\n‫يف ‪1433/2/13‬ه ـ واحملالــة إلــى مكتبنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بتبــوك برقــم ‪ 33107611‬يف ‪1433/2/13‬ه ـ بشــأن دعــوى‬\n‫املدعــي العــام ضــد ‪...‬و ‪...‬بشــأن قضيــة ســرقة افتتحــت اجللســة األولــى‬\n‫يف متــام الســاعة ‪ 11 : 16‬وفيهــا حضــر املدعــي العــام ‪...‬بالســجل املدنــي‬\n‫رقــم ‪...‬وادعــى علــى احلاضريــن معــه ‪...‬الســعودي بالســجل املدنــي رقــم ‪...‬‬\n‫ســجل تبــوك و‪ ...‬الســعودي بالســجل املدنــي رقــم ‪...‬ســجل تبــوك قائــا يف‬\n\n                                                                                    ‫‪224‬‬\n\f      ‫حتريــر دعــواه بصفتــي مدعيــا عامــا بدائــرة اإلدعــاء العــام لفــرع الهيئــة‬\n      ‫مبنطقــة تبــوك أدعــي علــى احلاضريــن إنــه بتاريــخ ‪1432/10/12‬ه ـ ويف‬\n      ‫متــام الســاعة احلاديــة عشــر صباحــا تقــدم املواطــن ‪...‬ببــاغ ملركز شــرطة‬\n      ‫العزيزيــة مفــاده تعــرض الغرفــة التــي يســكنها بفنــدق ‪...‬للســرقة حيــث‬\n      ‫ســرق منهــا عــدد ثالثــة عشــر (‪ )13‬جــواز ســفر وعــدد ثالثــة عشــر (‪)13‬‬\n      ‫رخصــة إقامــة للعمالــة التابعــن لــه ورخصــة القيــادة وبطاقــة صــراف‬\n      ‫ومبلغــا ماليــا وقــدره تســعة آالف وخمســمائة وعشــرون ريـ‪ 9520‬ــال‬\n      ‫وجهــاز جــوال يحمــل الرقــم التسلســلي (‪ )............‬وجهــاز جــوال يحمــل‬\n      ‫الرقــم التسلســلي (‪ )............‬وبــذات الوقــت تقدم املواطــن (‪ )..........‬ببالغ‬\n      ‫عــن تعــرض الغرفــة التــي يســكنها بفنــدق‪ .....‬للســرقة حيــث ســرق منهــا‬\n      ‫جهــاز الب تــوب ومبلــغ مالــي وقــدره مائــة ريـ‪ 100‬ــال وباالنتقــال واملعاينــة‬\n      ‫رفــق األدلــة اجلنائيــة إلــى موقــع الســرقة بفنــدق ‪...‬بحــي ‪ ......‬اتضــح أنــه‬\n      ‫عبــارة عــن عــدة طوابــق وأن الســرقة حدثــت يف غرفتــن بالــدور األول‬\n      ‫حيــث قــام اجلنــاة بالدخــول للغرفتــن عــن طريــق النافــذة ومبعاينــة غرفــة‬\n      ‫‪...‬اتضــح بأنــه يوجــد بداخلهــا ســريرين وتبــن دخــول اجلنــاة عــن طريــق‬\n      ‫النافــذة ومبعاينــة غرفــة ‪...‬تبــن دخــول اجلنــاة عــن طريــق النافــذة ومــن‬\n      ‫خــال البحــث والتحــري مت العثــور علــى شــنطة بداخلهــا عــدد (‪)9‬‬\n      ‫جــوازات وعــدد (‪ )9‬إقامــات عائــدة للمواطــن ‪...‬على ســطح هنقر الورشــة‬\n      ‫الواقعــة خلــف الفنــدق واتضــح بــأن الغرفــة رقــم ‪ ....‬الواقعــة بالــدور‬\n      ‫األول تطــل نافذتهــا علــى الورشــة والغرفــة مســتأجرة مــن قبــل املواطــن‬\n      ‫‪...‬وغادرهــا بعــد حــدوث الســرقة وبتفتيــش الغرفــة عثــر بداخلهــا علــى‬\n      ‫مشــرط وقفــازات داخــل علبــة فتــم حتريزهــا وبعثهــا لألدلــة اجلنائيــة مت‬\n      ‫القبــض علــى كال مــن ‪...‬بتاريــخ ‪1432/10/13‬ه ـ واملدعــى عليــه األول‬\n\n\n‫‪225‬‬\n\f‫بتاريــخ ‪1432/10/16‬ه ـ واملدعــى عليــه الثانــي بتاريــخ ‪1432/10/28‬هـ‬\n‫وورد التقريــر الفنــي مــن إدارة األدلــة اجلنائيــة رقــم (‪/23‬فحــوص حيويــة‬\n‫دم ‪1433‬هــ) املتضمــن ســلبية املشــرط والبالطــة املرفوعــة مــن مســرحة‬\n‫اجلرميــة وجــرى إحالــة املدعــى عليــه الثانــي للســجن العــام مبوجــب‬\n‫مذكــرة التوقيــف رقــم (‪ )6117‬يف ‪1432/11/4‬ه ـ واعتبــار إيقافــه مــن‬\n‫تاريــخ ‪1432/10/16‬ه ـ وجــرى إحالــة املدعــى عليــه األول للســجن العــام‬\n‫مبوجــب مذكــرة التوقيــف رقــم (‪ )6371‬يف ‪1432/11/17‬ه ـ واعتبــار‬\n‫إيقافــه مــن تاريــخ ‪1432/10/28‬ه ـ وجــرى تســليم اجلــوازات واإلقامــات‬\n‫للمواطــن ‪...‬وقــدر قيمــة اجلهــاز احملمول بقيمة ألفني وأربعني ريـ‪ 2040‬ــال‬\n‫وكذلــك اجلوالــن املســروقة وأفــاد املدعــي ‪...‬بأنــه قــام بشــرائها بألــف‬\n‫وثمامنائة ريـ‪ 1800‬ــال وبسماع أقوال املواطن ‪ ...‬سعودي اجلنسية مبوجب‬\n‫الســجل املدنــي رقــم (‪ )...‬أفــاد أنــه كان يســكن بنفــس الفنــدق بالغرفــة‬\n‫رقــم ‪ ...‬وأفــاد أن املدعــى عليــه الثانــي كان يســكن معــه وأنــه غــادر‬\n‫الفنــدق وتركــه بالغرفــة وأنكــر عالقتــه بالســرقة ومت حفــظ الدعــوى‬\n‫بحــق ‪...‬اســتنادا للمــادة (‪ )124‬مــن نظــام اإلجــراءات اجلزائيــة لعــدم‬\n‫كفايــة األدلــة وبالتحقيــق مــع املدعــى عليــه الثانــي ‪...‬اعتــرف بقيامــه‬\n‫بالســرقة حيــث قــام بالدخــول إلــى الغرفــة مــن الشــباك وأخــذ مــن الغرفة‬\n‫جهــاز محمــول وكان املدعــى عليــه األول ‪ ...‬يراقبــه وقــام ‪...‬بالدخــول‬\n‫للغرفــة األخــرى وســرق منهــا شــنطتني واحــدة بهــا جــوازات واألخــرى‬\n‫بهــا عــاج وســرق منهــا جوالــن مــن نــوع ‪ ....‬وقــام بإعطائــه إياهــا وأنــه‬\n‫قــام ببيعهــا وأن اجلهــاز احملمــول قــام بإعطائــه املدعــو ‪...‬كمــا أقــر بأنــه‬\n‫أخــذ مبلــغ أربعــة آالف وخمســمائة ريـ‪ 4500‬ــال وأن املدعــو ‪...‬قــام بأخــذ‬\n‫أربعــة آالف وخمســمائة ريـ‪ 4500‬ــال وبالتحقيــق مــع املدعــى عليــه األول‬\n\n\n                                                                                       ‫‪226‬‬\n\f      ‫‪...‬أنكــر قيامــه بالســرقة وجــرى مواجهــة املدعــى عليهمــا وأصــر كال‬\n      ‫منهمــا علــى أقوالــه وبضبــط شــهادة املدعــو ‪...‬والــد املدعــى عليــه الثانــي‬\n      ‫أفــاد بــأن اجلــوازات واإلقامــات مت تســليمها لــه مــن قبــل املدعــى عليــه‬\n      ‫األول ومبواجهــة املدعــو ‪ ...‬باملدعــى عليــه األول أصــر كال منهمــا علــى‬\n      ‫أقوالــه ولــم يظهــر مــا يفيــد التحقيــق وملــا أشــير إليــه أقــرر توجيــه االتهــام‬\n      ‫للمدعــى عليهمــا بســرقة مجموعــة مــن اجلــوازات واإلقامــات ومبلغــا‬\n      ‫ماليــا يقــدر بتســعة آالف وســتمائة وعشــرين ريـ‪ 9620‬ــال وجهازيــن‬\n      ‫جــوال مــن نــوع ‪ ...‬وجهــاز محمــول وحيــث أن مــا أقــدم عليــه املذكــوران‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا وهــو ســرقة مــال محتــرم مــن حــرزه‬\n      ‫وبلــغ النصــاب وال شــبهة لهمــا فيــه وهمــا مكلفــن غيــر مكرهــن لــذا‬\n      ‫أطلــب مــا يلــي‪ -1 :‬إثبــات مــا أســند إليهمــا ‪ -2‬احلكــم عليهمــا بحــد‬\n      ‫الســرقة الــوارد يف اآليةالكرميــة رقــم (‪ )38‬مــن ســورة املائــدة (علمــا بــأن‬\n      ‫احلــق اخلــاص ال يــزال قائمــا) هــذه دعــواي وبعــرض دعــوى املدعــي العــام‬\n      ‫علــى املدعــى عليــه الثانــي أجــاب قائــا مــا جــاء يف دعــوى املدعــي العــام‬\n      ‫بعضــه صحيــح وبعضــه غيــر صحيــح والصحيــح أن لــي ابــن عــم يدعــى ‪...‬‬\n      ‫كان قــد قــدم إلــى منطقــة ‪ .....‬واســتأجر غرفــة يف فنــدق ‪...‬بالــدور األول‬\n      ‫وملــا أتــى الصبــاح اتصــل علــي ابــن عمــي ‪...‬وأخبرنــي بأنــه ســيخرج مــن‬\n      ‫الغرفــة وبقــي لــه فيهــا ســاعات وبإمكانــي املجــيء إلــى الغرفــة واجللــوس‬\n      ‫فيهــا بقيــة اليــوم وفعــا ملــا خــرج ابــن عمــي ‪...‬مــن الغرفــة أتيــت إليهــا‬\n      ‫يف متــام الســاعة الســابعة صباحــا وجلســت فيهــا واتصلــت علــى املدعــى‬\n      ‫عليــه األول ‪...‬وطلبــت منــه املجــيء إلــى الفنــدق لكــي جنلــس ونتجــاذب‬\n      ‫أطــراف احلديــث ولــم تكــن يف نيتــي الســرقة أبــدا وفعــا أتــى إلــى‬\n      ‫املدعــى عليــه األول ‪...‬وجلســنا قليــا وقــال لــي املدعــى عليــه األول ‪...‬هيــا‬\n\n\n‫‪227‬‬\n\f‫بنــا نســرق مــن الغــرف فرافقتــه فذهــب هــو إلــى غرفــة وأنــا ذهبــت إلــى‬\n‫غرفــة أخــرى والغــرف مت الدخــول إليهــا عــن طريــق النافــذة التــي بداخــل‬\n‫(املمــر) فدخــل املدعــى عليــه األول ‪...‬الغرفــة التــي بهــا شــنطة اجلــوازات‬\n‫ورخــص اإلقامــة واجلوالــن املوصوفــن يف الدعــوى وقمنــا ببيعهمــا مببلــغ‬\n‫وقــدره ثمامنائــة ريـ‪ 800‬ــال يف محــل ال أتذكــر اســمه ولكــن يقــع يف‬\n‫شــارع ‪ ............‬وأنــا ســرقت مــن الغرفــة األخــرى جهــاز الب تــوب فقــط‬\n‫ولــم أســرق مبلــغ وقــدره مائــة ريـ‪ 100‬ــال وبعــد أن انتهينــا مــن الســرقة‬\n‫اجتمعنــا يف غرفتنــا ووجــدت مــع املدعــى عليــه األول ‪...‬شــنطة الب تــوب‬\n‫موجــود بداخلهــا اجلــوازات واإلقامــات ومعــه جهازيــن جــوال وال أعلــم هــل‬\n‫هــو قــام بســرقة املبلــغ املالــي املذكــور يف الدعــوى وقــدره تســعة آالف‬\n‫وخمســمائة وعشــرون ‪ 9520‬ريــال أم ال ألنــه لــم يخبرنــي بذلــك وأخــذ‬\n‫منــي املدعــى عليــه األول ‪...‬جهــاز الــاب تــوب وال أعلــم عنــه حتــى تاريخــه‬\n‫هــل باعــه أم ال وقبــل خروجنــا مــن الغرفــة قــام املدعــى عليــه األول ‪......‬‬\n‫بأخــذ مجموعــة مــن جــوازات الســفر ورخصاإلقامــة ورمــى الباقــي‬\n‫املوجوديــن يف الشــنطة خــارج الفنــدق مــن النافــذة علــى ســطح الورشــة‬\n‫املوجــودة خلــف الفنــدق وأنــا تائــب إلــى اهلل ونــادم علــى مشــاركتي‬\n‫لــه يف الســرقة علمــا بأنــه ملــا مت طلبــي مــن قبــل الشــرطة اتصلــت علــى‬\n‫املدعــى عليــه األول ‪...‬وطلبــت منــه أن يقــوم بإرجــاع اجلــوازات ورخــص‬\n‫اإلقامــة إلــى والــدي ‪...‬وســلمت نفســي للشــرطة وفعــا ذهــب والــدي إلــى‬\n‫بيــت املدعــى عليــه ‪...‬وطلــب منــه إرجــاع اجلــوازات ورخــص اإلقامــة لــه‬\n‫فرفــض وهــرب مــن البيــت وقــام املدعــى عليــه األول ‪...‬بوضــع اجلــوازات‬\n‫ورخــص اإلقامــة يف ســيارة والــدي لكــون نافــذة الســيارة مفتوحــة وال‬\n‫تعمــل جيــدا ولــم يســلم نفســه املدعــى عليــه األول ‪...‬إال بعــد إيقــايف بســبع‬\n\n\n                                                                                       ‫‪228‬‬\n\f      ‫وعشــرين يومــا هــذه إجابتــي وأضــاف املدعــى عليــه الثانــي ‪...‬قائال أطلب‬\n      ‫مــن فضيلتكــم النظــر إلــي بعــن الرحمــة وهــذه أول مــرة وهــي آخــر مــرة‬\n      ‫وأنــا ال توجــد علــي ســوابق جنائيــة غيــر مــا ذكــرت هكــذا أضــاف‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه األول ‪...‬أجــاب قائــا‬\n      ‫مــا جــاء يف دعــوى املدعــي العــام ضــدي غيــر صحيــح جملــة وتفصيــا‬\n      ‫فأنــا لــم أقــم بالســرقة وال أعلــم عــن هــذه املســروقات شــيئا وليــس لــي‬\n      ‫عالقــة بهــذه الســرقة ال مــن قريــب وال مــن بعيــد هــذه إجابتــي وبعــرض‬\n      ‫إجابــة املدعــى عليــه الثانــي ‪...‬علــى املدعــى عليــه األول ‪...‬أجــاب قائــا‬\n      ‫مــا ذكــره املدعــى عليــه الثانــي ‪...‬يف إجابتــه علــى دعــوى املدعــي العــام‬\n      ‫وأننــي مشــترك معــه يف الســرقة فغيــر صحيــح أبــدا كمــا ذكــرت ذلــك‬\n      ‫يف إجابتــي علــى دعــوى املدعــي العــام هكــذا أجــاب وبســؤال املدعــي‬\n      ‫العــام عــن بينتــه علــى طبــق دعــواه أجــاب قائــا بينتــي ســأحضرها يف‬\n      ‫اجللســة القادمــة هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي العــام‬\n      ‫وحضــر حلضــور املدعــى عليهمــا وبســؤال املدعــي العــام عــن بينتــه التــي‬\n      ‫وعــد بإحضارهــا يف هــذه اجللســة فأجــاب قائــا بينتــي هــي مايلــي‪-1 :‬‬\n      ‫مــا جــاء يف اعتــراف املتهــم ‪...‬املــدون علــى الصفحــة رقــم (‪ )11‬لفــة رقــم‬\n                                                                                     ‫(‪)1‬‬\n      ‫‪ -2‬مــا جــاء بشــهادة الشــاهد املدونــة علــى الصفحــة رقــم (‪ )7‬لفــة رقــم‬\n      ‫(‪ -3 )4‬محضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪)6-5‬‬\n      ‫لفــة رقــم (‪ -4 )4‬مــا جــاء بأقــوال املتهــم أحمــد مبشــاركة املتهــم ‪...‬معــه‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )10-9‬لفــة رقــم (‪ )1‬هــذه بينتــي وجــرى‬\n      ‫منــا االطــاع علــى الدليــل األول مــن أدلــة املدعــي العــام وهــو مــا جــاء يف‬\n      ‫اعتــراف املدعــى عليــه ‪...‬املــدون علــى الصفحــة رقــم (‪ )11‬لفــة رقــم (‪)1‬‬\n\n\n‫‪229‬‬\n\f‫ونصه(أقــر أنــا املواطــن ‪...‬ســعودي مبوجــب بطاقــة رقــم (‪ )...‬مصدرهــا‬\n‫تبــوك وأنــا بكامــل قــواي العقليــة واملعتبــرة شــرعا وبــدون إكــراه مــن‬\n‫أحــد بأنــي قمــت بالســرقة مــن فنــدق ‪...‬أنــا و‪...‬وســرقت جهــاز البتــوب‬\n‫وجوالــن واجلــوازات أخذهــا ‪...‬وأنــا مــن قــام ببيــع اجلــواالت واملبلــغ‬\n‫املذكــور واملســروقات ال أعلــم عنهــا شــيئا وأنــا مــن قــام بدخــول الغرفــة‬\n‫مــن الشــباك وأخــذت منهــا جهــاز البتــوب والغرفــة األخــرى دخلهــا ‪...‬مــن‬\n‫الشــباك وأنــا مســؤول عــن عالقتــي وعلــى هــذا أوقع)أ‪.‬ه ـ املقــر مبــا فيــه‬\n‫‪......‬بصمتــه وجــرى منــا االطــاع علــى الدليــل الثانــي مــن أدلــة املدعــي‬\n‫العــام وهــو مــا جــاء بشــهادة الشــاهد املدونــة علــى الصفحــة رقــم (‪ )7‬لفــة‬\n‫رقــم (‪ )4‬ونصــه (أشــهد أنــا املواطــن ‪ ...‬ســعودي مبوجــب ســجل رقــم (‪)...‬‬\n‫مصدرهــا ‪ .....‬يســكن حــي ‪ ....‬متســبب إمــام مســجد ‪ ...‬الفيصليــة العمــر‬\n‫‪ 60‬جــوال ( ‪ )...‬أشــهد بــأن الــذي أعطانــي اجلــوازات ووضعهــا يف ســيارتي‬\n‫هــو ‪...‬وقــام بوضــع اجلــوازات يف الســيارة والهــروب وعلــى ذلــك أوقع)أ‪.‬ه ـ‬\n‫املقــر مبــا فيــه ‪ ...‬توقيعــه وجــرى منــا االطــاع علــى الدليــل الثالــث مــن‬\n‫أدلــة املدعــي العــام وهــو محضــر االنتقــال واملعاينــة املــدون علــى الصفحــة‬\n‫رقــم (‪ )5،6‬لفــة رقــم (‪ )4‬ونصه(مبعرفتــي أنــا املــازم ‪...‬ضابــط التحقيــق‬\n‫بشــرطة ‪ .....‬جــرى االنتقــال إلــى موقــع الســرقة واتضــح أنــه عبــارة عــن‬\n‫فنــدق واســمه فنــدق ‪...‬يقــع علــى شــارعني شــرقي وشــمالي بالقــرب منــه‬\n‫إشــارة مــرور ويحــده مــن الغــرب ورشــة واالجتــاه اجلنوبــي حــوش عبــارة‬\n‫عــن موقــف ســيارة والفنــدق مكــون مــن عــدة أدوار الــدور األرضــي‬\n‫عبــارة عــن اســتقبال وبــه صالــة طعــام والــدور األول مكــون مــن عــدة‬\n‫غــرف واتضــح أن غرفــة املجنــي عليــه (‪ )........‬تقــع يف الــدور األول رقــم‬\n‫‪ 500‬وتقــع علــى ممــر الغرفــة مســاحة حوالــي ثالثــة أمتــار يف ثالثــة يوجــد‬\n\n\n                                                                                      ‫‪230‬‬\n\f      ‫بهــا بــاب علــى أول املدخــل علــى اليســار واتضــح أنــه يفتــح علــى دورة ميــاه‬\n      ‫ويوجــد يف الغرفــة عــدد اثنــن ســرير وطاولــة وشــماعة مالبــس ودرج‬\n      ‫صغيــر وبهــا شــباك مســافة متــر يف متــر علــى منــور واتضــح دخــول اجلنــاة‬\n      ‫عــن طريــق الشــباك وباالنتقــال إلــى الغرفــة العائــدة للمواطــن ‪ ...‬اتضــح‬\n      ‫عبــارة عــن غرفــة بنفــس مســاحة الغرفــة الســابقة ويوجــد بهــا ســريرين‬\n      ‫وطاولــة ومــرآة وشــماعة مالبــس ودورة ميــاه وشــباك مســاحته حوالــي‬\n      ‫متــر يف متــر ودخــول اجلنــاة عــن طريــق الشــباك الــذي يفتــح علــى املمــرات‬\n      ‫منــاور وباألســقف إلــى الغرفــة املشــتبه بــه اتضــح أنــه عبــارة عــن غرفــة‬\n      ‫بداخلهــا ســريرين وبنفــس مواصفــات الغرفــة الســابقة أن بهــا شــباك‬\n      ‫يطــل علــى الورشــة وبالبحــث مت العثــور علــى اجلــوازات والشــنطة التــي‬\n      ‫بهــا اجلــوازات وشــنطة وبهــا عــدد تســع جــوازات وتســع إقامــات وكانــت‬\n      ‫علــى هنقــر الورشــة وعثــر علــى قفــاز ومشــرط يف غرفــة ‪...‬وحفظــا للواقع‬\n      ‫نظــم هــذا احملضــر )أ‪.‬ه ـ رجــل الضبــط فنــي أول توقيعــه وجــرى منــا‬\n      ‫االطــاع علــى الدليــل الرابــع مــن أدلــة املدعــي العــام وهــو مــا جــاء بأقــوال‬\n      ‫املتهم‪...‬مبشــاركة املتهــم ‪...‬معــه املدونــة علــى الصفحــة رقــم (‪)9،10‬‬\n      ‫لفــة رقــم (‪ )1‬ونصهــا (س‪ /‬أعطنــي معلومــات أحصائيــة عــن نفســك؟‬\n      ‫االســم ‪...‬ســعودي مبوجــب ســجل رقــم (‪ )...‬مصدرهــا ‪ ....‬العمــل ال يعمــل‬\n      ‫الســكن الفيصليــة العمــر ‪ 22‬ســنة س‪ /‬أنــت متهــم بالســرقةمن فنــدق ‪...‬‬\n      ‫مــاذا تقــول؟ نعــم قمــت بالســرقة مــن فنــدق ‪ ...‬أنــا و‪...‬س‪ /‬كيــف حصلت‬\n      ‫الســرقة؟ بعدمــا خــرج ‪...‬مــن الفنــدق الســاعة الثالثــة صباحــا جلســنا يف‬\n      ‫الفنــدق ويف حوالــي الســاعة الثامنــة صباحــا اتصلــت علــى ‪...‬مــن أجــل‬\n      ‫أذهــب معــه قــال لــي (ودنــا نســرق) ثــم خــرج مــن الغرفــة وذهــب إلــى‬\n      ‫شــباك يف املمــر وطلــع مــع الشــباك ثــم طلعــت بعدهــا ودخلــت إلــى الغرفــة‬\n\n\n‫‪231‬‬\n\f‫مــن الشــباك وأخــذت جهــاز الب تــوب وكان ‪...‬يراقــب ثــم خرجــت مــن‬\n‫الغرفــة وذهبــت إلــى الغرفــة املســتأجرينها وبعدهــا ذهب‪...‬إلــى الغرفــة‬\n‫الثانيــة وكنــت أراقــب لــه ودخــل هــو الغرفــة وكنــت انتظــره عنــد‬\n‫الشــباك املمــر ورجــع معــه شــنطتني واحــدة بهــا جــوازات واألخــرى عــاج‬\n‫ومعــه جوالــن وبعدهــا أعطانــي اجلــواالن وقــال لــي بعهمــا س‪ /‬مــن الــذي‬\n‫أخــذ املبلــغ الــذي كان مــع اجلــوازات؟ ال أعلــم عــن املبلــغ أي شــيء ألن‬\n‫‪...‬هــو الــذي جــاء بشــنطة اجلــوازات س‪ /‬أيــن ذهــب باجلــوازات واجلــواالت‬\n‫وجهــاز الــاب تــوب واملبلــغ ج‪ /‬أخذنــا اجلــواالت فقــط وبعناهــا س‪ /‬كــم‬\n‫بعــت اجلــواالت ج‪ /‬أربعمائــة وســتني ريـ‪ 460‬ــال و ثالثمائــة وخمســن‬\n‫ريـ‪ 350‬ــال س‪ /‬مــن أخــذ جهــاز الــاب تــوب ج‪ /‬أخــذت اجلهــاز يف الغرفــة‬\n‫وبعدهــا خرجــت مــن الفنــدق وأخــذه ‪...‬وقــال أنــا أبيعــه س‪ /‬ملــاذا أخــذت‬\n‫اجلــوازات؟ ج‪ /‬لــم آخــذ اجلــوازات س‪ /‬مــن الــذي أخذهــا؟ ج‪ .../‬س‪ /‬ملــاذا‬\n‫أخــذ اجلــوازات؟ ج‪ /‬ال أعلــم س‪ /‬هــل كان معــك أحــد غيــر ‪.........‬؟ ج‪/‬‬\n‫ال يوجــد أحــد غيرنــا أنــا و‪...‬س‪ /‬هــل لديــك أقــوال أخــرى؟ ج‪ /‬نعــم أن‬\n‫‪...‬ليــس لــه أي عالقــه بالســرقة س‪/‬هــل تصــادق علــى أقوالــك؟ ج‪/‬نعــم )‬\n‫أ‪.‬ه ـ املقــر مبــا فيــه ‪...‬بصمتــه وبعــرض أدلــة املدعــي العــام علــى املدعــى‬\n‫عليــه الثاني‪...‬أجــاب قائــا مــا جــاء يف اعتــرايف كلــه صحيــح وكذلــك‬\n                           ‫مــا جــاء يف شــهادة والــدي فصحيــح وهــو موجــود‬\n‫قــد أحضــره املدعــي العــام يف هــذه اجللســة وأطلــب من فضيلتكم ســماع‬\n‫مــا لديــه مــن الشــهادة وكذلــك مــا جــاء يف محضــر االنتقــال واملعاينــة‬\n‫مــن وصــف الغرفتــن ووجــود شــنطة اجلــوازات مرميــة خــارج الفنــدق فــوق‬\n‫(الهنقــر) فصحيــح وأن الــذي رمــى الشــنطة ومافيهــا املدعــى عليــه األول‬\n‫‪...‬ومــا جــاء يف أقوالــي أيضــا كلهــا صحيحــة وأنــا مقــر بهــا هكــذا‬\n\n\n                                                                                      ‫‪232‬‬\n\f      ‫أجــاب وبعــرض أدلــة املدعــي العــام علــى املدعــى عليــه األول ‪...‬أجــاب‬\n      ‫قائــا مــا جــاء يف اعتــراف املدعــى عليــه الثانــي ‪...‬بقيامــه الســرقة فهــذا‬\n      ‫يخصه وال يخصني وال أعلم عنه وكذلك ال أعلم عن محضر االنتقال‬\n      ‫واملعاينــة شــيئا فأنــا لــم أدخــل فنــدق ‪...‬طيلــة حياتــي أبــدا ومــا جــاء يف‬\n      ‫أقــوال املدعــى عليــه الثانــي ‪...‬مــن أننــي شــاركته يف الســرقة فهــذا غيــر‬\n      ‫صحيــح أبــدا أمــا بالنســبة لشــهادة والــد املدعــى عليــه الثانــي ‪...‬فأطلــب‬\n      ‫إحضــاره والســماع منــه ثــم ســأقوم باإلجابــة علــى ماسيشــهد بــه هكــذا‬\n      ‫أجــاب وبطلــب الشــاهد حضر‪...‬الســعودي بالســجل املدنــي رقــم ‪...‬ســجل‬\n      ‫تبــوك وجــرى ســؤاله عــن ســنه ومهنتــه ومحــل إقامتــه وعالقتــه باملدعــى‬\n      ‫عليهمــا فأجــاب قائــا إننــي مــن مواليــد ‪1374/7/1‬ه ـ ومتســبب وأعمــل‬\n      ‫حاليا مؤذنا يف مســجد ‪...‬وأســكن يف حي الفيصلية وعالقتي باملدعى‬\n      ‫عليــه الثانــي ‪...‬فهــو ابنــي أمــا املدعــى عليــه األول ‪...‬فأنــا وأبيــه متزوجــان‬\n      ‫بأختــن واملدعــى عليــه األول‪...‬واملدعى عليــه الثاني ‪...‬أوالد خالة هكذا‬\n      ‫أجــاب وجــرى ســؤاله عمــا لديــه مــن الشــهادة فأجــاب قائــا أشــهد بــاهلل‬\n      ‫بــأن أخــي ‪...‬الــذي يتقدمنــي يف الســن وهــو والــد املدعــو ‪...‬صاحــب‬\n      ‫الغرفــة األســاس جائنــي إلــى بيتــي وأخبرنــي بــأن ابنــي املدعــى عليــه‬\n      ‫الثانــي ‪...‬قــد ســرق مــن الفنــدق جــوازات وغيرهــا مــع رجــل آخــر ال يعلــم‬\n      ‫عــن اســمه وقمــت مبنــاداة ابنــي املدعــى عليــه الثاني‪...‬وأخبرنــي بأنــه قــام‬\n      ‫بالســرقة مــع املدعــى عليــه األول ‪...‬وأخبرنــي أن اجلــوازات مــع املدعــى‬\n      ‫عليــه األول ‪ ...‬فضربتــه ضربــا مبرحــا حتــى مت نقلــه إلــى املستشــفى ثــم‬\n      ‫أمــرت ابنــي ‪...‬أن يتصــل علــى املدعــى عليــه األول ‪...‬ويطلــب منــه أن يقــوم‬\n      ‫بإعطائــي اجلــوازات لكــي أقــوم بتســليمها إلــى الشــرطة وفعــا اتصــل‬\n      ‫ابنــي ‪...‬علــى املدعــى عليــه األول ‪...‬وكنــت أســمع احملادثــة عــن طريــق‬\n\n\n‫‪233‬‬\n\f‫مكبــر الصــوت وطلــب ابنــي ‪...‬مــن املدعــى عليــه األول ‪...‬أن يســلمه‬\n‫اجلــوازات لكــي يســلمها لــي ووعــده أن يســلمه اجلــوازات يف يــوم غــدا‬\n‫وأمــرت ابنــي ‪...‬أن يخبــره بــأن يضــع اجلــوازات يف الســيارة وســأترك لــه‬\n‫نافــذة الســيارة مفتوحــة وفعــا ملــا أتــى الصبــاح خرجــت مــن بيتــي وإذ‬\n‫باملدعــى عليــه األول ‪...‬بجانــب ســيارتي وســألته مــاذا عنــدك فأخبرنــي‬\n‫بأنــه يريــد خالتــي التــي هــي زوجتــي فقلــت لــه اذهــب لهــا فــوق ولــم يكــن‬\n‫أحــد غيرنــا يف احلــارة وفعــا فتحــت الســيارة ووجــدت اجلــوازات داخلهــا‬\n‫هــذا مالــدي مــن الشــهادة وبعــرض شــهادة الشــاهد ‪...‬علــى املدعــى عليــه‬\n‫األول ‪...‬أجــاب قائــا مــا جــاء يف شــهادة الشــاهد غيــر صحيــح جملــة‬\n‫وتفصيــا هكــذا أجــاب ثــم ظهــر عليــه االرتبــاك وقــال أن النــاس‬\n‫مظاهــر وقــال حقــي إذا لــم آخــذه منــك يف الدنيــا فســآخذه يف اآلخــرة‬\n‫فأثبــت ذلــك وبطلــب معدلــن مــن الشــاهد ‪...‬حضــر ‪...‬الســعودي بالســجل‬\n‫املدنــي رقــم ‪...‬ســجل تبــوك و ‪...‬الســعودي بالســجل املدنــي رقــم ‪...‬ســجل‬\n‫تبــوك فشــهدا بعدالــة الشــاهد املذكــور وبســؤال املدعــي العــام واملدعــى‬\n‫عليهمــا هــل لديهــم مايريــدون إضافتــه يف هــذه القضيــة فأجابــوا قائلــن‬\n‫ليــس لدينــا ســوى ماقدمنــا ونطلــب احلكــم يف هــذه القضيــة هكــذا‬\n‫أجابــوا عليــه فقــد تأجلــت القضيــة للدراســة والتأمــل ويف جلســة أخــرى‬\n‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليهمــا فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه األول ‪...‬مــا جــاء‬\n‫يف دعــوى املدعــي العــام مــن قيامــه بالســرقة جملــة وتفصيــا وإلقــرار‬\n‫املدعــى عليــه الثانــي ‪...‬بقيامــه بســرقةجهاز الــاب تــوب املوصــوف يف‬\n‫الدعــوى واشــتراكه مــع املدعــى عليــه األول ‪ ...‬بســرقة كل من اجلوالني‬\n‫املوصوفــن يف الدعــوى وبيعهمــا وســرقة شــنطة اجلــوازات وأخــذ بعــض‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫مــا فيهــا مــن جــوازات ورميهــا خــارج الفنــدق وإقــراره بــأن املدعــى عليــه‬\n      ‫األول ‪...‬قــد شــاركه يف الســرقة وحلرمــة دم املســلم ومالــه وعرضــه يف‬\n      ‫الشــريعة اإلســامية ولشــهادة الشــاهد ‪...‬والــد املدعــى عليــه الثانــي‬\n      ‫‪...‬مــن أنــه رأى املدعــى عليــه األول ‪...‬عنــد ســيارته يف وقــت ال يوجــد فيــه‬\n      ‫غيرهمــا وأنــه رأى اجلــوازات املســروقة داخــل ســيارته وألن شــهادته ضــد‬\n      ‫املدعــى عليــه األول ‪...‬جتــر البنــه املدعــى عليــه الثانــي ‪...‬نفعــا وملــا جــاء يف‬\n      ‫كتــاب املغنــي ‪ 182/14‬مــا نصــه (فأمــا شــهادة أحدهمــا علــى صاحبــه‬\n      ‫فتقبــل نــص عليــه ‪...‬وهــذا قــول عامــة أهــل العلــم ولــم أجــد فيــه خالفــا‬\n      ‫وذلــك لقــول اهلل تعالــى ( كونــوا قوامــن بالقســط شــهداء هلل ولــو علــى‬\n      ‫أنفســكم أو الوالديــن واألقربــن) فأمــر بالشــهادة عليهــم ولــو لــم تقبــل‬\n      ‫ملــا أمــر بهــا وألنهــا إمنــا ردت للتهمــة يف إيصــال النفــع وال تهمــة يف شــهادته‬\n      ‫عليــه فوجــب أن تقبــل كشــهادة األجنبــي بــل أولــى فــأن شــهادته لنفســه‬\n      ‫ملــا ردت للتهمــة يف إيصــال النفــع إلــى نفســه كان إقــراره عليهــا مقبــوال)‬\n      ‫أ‪.‬ه ـ وألن مــن شــروط إقامــة حــد الســرقة انتهــاك احلــرز فلــم جنــد أن‬\n      ‫املدعــى عليهمــا قــد انتهــكا حــرزا أو قامــوا بكســر بــاب أو نافــذة وألنه‬\n      ‫ال يوجــد للمدعــى عليــه األول ‪...‬إقــرار مصــدق شــرعا وال حتقيقــا لــذا‬\n      ‫فقــد حكمنــا مبــا يلــي‪ :‬أوال توجــه التهمــة يف قيــام املدعــى عليــه األول ‪...‬‬\n      ‫بالســرقة‪ .‬ثانيــا إثبــات إدانــة املدعــى عليــه الثانــي ‪...‬بســرقة جهــاز الــاب‬\n      ‫تــوب املوصــوف يف الدعــوى واالشــتراك يف بيــع اجلوالــن املســروقني‬\n      ‫املوصوفــن يف الدعــوى ودرءنــا عنــه حــد الســرقة‪ .‬ثالثــا تعزيــر املدعــى‬\n      ‫عليهمــا األول ‪...‬والثانــي ‪...‬وذلــك بســجن األول ســنة وســجن الثانــي أربــع‬\n      ‫ســنوات تبــدأ مــن تاريــخ إيقافهمــا بســبب هــذه القضيــة‪ .‬رابعــا جلــد‬\n      ‫املدعــى عليهمــا األول ‪...‬مائتــي جلــدة مفرقــة علــى أربــع دفعــات متســاوية‬\n\n\n‫‪235‬‬\n\f‫بــن كل دفعــة وأخــرى خمســة عشــر يومــا والثانــي ‪...‬أربعمائــة جلــدة‬\n‫مفرقــة علــى ثمــان دفعــات متســاوية بــن كل دفعــة وأخــرى خمســة‬\n‫عشــر يومــا‪ .‬هكــذا حكمنــا وبعــرض احلكــم علــى جميــع األطــراف‬\n‫قــرر املدعــى عليــه الثانــي ‪...‬قناعتــه باحلكــم واعتــرض عليــه املدعــى‬\n‫عليــه األول ‪...‬وطلــب متييــزه مــن دون تقــدمي الئحــة اعتراضيــة واعتــرض‬\n‫عليــه املدعــي العــام وطلــب متييــزه مــع تقــدمي الئحــة اعتراضيــة فأجيــب‬\n‫إلــى طلبــه وســلم صــورة مــن القــرار الشــرعي يف هــذه اجللســة بتاريــخ‬\n‫‪1433/4/21‬ه ـ وأفهمنــاه بــأن لــه مــدة أقصاهــا ثالثــون يومــا مــن‬\n‫هــذا التاريــخ فــإذا انقضــت املــدة ولــم يقــدم اعتراضــه فإنــه يســقط‬\n‫حقــه يف االعتــراض وترفــع املعاملــة إلــى مقــام محكمــة االســتئناف‬\n‫املوقــرة باجلــوف لتدقيــق احلكــم حســب املتبــع ففهــم ذلــك واختتمــت‬\n‫اجللســة يف متــام الســاعة احلاديــة عشــر وخمســن دقيقــة وللبيــان حــرر يف‬\n                  ‫‪1433/4/21‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم االثنــن ‪1434/1/5‬ه ـ فقــد وردتنــا‬\n‫املعاملــة مــن مقــام محكمــة االســتئناف املوقــرة باجلــوف مبوجــب خطاب‬\n‫فضيلــة رئيســها رقــم ‪ 331013837‬يف ‪1433/11/20‬ه ـ وبرفقــه القــرار‬\n‫الصــادر مــن الدائــرة اجلزائيــة اخلماســية األولــى رقــم ‪ 33407255‬يف‬\n‫‪1433/9/10‬ه ـ ونــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ مــا يلــي ‪ :‬أوال‪ :‬لــم جنــد‬\n‫التصريــح يف احلكــم بــرد دعــوى املدعــي العــام إقامــة حــد الســرقة علــى‬\n‫املدعــى عليــه األول ملــا ذكــره أصحــاب الفضيلــة ثانيــا‪ :‬احلكــم الصــادر‬\n‫علــى املدعــى عليــه األول قليــل لقــوة األدلــة والقرائــن املؤيــدة للتهمــة‬\n‫املوجهــة ضــده وليــس بأقــل مــن الثانــي إال إنــه مــراوغ لــم يعتــرف ثالثــا‪:‬‬\n\n\n                                                                                      ‫‪236‬‬\n\f      ‫احلكــم الصــادر علــى املدعــى عليــه الثانــي كثيــر لظهــور بــوادر النــدم‬\n      ‫عليــه وتعاونــه ووالــده يف إعــادة بعــض املســروقات ألصحابهــا وعــدم‬\n      ‫وجــود ســوابق عليــه وملــا ظهــر منــه عزمــه علــى عــدم العــودة واملقصــد‬\n      ‫اســتصالح حالــه ممــا يتوجــه إعــادة النظــر يف احلكــم الصــادر عليــه‬\n      ‫فعلــى أصحــاب الفضيلــة إعــادة النظــر وإكمــال الــازم وإحلــاق مــا‬\n      ‫يجــد للضبــط وصورتــه والقــرار وســجله ثــم إعــادة املعاملــة كاملتبــع‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم)‬\n      ‫أ‪.‬ه ـ قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف‪...‬وقع األصــل‬\n      ‫وانتهــى انتدابــه قاضــي اســتئناف‪...‬ختمه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه وجنيــب مشــايخنا‬\n      ‫حفظهــم اهلل لوجاهــة مــا رأوه عــن الفقــرة األولــى فقــد حكمنــا بــرد‬\n      ‫دعــوى املدعــي العــام إقامــة حــد الســرقة علــى املدعــى عليــه وجنيــب عــن‬\n      ‫الفقــرة الثانيــة والثالثــة وبعــد التأمــل فقــد رجعنــا عمــا حكمنــا بــه مــن‬\n      ‫ســجن وجلــد يف حــق املدعــى عليهمــا وحكمنــا بســجن املدعــى عليــه‬\n      ‫األول ‪ ..........‬بســنتني تبــدأ مــن تاريــخ إيقافــه بســبب هــذه القضيــة وجلــده‬\n      ‫مائتــي جلــدة مفرقــة علــى أربــع دفعــات متســاوية بــن كل دفعــة وأخــرى‬\n      ‫خمســة عشــرة يومــا وحكمنــا بســجن املدعــى عليــه الثانــي ‪...‬ثــاث‬\n      ‫ســنوات تبــدأ مــن تاريــخ إيقافــه بســبب هــذه القضيــة وجلــده ثالثمائــة‬\n      ‫جلــدة مفرقــة علــى ســت دفعــات متســاوية بــن كل دفعــة وأخــرى خمســة‬\n      ‫عشــرة يومــا هــذا جوابنــا ولئــا يخفــى جــرى إحلاقــه بضبطــه وصورتــه‬\n      ‫وســيجري إحلاقــه بالقــرار ثــم إعــادة املعاملــة إلــى محكمــة االســتئناف‬\n      ‫املوقــرة وبعــرض احلكــم علــى جميــع األطــراف قــرر املدعــي العــام‬\n      ‫اعتراضــه مكتفيــا مبــا قدمــه مــن الئحــة وقــرر املدعــى عليــه الثانــي‬\n\n\n‫‪237‬‬\n\f‫‪...‬قناعتــه بــه وســيتم عــرض احلكــم علــى املدعــى عليــه األول ‪...‬يف حــال‬\n‫حضــوره ويف جلســة أخــرى حضــر املدعــى عليــه األول ‪...‬وجــرى عــرض‬\n‫مالحظــات أصحــاب الفضيلــة قضــاة محكمــة االســتئناف املذكــورة‬\n‫وعــرض احلكــم الصــادر يف حقــه فقــرر اعتراضــه عليــه مــن دون تقــدمي‬\n‫الئحــة اعتراضيــة ولئــا يخفــى جــرى إحلاقــه بضبطــه وصورته وســيجري‬\n‫إحلاقــه بالقــرار ثــم إعــادة املعاملــة حملكمــة االســتئناف املوقــرة باجلــوف‬\n‫وللبيــان حــرر يف ‪1434/1/6‬ه ـ وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى يف محكمــة االســتئناف باجلــوف علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك برقــم ‪ 332128231‬وتاريــخ‬\n‫‪1434/1/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫القضــاة الشــيخ ‪ ...‬و‪...‬و‪...‬برقــم ‪ 33205932‬وتاريــخ ‪1433/4/21‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪...‬و ‪...‬يف قضيــة ســرقة وقــد تضمــن‬\n‫القــرار حكــم أصحــاب الفضيلــة علــى النحــو املفصــل فيــه وباإلطــاع‬\n‫علــى مــا أجــاب بــه أصحــاب الفضيلــة القضــاة وأحلقــوه بالقــرار بنــاء علــى‬\n‫قرارنــا الســابق رقم‪33407255‬وتاريــخ ‪1433/9/10‬ه ـ تقــرر املصادقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                              ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪238‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":223,"source_page_end":238,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"462d327ecd48c79fa3a18ea854ae6008da484453ce3801e32bcb4b0393bcec12","normalized_text_hash":"f33ac4583ae1de6bd319252ec381234d4cf9456827db6cf79dbd02170f4cdb20","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p223-33205932"},{"id":"58af1b9d-5bbd-5069-8a34-0c6aa350c749","document_type":"judgment","category":"judicial","subcategory":"general","title":"قصاص األثر -غسل سرقة -سرقة مزرعة -سرقة أغنام -محضر محصلة من نشاط إجرامي -اشتراك يف األموال بحيازة أموال السرقة -بيع املسروقات -املطالبة بحد السرقة-الرجوع عن اإلقرار بالسرقة -درء حد السرقة -تشديد العقوبة خلطورة اجلرمية- التعزير بالسجن واجللد واإلبعاد عن الباد -غرامة مالية .","document_number":"33303859","case_number":"33125542","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":"الدائرة رقم 33396816وتاريخ 1433/8/28ه لوحظ ما يلي أوال","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/17","year":"1434","subject":"قصاص األثر -غسل سرقة -سرقة مزرعة -سرقة أغنام -محضر محصلة من نشاط إجرامي -اشتراك يف األموال بحيازة أموال السرقة -بيع املسروقات -املطالبة بحد السرقة-الرجوع عن اإلقرار بالسرقة -درء حد السرقة -تشديد العقوبة خلطورة اجلرمية- التعزير بالسجن واجللد واإلبعاد عن الباد -غرامة مالية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 33303859 :‬تاريخه ‪1433/06/17 :‬هـ رقم‬\n                              ‫الدعوى ‪33125542 :‬‬\n ‫رقم قرار التصديق من محكمة االستئناف ‪3460112 :‬‬\n                          ‫تاريخه ‪1434/03/11 :‬هـ‬\n\n\n\n      ‫قصــاص األثــر ‪-‬غســل‬ ‫ســرقة ‪ -‬ســرقة مزرعــة ‪-‬ســرقة أغنــام ‪-‬محضــر ّ‬\n      ‫محصلــة مــن نشــاط إجرامــي ‪-‬اشــتراك يف‬    ‫ّ‬       ‫األمــوال بحيــازة أمــوال‬\n      ‫الســرقة ‪-‬بيــع املســروقات ‪-‬املطالبــة بحــد الســرقة‪-‬الرجوع عــن اإلقــرار‬\n      ‫بالســرقة ‪-‬درء حــد الســرقة ‪-‬تشــديد العقوبــة خلطــورة اجلرميــة‪-‬‬\n           ‫التعزيــر بالســجن واجللــد واإلبعــاد عــن البــاد ‪ -‬غرامــة ماليــة ‪.‬‬\n\n\n\n\n         ‫‪-1‬قول النبي صلى اهلل عليه وسلم ‪ (« :‬ادرؤوا احلدود بالشبهات )»‪.‬‬\n      ‫‪-2‬مــا نقلــه صاحــب الشــرح الكبيــر (‪ : )136/10‬عــن األوزاعــي مــا نصــه ‪:‬‬\n                          ‫( وإن رجــع عــن الســرقة أو الشــرب ضــرب دون احلــد )‪.‬‬\n                                  ‫‪-3‬املادة (‪ )16‬من نظام مكافحة غسل األموال ‪.‬‬\n\n\n\n      ‫مقيمــن ‪ -‬أحدهمــا بســرقة أعــداد‬‫َ‬     ‫توجيــه االتهــام للمدعــى عليهمــا ‪-‬‬\n      ‫كبيــرة مــن الغنــم وارتــكاب جرميــة غســل األمــوال واآلخــر مبســاعدته‬\n      ‫لــأول يف جرميــة الســرقة ‪ ،‬حيــث تقــدم مواطــن ببــاغ ملركــز الشــرطة‬\n      ‫عــن تعــرض مزرعتــه لســرقة أغنــام منهــا‪ ،‬ثــم مت االنتقــال للموقــع‬\n      ‫ووصفــه وطريقــة الدخــول والســرقة ‪ ،‬ومت القبــض علــى املدعــى عليهمــا‬\n      ‫بعــد أن قامــا ببيــع األغنــام‪ ،‬وباســتجوابهما اعترفــا مبــا نســب إليهمــا‬\n\n‫‪239‬‬\n\f‫‪ ،‬وصــدق اعترافهمــا شــرع ًا ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند‬\n‫إليهمــا واحلكــم بإقامــة حــد الســرقة بحــق الســارق األول وتعزيــر‬\n‫اآلخــر ‪،‬لوجــود اعتــراف مصــدق شــرع ًا للمدعــى عليهمــا ‪ ،‬لكــن‬\n‫أنكــر املدعــى عليهمــا مــا نســب إليهمــا ‪ ،‬ورجــع املدعــى عليهمــا عــن‬\n‫اعترافهمــا ‪ ،‬لــذا صــدر احلكــم بــدرء حــد الســرقة ‪ ،‬والتعزيــر بالســجن‬\n‫واجللــد والغرامــة واإلبعــاد ‪ .‬وصــدق احلكــم مــن محكمــة االســتئناف‬\n                                            ‫بعــد التوجيــه بزيــادة التعزيــر ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد يف يــوم األربعــاء ‪1433/4/7‬ه ـ لدينا نحن القضاة‬\n‫باحملكمــة العامــة بتبــوك ‪ .........‬وفضيلــة القاضــي ‪ .........‬وفضيلــة‬\n‫القاضــي ‪ .........‬وبنــاء علــى ورود املعاملــة إلــى احملكمــة العامــة بتبــوك‬\n‫بخطــاب رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة تبــوك رقــم‬\n‫‪ 2540‬يف ‪1433/2/16‬ه ـ واملقيــدة يف احملكمــة العامــة بتبــوك برقــم‬\n‫‪ 33328832‬يف ‪1433/2/20‬ه ـ واحملالــة إلــى مكتبنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بتبــوك برقــم ‪ 33125542‬يف ‪1433/2/20‬ه ـ‬\n‫بشــأن دعــوى املدعــي العــام ضــد ‪ .........‬و ‪ .........‬بشــأن قضيــة ســرقة‬\n‫وجرميــة غســيل أمــوال افتتحــت اجللســة األولــى يف متــام الســاعة ‪10 : 23‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .........‬الســعودي بالســجل املدنــي رقــم ‪.........‬‬\n‫وادعــى علــى احلاضــر معــه ‪ .........‬ســوداني اجلنســية مبوجــب اإلقامــة‬\n‫الصــادرة مــن تبــوك رقــم (‪ ) .........‬و‪ .........‬ســوداني اجلنســية مبوجــب‬\n‫اإلقامــة الصــادرة مــن تبــوك رقــم (‪ ) .........‬قائــا يف حتريــر دعــواه‬\n‫بصفتــي مدعيــا عامــا بدائــرة اإلدعــاء العــام لفــرع الهيئــة مبنطقــة تبــوك‬\n\n                                                                                       ‫‪240‬‬\n\f      ‫أدعــي علــى احلاضريــن إنــه بتاريــخ ‪1432/9/26‬ه ـ تقــدم املواطــن ‪.........‬‬\n      ‫ببــاغ ملركــز شــرطة ‪ .........‬مفادهــا تعــرض مزرعتــه الواقعــة بطريــق‬\n      ‫‪ .........‬للســرقة حيــث ســرق منهــا مابلــغ عــدده (‪ )200‬مائتــا رأس مــن‬\n      ‫األغنــام نوعهــا خرفــان نعيمــي وال يتهــم أحــدا بذلــك وبتاريــخ‬\n      ‫‪1432/9/29‬ه ـ حضــر املبلــغ املذكــور للمركــز وأفــاد بــأن عــدد‬\n      ‫األغنــام املســروقة بعــد التأكــد منهــا هــو (‪ )380‬ثالثمائــة وثمانــون‬\n      ‫رأســا مــن األغنــام وبتاريــخ ‪1432/9/27‬ه ـ مت القبــض علــى املدعــى‬\n      ‫عليــه ‪ .......‬وبتاريــخ ‪1432/10/5‬ه ـ مت القبــض علــى املدعــى عليه ‪.........‬‬\n      ‫وبانتقــال رجــل الضبــط اجلنائــي ملوقــع اجلرميــة اتضــح بأنــه يقــع علــى‬\n      ‫طريــق ‪ .........‬بالقــرب مــن ‪ .........‬وهــو عبــارة عــن مزرعــة وتبــن دخــول‬\n      ‫اجلنــاة عــن طريــق فتــح بــاب املزرعــة والدخــول منــه ولــم يتضــح وجــود أي‬\n      ‫آثــار تفيــد التحقيــق وبتاريــخ ‪1432/10/10‬ه ـ مت انتقــال رجــل الضبــط‬\n      ‫اجلنائــي برفقــة صاحــب األغنــام املســروقة املدعــو ‪ .........‬واملدعــى عليــه‬\n      ‫‪ .........‬للداللــة علــى األغنــام املســروقة التــي باعهــا لشــخص يف مزرعــة‬\n      ‫والبالــغ عددهــا (‪ )112‬مائــة واثنــي عشــر رأســا مــن األغنــام ‪.........‬‬\n      ‫واتضــح أن املوقــع عبــارة عــن مزرعــة تقــع علــى طريــق ‪ .........‬بعــد محطــة‬\n      ‫‪ .........‬للمحروقــات علــى طريــق فرعــي (طريــق ‪ ) .........‬واملزرعــة تعــود‬\n      ‫ملكيتهــا للمواطــن ‪ .........‬ومبعاينتهــا اتضــح وجــود حــوش داخــل املزرعة‬\n      ‫معــد لألغنــام وســكن للعمــال واســتراحة لصاحــب املزرعــة ومت مقابلــة‬\n      ‫املواطــن ‪ .........‬الــذي أفــاد بــأن املزرعــة عائــدة لشــقيقه وهــو غيــر موجــود‬\n      ‫كمــا أفــاد بوجــود عــدد (‪ )112‬مائــة واثنــي عشررأســا مــن األغنــام‬\n      ‫‪ .........‬ســبق أن اشــتراها شــقيقه ‪ .........‬مــن شــخص ســوداني ال يعرفــه‬\n      ‫مببلــغ مائــة وثالثــة آالف وخمســمائة ريـ‪ 103500‬ــال وقــد اســتطاع‬\n\n\n‫‪241‬‬\n\f‫املواطــن ‪ .........‬التعــرف علــى األغنــام وأفــاد بأنهــا عائــدة لــه وهــي مــن‬\n‫األغنــام املســروقة التــي أبلــغ عنهــا ومت يف حينــه تســليم األغنــام للمواطــن‬\n‫‪ .........‬ومت إبــاغ شــقيق صاحــب املزرعــة بإبــاغ شــقيقه مبراجعــة‬\n‫التحريــات والبحــث اجلنائــي كمــا أنــه بتاريــخ ‪1432/10/10‬ه ـ مت‬\n‫انتقــال رجــل الضبــط اجلنائــي رفــق املدعــى عليــه ‪ .........‬إلــى أحــد املــزارع‬\n‫بحــي ‪ .........‬حيــث أفــاد بأنــه قــام بوضــع املبلــغ املالــي وقــدره مائــة‬\n‫وخمســون ألــف ريـ‪ 150000‬ــال عنــد أحــد األشــخاص باملزرعــة وقابــل‬\n‫‪ .........‬الشــخص وطلــب منــه تســليم األمانــة وهــي عبــارة عــن كيــس‬\n‫وبالتأكــد منهــا وعدهــا اتضــح وجــود مبلــغ وقــدره مائــة وخمســون ألــف‬\n‫ريـ‪ 150000‬ــال ومت التحفــظ علــى املبلــغ كمــا ورد مبحضــر قصــاص‬\n‫اآلثــار مــن خــال مضاهــاة آثــار املدعــى عليهمــا ومطابقتهــا مــع آثــار‬\n‫الســرقات املجهولــة لألغنــام والتــي ســبق أن قــام مبعاينتهــا لــم يتضــح‬\n‫مطابقتهــا مــع أي آثــار ألي ســرقة مجهولــة وجرى تســليم األغنام األخرى‬\n‫املضبوطــة لــدى املواطــن ‪ .........‬واملــرأة ‪ .........‬واملواطــن ‪ .........‬واملواطــن‬\n‫‪ .........‬واملواطــن ‪ .........‬واملواطــن ‪ .........‬للمبلــغ ‪ .........‬كمــا مت العثــور‬\n‫علــى عــدد (‪ )39‬تســعة وثالثــن رأســا مــن األغنــام املســروقة مــن منطقــة‬\n‫اجلــوف لــدى املواطــن ‪ .........‬تعــود للمواطــن ‪ .........‬وأفــاد ‪ .........‬بأنــه قــام‬\n‫بشــرائها مــن املدعــى عليــه ‪ .........‬ومت تســليمها لصاحبهــا بعــد التنســيق‬\n‫مــع شــرطة منطقــة اجلــوف وجــرى فــرز أوراق مســتقلة للمتهمــن الهاربــن‬\n‫والتعميــم عنهــم مبوجــب التعميــم رقــم (‪ ) .........‬يف ‪1432/10/11‬ه ـ وال‬\n‫يــزال البحــث جاريــا عــن الهاربــن وجــرى التعميــم عــن الســيارة نــوع ‪.....‬‬\n‫اللــون ‪ .........‬رقــم اللوحــة (‪ ) .........‬والتــي اســتخدمت يف حتميــل األغنــام‬\n‫املســروقة وال يــزال البحــث جاريــا ومت ضبــط مبلــغ مالــي قــدره مائــة‬\n\n\n                                                                                              ‫‪242‬‬\n\f      ‫وخمســون ألــف ريـ‪ 150000‬ــال وجــدت بحــوزة املدعــو وجــرى التحفــظ‬\n      ‫علــى املبلــغ وبضبــط إفــادة املدعــي ‪ .........‬أفــاد بأنــه ســبق وأن ســرقت‬\n      ‫أغنامــه ولــم يعلــم عــن ذلــك إال حينمــا ســرقت منــه مــرة أخــرى بتاريــخ‬\n      ‫‪1432/9/26‬ه ـ وأفــاد بأنــه بتاريخ ‪1432/9/21‬هـ وقع حادث اصطدام‬\n      ‫عــدد (‪ )3‬ثالثــة رؤوس مــن األغنــام عنــد قطعهــا للطريــق حيــث كان‬\n      ‫يبلــغ عــدد األغنــام أثنــاء احلــادث مائــة وواحــدا وتســعني رأســا وأفــاد بأنــه‬\n      ‫ذهــب إلــى إدارة املــرور وقــام بأخــذ رقــم جــوال املواطــن ‪ .........‬وقــام‬\n      ‫باالتصــال عليــه وســؤاله عــن عدداألغنــام التــي كانــت مــع املدعــى عليــه‬\n      ‫‪ .........‬فأفــاده بــأن عددهــا كثيــر وأثنــاء ذلــك علــم بــأن احلــوش التابــع لــه‬\n      ‫ســرق مرتــن وأفــاد بأنــه لــم يكــن يعلــم عــن الســرقة األولــى بســبب أن‬\n      ‫األغنــام التــي لديــه عددهــا كثيــر وال يســتطيع أن يحصيهــا كمــا أفــاد‬\n      ‫بــأن األغنــام التــي وجــدت بحــوزة املدعــى عليهمــا عليــه الوســم اخلــاص‬\n      ‫بأغنامــه املســروقة (‪ )391‬ثالثمائــة وواحــد ًا وتســعني رأســا كمــا أفــاد‬\n      ‫بــأن عــدد األغنــام التــي قــام باســتالمها (‪ )309‬ثالثمائــة وتســعة وبقــي‬\n      ‫عــدد (‪ )82‬اثنــن وثمانــن رأســا وأفــاد بــأن قيمــة األغنــام التــي لــم‬\n      ‫يســتلمها تقــدر مببلــغ مائــة وثالثة وعشــرين ألف ريـ‪ 123000‬ــال وبضبط‬\n      ‫إفــادة كل مــن املواطــن ‪ .........‬واملــرأة ‪ .........‬واملواطــن ‪ .........‬واملواطــن‬\n      ‫‪ .........‬واملواطــن ‪ .........‬واملواطــن ‪ .........‬أفــادوا بأنهــم قامــوا بشــراء عــدد‬\n      ‫مــن األغنــام مــن ‪ .........‬وبعــرض ‪ .........‬علــى املواطــن ‪ .........‬اســتطاع‬\n      ‫التعــرف عليــه وأفــاد بأنــه هــو مــن قــام ببيعــه األغنــام وحتميلهــا وبعــرض‬\n      ‫‪ .........‬علــى املــرأة ‪ .........‬اســتطاعت التعــرف عليــه وأفــادت بأنــه هــو مــن‬\n      ‫قــام ببيعهــا األغنــام وحتميلهــا وبضبــط شــهادة املواطــن ‪ .........‬أفــاد بأنــه‬\n      ‫كان موجــودا مــع زوجتــه فضيــة أثنــاء قيامهــا بشــراء عــدد مــن األغنــام‬\n\n\n‫‪243‬‬\n\f‫مــن ‪ ....‬وباســتجواب ‪ .........‬أفــاد بأنــه يف يــوم ‪1432/9/21‬ه ـ ورده‬\n‫اتصــال مــن املدعــى عليــه ‪ .........‬وذلــك بعــد اإلفطــار وقــال لــه إنــه يوجــد‬\n‫أغنــام ‪ .........‬كثيــرة يف املزرعــة التــي يعمــل بهــا وطلــب منــه أن يقومــا‬\n‫بســرقتها فأخبــره بأنــه ســوف يــرد عليــه الحقــا ويف حينــه أخبــر كال‬\n‫مــن املقيــم ‪ .........‬واملقيــم ‪ .........‬فوافقــا واتفقــوا علــى ســرقتها وذلــك‬\n‫بعــد التنســيق مــع ‪ .........‬ثــم قــام باالتصــال علــى ‪ .........‬وأخبــره بأنــه ال‬\n‫مانــع لديهــم مــن ســرقة األغنــام واتفقــوا معــه علــى أن يتقابلــوا صبــاح‬\n‫اليــوم التالــي عنــده باملزرعــة التــي يعمــل بهــا والتــي يوجــد بهــا يوجــد‬\n‫بداخلهــا األغنــام املــراد ســرقتها وذهــب صبــاح اليــوم التالــي هــو واملقيــم‬\n‫‪ .........‬بالســيارة ‪ ....‬العائــدة ملكيتهــا لــه علــى طريــق ‪ .........‬وكان‬\n‫‪ .........‬علــى تواصــل معــه بالهاتــف اجلــوال حتــى وصلــوا إليــه بالقــرب مــن‬\n‫املزرعــة وقابلــوه وأرشــدهم إلــى احلــوش املوجــود فيــه األغنــام واتفقــوا‬\n‫علــى أن يحضــروا يف نفــس اليــوم مســاء لســرقتها ثــم رجعــوا إلــى املزرعــة‬\n‫التــي يعمــل بهــا ويســكن فيهــا كل مــن املقيــم ‪ .........‬و‪ .........‬ويف نفــس‬\n‫اليــوم ذهــب هــو ‪ .........‬و‪ .........‬وكان ذلــك بعــد اإلفطــار بســيارته ‪....‬‬\n‫حتــى وصلــوا بالقــرب مــن املزرعــة وأوقفــوا الســيارة وكان ‪ .........‬داخــل‬\n‫املزرعــة إلشــغال العمــال املوجوديــن فيهــا لكــي يتمكنــوا مــن ســرقة‬\n‫األغنــام وكان علــى تواصــل معــه عبــر اجلــوال ثــم ســاروا علــى األقــدام‬\n‫حتــى وصلــوا إلــى حــوش األغنــام وفتحــوا احلــوش وشــاهدوا أعــدادا‬\n‫كثيــرة مــن األغنــام وعنــد ذلــك قامــوا بعــزل مجموعــة كبيــرة مــن‬\n‫األغنــام ال يعــرف كــم عددهــا وقامــوا بالســير بهــا علــى األقــدام حتــى‬\n‫خرجــوا مــن املزرعــة وهــم يســوقونها أمامهــم حتــى وصلــوا إلــى ســيارته‬\n‫‪ .....‬وركــب هــو الســيارة وقــام كل مــن ‪ .........‬و‪ .........‬بالســير باألغنــام‬\n\n\n                                                                                          ‫‪244‬‬\n\f      ‫علــى األقــدام وهــو راكــب الســيارة لكــي يذهبــوا باألغنــام ســيرا إلــى‬\n      ‫املزرعــة التــي يعمــل بهــا يف حــي ‪ .........‬ويســكنان معــه بهــا وكان ذلــك‬\n      ‫تقريبــا عنــد صــاة العشــاء وهــم يســيرون باألغنــام وأثنــاء قطعهــم‬\n      ‫الطريــق بهــا بالقــرب مــن مزرعــة الســيرة اصطدمــت إحــدى الســيارات‬\n      ‫العابــرة للطريــق مبجموعــة مــن األغنــام حيــث مــات مــن الغنــم عــدد (‪)3‬‬\n      ‫ثالثــة رؤوس ونــزل صاحــب الســيارة النتظــار دوريــة أمــن الطــرق وذلــك‬\n      ‫بنــاء علــى طلــب صاحــب الســيارة وبقــي هــو يف موقــع احلــادث وقــال‬\n      ‫لصاحــب الســيارة أنــه هــو املســئول وذهــب رفاقــه الذيــن معــه وســاقوا‬\n      ‫الغنــم وبعــد حوالــي نصــف ســاعة حضــرت دوريــة أمــن الطــرق وأخــذوه‬\n      ‫هــو وصاحــب الســيارة الــذي صــدم الغنــم إلــى املركــز وقــال لهم صاحب‬\n      ‫الســيارة أنــه مؤمــن علــى ســيارته وال يرغــب ســوى محضــر باحلادثــة‬\n      ‫ليتمكــن مــن إصــاح ســيارته وبعدهــا ذهــب وبقــي هــو يف املركــز ألنــه‬\n      ‫طلــب منــه إحضــار كفيــل وقــام باالتصــال علــى أحــد األشــخاص‬\n      ‫املســتأجرين حــوش يف املزرعــة التــي يعمــل بهــا وطلــب منــه احلضــور‬\n      ‫لكفالتــه ثــم ذهــب معــه إليصالــه إلــى املزرعــة التــي يعمــل بهــا حيــث‬\n      ‫تضــم مجموعــة مــن األحــواش املؤجــرة للعديــد مــن األشــخاص ووصــل‬\n      ‫للمزرعــة وكان ذلــك مــع طلــوع الفجــر واتصــل هــو ب‪ .........‬فأخبــره‬\n      ‫بأنهــم بالطريــق باجتاهــه وعنــد الســاعة التاســعة صباحــا تقريبــا وصلــوا‬\n      ‫باألغنــام املســروقة إلــى املزرعــة ســيرا علــى األقــدام وقامــوا بإخفائهــا‬\n      ‫علــى الفــور بحــوش باملزرعــة كمــا أقــر بأنــه قــام ببيــع عــدد مــن هــذه‬\n      ‫األغنــام عددهــا (‪ )21‬واحــد وعشــرون رأســا لشــخص يدعــى ‪.........‬‬\n      ‫وذلــك مببلــغ تســعمائة وأربعــن ريـ‪ 940‬ــال للــرأس الواحــد وأعطــاه مبلــغ‬\n      ‫ســتة عشــر ألــف وخمســمائة ريـ‪ 16500‬ــال وبقــي عنــده ثالثــة آالف‬\n\n\n‫‪245‬‬\n\f‫وثمامنائــة ريـ‪ 3800‬ــال لــم يســتلمها منــه وال يعلــم املشــتري عــن األغنــام إال‬\n‫أنهــا عائــدة لــه وقــام هــو بتوصيــل األغنــام إلــى مزرعتــه ثــم بــاع عــدد (‪)2‬‬\n‫رأســن مــن األغنــام لشــخص يدعــى ‪ .........‬مببلــغ ثالثــة آالف ريـ‪ 3000‬ــال‬\n‫وبعــد ذلــك أحضــر لــه شــخص يدعــى ‪ .........‬والــذي اشــترى منــه عــدد‬\n‫(‪ )112‬مائــة واثنــي عشــر رأســا مــن األغنــام مببلــغ ثالثــة آالف ومائــة‬\n‫ريـ‪ 3100‬ــال اســتلمها منــه نقــدا وقــام هــو بإيصــال األغنــام إلــى مزرعتــه‬\n‫علــى طريــق ‪ .........‬كمــا قــام ببيــع عــدد (‪ )12‬اثنــي عشــر رأسـاً للمواطــن‬\n‫‪ .........‬وعــدد (‪ )12‬اثنــا عشــر رأســا للمــرأة ‪ .........‬وبــاع أيضــا ل‪.........‬‬\n‫عــدد (‪ )12‬اثنــى عشــر رأســا وقــام أيضــا ببيــع املســتأجر باألحــواش‬\n‫املواطــن ‪ .........‬وأقــر بــأن املبالــغ املاليــة بقيــت بحوزتــه وحتفــظ عليهــا‬\n‫حتــى يتمكــن كل مــن ‪ .........‬و‪ .........‬و‪ .........‬مــن تقاســمها بينهــم‬\n‫الحقــا وبعــد حوالــي أربعــة أو خمســة أيــام اتصــل عليــه ‪ .........‬وقــال لــه‬\n‫نريــد أن نســرق مــرة أخــرى مــن نفــس األغنــام الســابقة وكان وقتهــا‬\n‫يجلــس باملزرعــة التــي يعمــل بهــا وكان موجــودا معــه كل مــن ‪.........‬‬\n‫و‪ .........‬وشــخص آخــر ســوداني يدعــى ‪ .........‬وبقيادتــه ســيارة مــن نــوع‬\n‫‪ .....‬يقــوم بتوصيــل األغنــام وعنــد ذلــك قــال هــو للموجوديــن بــأن ‪.........‬‬\n‫اتصــل عليــه وأخبــره بأنــه يريــد أن يقــوم بالســرقة مــن األغنــام مــرة‬\n‫أخــرى فوافــق املوجــدون معــه مــا عــدا ‪ .........‬الــذي قــال إنــه يريــد قيمــة‬\n‫التوصيــل فقــط وال يريــد مــن الغنــم شــيئا وبعــد اإلفطــار ركــب كل مــن‬\n‫‪ .........‬و‪ .........‬مــع ‪ .........‬بســيارته ‪ .....‬وركــب هــو بســيارته ‪ .....‬واجتهــا‬\n‫إلــى املزرعــة ســيرا علــى األقــدام أمــا هــو ‪ .........‬فجلســا ينتظرانهمــا‬\n‫وأثنــاء ذلــك فتحــوا حــوش األغنــام وســرقوا عــددا مــن األغنــام مــا يقــارب‬\n‫(‪ )129‬مائــة وتســعة وعشــرين وســاروا بهــا علــى األقــدام حتــى أخرجوهــا‬\n\n\n                                                                                           ‫‪246‬‬\n\f      ‫إلــى خــارج املزرعــة وقابلوهمــا وقامــوا بتحميــل األغنــام بال ــ‪ ....‬علــى‬\n      ‫دفعــات إلــى املزرعــة التــي يعمــل بهــا بحــي ‪ .........‬حتــى متكنــوا مــن‬\n      ‫إيصــال كامــل األغنــام وذلــك عنــد طلــوع الفجــر وقامــوا بإخفــاء األغنام‬\n      ‫داخــل املزرعــة بقصــد بيعهــا الحقــا وتقاســم املبالــغ املاليــة بينهــم وأمــا‬\n      ‫املقيــم ‪ .........‬فقــام هــو بإعطائــه مبلــغ ألــف وخمســمائة ريـ‪ 1500‬ــال قيمة‬\n      ‫حتميــل األغنــام ثــم ذهــب إال أنــه بتاريخ ‪1432/10/4‬هـ وحوالي الســاعة‬\n      ‫احلاديــة عشــر ليــا حضــر رجــال األمــن إلــى املزرعــة التــي يعمــل بهــا‬\n      ‫ويســكن معــه بهــا ‪ .........‬و‪ .........‬وقبــض عليــه ومت اصطحابــه إلــى‬\n      ‫مركــز شــرطة ‪ .........‬ويف اليــوم التالــي عثــر علــى األغنــام املســروقة‬\n      ‫داخــل املزرعــة وعنــد ســؤاله عــن األغنــام ذكــر لهــم أن األغنــام تعــود‬\n      ‫ل‪ .........‬واليعلــم عنهــا أي شــيء كمــا أفــاد أنــه أثنــاء القبــض عليه كان‬\n      ‫كل مــن ‪ .........‬و‪ .........‬موجوديــن يف املزرعــة لكنهمــا اختفيــا وال يعلــم‬\n      ‫عنهمــا أي شــيء كمــا أقــر بأنــه هــو وكل مــن ‪ .........‬و‪ .........‬و‪.........‬‬\n      ‫هــم مــن قامــوا بســرقة األغنــام مرتــن مــن املزرعــة الواقعــة علــى طريــق‬\n      ‫‪ .........‬وبتنســيق واتفــاق بينهــم األربعــة كمــا أقــر بأنــه اســتلم مبلــغ مائــة‬\n      ‫وخمســن ألــف ريـ‪ 150000‬ــال وأفــاد بأنهــا موجــودة ويســتطيع الداللــة‬\n      ‫عليهــا وأمــا املبلــغ وقــدره ســتني ألــف ريـ‪ 60000‬ــال فقــام بتحويلــه إلــى‬\n      ‫الســودان علــى دفعــات وأن هــذه املبالــغ هــي محصلــة بيعــه ملجموعــة مــن‬\n      ‫األغنــام املســروقة وأفــاد بأنهــم األربعــة اتفقــوا علــى تقاســم املبلــغ بينهــم‬\n      ‫الحقــا وصــادق علــى إقــراره شــرعا وباســتجواب املدعــى عليــه ‪ .........‬أقــر‬\n      ‫بأنــه بتاريــخ ‪1432/9/12‬ه ـ أخبــره‪ .........‬بأنــه يريــد منــه أن يعمــل يف‬\n      ‫املزرعــة التــي كان يعمــل بهــا ‪ .........‬لكــي يقومــوا بســرقة األغنــام‬\n      ‫املوجــودة هنــاك ويكــون دوره تســهيل عمليــة الدخــول واخلــروج مــن‬\n\n\n‫‪247‬‬\n\f‫املزرعــة واملســاعدة يف الســرقة وبعــد أن عمــل باملزرعــة قــام ‪.........‬‬\n‫باالتصــال عليــه فأخبــره بأنــه ال يعــرف أن يوصــف لــه املزرعــة فقــال لــه‬\n‫‪ .........‬ال بــد أن أعــرف املوقــع وحضــر لــه يف النهــار وكان ينتظــره عنــد‬\n‫عقــم املزرعــة وبعــد ذلــك قــال لــه هــذا هــو احلــوش الــذي يوجــد بــه األغنــام‬\n‫بعــد ذلــك دخــل وبعدهــا بيومــن حضر له كل مــن ‪ .........‬و‪ .........‬و‪.........‬‬\n‫قبــل صــاة العشــاء وقامــوا بأخــذ األغنــام مــن احلــوش وأفــاد بأنــه لــم‬\n‫يقابلهــم ويف الصبــاح اتصــل عليــه ‪ .........‬وأخبــره بأنــه حصــل حــادث‬\n‫أثنــاء ســرقتهم األغنــام علــى طريــق عمــان وقــد مــات (‪ )3‬ثالثــة رؤوس‬\n‫مــن األغنــام وقــد أوقــف وخــرج مــن التوقيــف وبعــد يومــن اتصــل عليــه‬\n‫‪ .........‬وأخبــره بــأن عــدد األغنــام (‪ )200‬مائتــن وقــد بــاع منهــا (‪)100‬‬\n‫مائــة رأس علــى شــخص علــى طريــق ‪ .........‬واملائــة األخــرى باعهــا يف‬\n‫نفــس املزرعــة وبعــد حوالــي خمــس أيــام قــام ‪ .........‬باالتصــال عليــه وقــال‬\n‫لــه دع ‪ .........‬و‪ .........‬و‪ .........‬يأخــذون األغنــام وأنــا ســوف أقابلهــم‬\n‫وحضــر إليــه يف املزرعــة كل مــن ‪ .........‬و‪ .........‬و‪ .........‬وقابلهــم وقامــوا‬\n‫بأخــذ األغنــام يف املــرة الثانيــة وبعــد ذلــك ال يعلــم أي شــيء ويف الصبــاح‬\n‫اكتشــف العمــال املوجــودون يف املزرعــة الســرقة وقــام هــو باالتصــال‬\n‫علــى ‪ .........‬وأخبــره بــأن العمــال اكتشــفوا الســرقة ولــم يتصــل عليــه‬\n‫وبعــد ذلــك مت القبــض عليــه وصــادق علــى إقــراره شــرعا وملــا أشــير إليــه‬\n‫أقــرر توجيــه االتهــام ل‪ .........‬بســرقة ثالثمائــة وواحــد وتســعني رأســا مــن‬\n‫الغنــم وارتــكاب جرميــة غســل األمــوال املجــرم باملــادة الثانيــة مــن‬\n‫مكافحــة غســل األمــوال وذلــك حليازتــه ألمــوال متحصلــة عــن نشــاط‬\n‫إجرامــي وحتويلــه ملبالــغ أخــرى إلــى بلــده مــع علمــه بأنهــا ناجتــه عــن‬\n‫نشــاط إجرامــي وتوجيــه االتهــام ل‪ .........‬مبســاعدته يف جرميــة الســرقة‬\n\n\n                                                                                          ‫‪248‬‬\n\f      ‫بصــرف عمــال املزرعــة التــي ســرقت منهــا األغنــام حتــى متكــن ‪.........‬‬\n      ‫ورفقــاؤه الهاربــون مــن الســرقة وحيــث إن مــا أقــدم عليــه املذكــوران‬\n      ‫فعــل محــرم شــرعا ومجــرم نظامــا ومعاقــب عليــه وهــو قيــام الثانــي‬\n      ‫بســرقة مــال محتــرم مــن حــرزه بالــغ النصــاب ال شــبهة لــه فيــه وهــو‬\n      ‫مكلــف غيــر مكــره وقيامــه بجرميةغســل األمــوال وقيــام األول‬\n      ‫مبســاعدته بجرميــة الســرقة لــذا أطلــب مــا يلــي ‪ -1:‬إثبــات مــا أســند‬\n      ‫إليهمــا ‪ -2‬احلكــم علــى الثانــي بحــد الســرقة الــوارد يف األيــة الكرميــة‬\n      ‫رقــم (‪ )38‬مــن ســورة املائــدة ‪ -3‬احلكــم علــى الثانــي بالعقوبــة املنصــوص‬\n      ‫عليهــا باملــادة السادســة عشــرة مــن نظــام مكافحــة غســل األمــوال ‪-4‬‬\n      ‫احلكــم علــى األول بعقوبــة تعزيريــة تردعــه وتزجــر غيــره (علمــا بــأن‬\n      ‫احلــق اخلــاص ال زال قائمــا) هــذه دعــواي وبعــرض دعــوى املدعــي العــام‬\n      ‫علــى املدعــى عليــه األول ‪ .........‬أجــاب قائــا مــا جــاء يف دعــوى املدعــي‬\n      ‫العــام وإقــرار املدعــى عليــه الثانــي ‪ .........‬وإقــراري علــى نفســي كلــه‬\n      ‫غيــر صحيــح وال أعلــم عــن هــذه القضيــة شــيئا ولــم أســاعد املدعــى عليــه‬\n      ‫الثانــي ‪ .........‬لســرقة األغنــام املوجــودة يف مزرعــة ‪ .........‬أبــدا هــذه‬\n      ‫إجابتــي وجــرى ســؤاله هــل بينــك وبــن املدعــى عليــه الثانــي ‪ .........‬ســابق‬\n      ‫معرفــة فأجــاب قائــا نعــم إننــي أعــرف املدعى عليه الثانــي ‪ .........‬معرفة‬\n      ‫تامــة واملزرعــة التــي يعمــل بهــا قريبــة مــن املزرعــة التــي أعمــل بهــا وتبعــد‬\n      ‫عنــا قرابــة أربعــة كيلــو متــرات تقريبــا هكــذا أجــاب وأضــاف املدعــى‬\n      ‫عليــه األول ‪ .........‬قائــا إن صــدق برائتــي أنــه ملــا مت القبــض علــي لــم‬\n      ‫يجــدوا عنــدي مــاال وال أســلحة وهــذا دليــل برائتــي هكــذا أضــاف‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه الثانــي ‪ .........‬أجــاب‬\n      ‫قائــا مــا جــاء يف دعــوى املدعــي العــام غيــر صحيــح والصحيــح أننــي‬\n\n\n‫‪249‬‬\n\f‫أعمــل يف مزرعــة كفيلــي املدعــو ‪ .........‬وهــي مزرعــة كبيــرة ومقســمة‬\n‫إلــى عــدة أحــواش وأقــوم بتأجيــر األحــواش علــى األشــخاص حلفــظ‬\n‫أغنامهــم بهــا ويف شــهر رمضــان عــام ‪1432‬ه ـ ال أذكــر تاريــخ اليــوم أتــى‬\n‫إلــي املدعــو ‪ .........‬واملدعــو ‪ .........‬ومعهمــا عــدد مــن األغنــام وعددهــا‬\n‫مائــة وواحــد وثمانــون رأســا يســوقونها مشــيا وطلبــا منــي بيعهــا علــى‬\n‫املســتأجرين لألحــواش املوجــودة داخــل املزرعــة وعلــى غيرهــم مــن خارج‬\n‫املزرعــة فوافقــت علــى ذلــك فبعــت مائــة وواحــد وســبعون رأســا علــى‬\n‫عــدة أشــخاص وهــم املذكوريــن يف الدعــوى وبقــي عشــرة مــن األغنــام‬\n‫موجــودة يف احلــوش لــم أبعهــا علمــا بأنــه قــد اتصــل علــي املدعــو ‪.........‬‬\n‫و‪ .........‬قبــل أن يأتيــا إلــي يف املزرعــة وأخبرانــي بــأن شــخصا قــد صــدم‬\n‫ثالثــة رؤوس مــن األغنــام وطلبــا منــي أن أكــون أنــا املســؤول عــن هــذه‬\n‫األغنــام لكونهمــا ال ميلــكان رخصــة إقامــة وفعال حضــرت إلى صاحب‬\n‫الســيارة وأخبرتــه بأننــي أنــا صاحــب هــذه األغنــام ومت القبــض علــي‬\n‫وإيداعــي يف التوقيــف حتــى خرجــت منــه بكفالــة وملــا وصلــت إلــى‬\n‫املزرعــة وصــا املدعــو ‪ .........‬و‪ .........‬ومعهــم األغنــام املذكــورة‬\n‫يســوقونها مشــيا وطلبــا منــي مــا ذكرتــه آنفــا وبعــد يومــن قدمــا إلــي‬\n‫مــرة أخــرى املدعــو ‪ .........‬و‪ .....‬ومعهــم ســيارة مــن نــوع (‪ )......‬يقودهــا‬\n‫شــخص اســمه (‪ ) .........‬وطلبا مني إعطائه مبلغ وقدره ألف وخمســمائة‬\n‫ريـ‪ 1500‬ــال قيمــة التوصيــل فأعطيتــه وأنــزال األغنــام عنــدي يف احلــوش‬\n‫ولــم أقــم ببيعهــا حتــى مت القبــض علــي وأخبــرت بــأن هــذه األغنــام‬\n‫مســروقة وهربــا املدعــو ‪ .........‬و‪ .........‬ولــم يعلــم عــن مكانهمــا حتــى‬\n‫تاريخــه هــذا الــذي حصــل معــي ومــا ذكــره املدعــى عليــه األول ‪.........‬‬\n‫مــن إقــراره ضــدي ومــا أقررتــه عــن نفســي غيــر مــا ذكرتــه آنفــا فغيــر‬\n\n\n                                                                                      ‫‪250‬‬\n\f      ‫صحيــح واهلل يعلــم بأننــي ال أعلــم أن هــذه األغنــام مســروقة هذه إجابتي‬\n      ‫وجــرى ســؤاله بكــم بعــت الــرأس الواحــد مــن األغنــام علــى األشــخاص‬\n      ‫املذكوريــن فأجــاب قائــا بعتــه مببلــغ وقــدره تســعمائة وأربعــون‬\n      ‫ريـ‪ 940‬ــال ومببلغ وقدره تسعمائة وخمسون ريـ‪ 950‬ــال ال يتجاوز هاذين‬\n      ‫الســعرين هكــذا أجــاب وقــرر املدعــى عليــه الثانــي ‪ .........‬قائــا مــا‬\n      ‫ذكرتــه عــن نفســي أننــي قمــت بتهريــب مبلــغ وقــدره ســتون ألــف‬\n      ‫ريـ‪ 60000‬ــال إلــى الســودان فغيــر صحيــح وذكــرت ذلــك للشــرطة خوف‬\n      ‫علــى املبلــغ احملفــوظ وقــدره مائــة وخمســون ألــف ريـ‪ 150000‬ــال خســية‬\n      ‫مطالبــة أصحــاب األغنــام املســروقة ألغنامهــم ولكــن يف نهايــة األمــر‬\n      ‫اعترفــت بــأن املبلــغ موجــود ولــم أرســل شــيئا منــه إلــى الســودان هكــذا‬\n      ‫قــرر وبســؤال املدعــي العــام عــن بينتــه علــى طبــق دعــواه أجــاب قائــا‬\n      ‫بينتــي ســأحضرها يف اجللســة القادمــة هكــذا أجــاب ويف جلســة أخــرى‬\n      ‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليهمــا وبســؤال املدعــي‬\n      ‫العــام عــن بينتــه التــي وعــد بإحضارهــا يف هــذه اجللســة فأجــاب قائــا‬\n      ‫بينتــي هــي مايلــي‪ -1 :‬اعترافهمــا املصدق شــرعا املــدون على الصفحات‬\n      ‫رقــم (‪ )7 - 3‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )53‬والصفحــات رقــم‬\n      ‫(‪ )6-5‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ -2 )56‬مــا جــاء بإفــادة‬\n      ‫املواطــن ‪ .........‬املدونــة علــى الصفحــة رقــم (‪ )3‬مــن دفتــر التحقيــق املرفق‬\n      ‫لفــة رقــم (‪ -3 )52‬مــا جــاء بإفــادة املواطنــة ‪ .........‬املدونــة علــى الصفحــة‬\n      ‫رقــم (‪ )8‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ -4 )52‬مــا جــاء بشــهادة‬\n      ‫املواطــن ‪ .........‬املدونــة علــى الصفحــة رقــم (‪ )10‬مــن دفتــر التحقيــق‬\n      ‫املرفــق لفــة رقــم (‪ -5 )52‬مــا جــاء بإفــادة املواطــن ‪ .........‬املدونــة علــى‬\n      ‫الصفحــة رقــم (‪ )12-11‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪-6 )52‬‬\n\n\n‫‪251‬‬\n\f‫مــا جــاء بإفــادة املواطــن ‪ .........‬املدونــة علــى الصفحــة رقــم (‪ )16-15‬مــن‬\n‫دفتــر التحقيــق املرفــق لفــة رقــم (‪ -7 )52‬مــا جــاء بإفــادة املواطــن ‪.........‬‬\n‫املدونــة علــى الصفحــة رقــم (‪ )15‬مــن دفتــر التحقيــق املرفــق لفــة رقــم‬\n‫(‪ -8 )53‬مــا جــاء بإفــادة املواطــن ‪ .........‬املــدون علــى الصفحــة رقــم (‪-13‬‬\n‫‪ )14‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ -9 )53‬محضــر داللــة املتهــم‬\n‫صــاح علــى املبلــغ املالــي املــدون علىالصفحــة رقم (‪ )8‬مــن دفتر التحقيق‬\n‫املرفــق لفــة رقــم (‪ -10 )53‬محضــر داللــة املتهــم ‪ .........‬علــى األغنــام‬\n‫املســروقة املــدون علــى الصفحــة رقــم (‪ )10‬مــن دفتــر التحقيــق املرفــق‬\n‫لفــة رقــم (‪ -11 )50‬مــا جــاء مبحضــر العــرض والتعــرف علــى املواطــن‬\n‫‪ .........‬املدونــة علــى الصفحــة رقــم (‪ )4‬مــن دفتــر التحقيــق املرفــق لفــة‬\n‫رقــم (‪ -12 )52‬مــا جــاء مبحضــر العــرض والتعــرف علــى املواطنــة ‪.........‬‬\n‫املدونــة علــى الصفحــة رقــم (‪ )9‬مــن دفتــر التحقيــق املرفــق لفــة رقم (‪)52‬‬\n‫هــذه بينتــي وجــرى منــا االطــاع علــى الدليــل األول مــن أدلــة املدعــي‬\n‫العــام وهــو اإلقــرار املصــدق شــرعا للمدعــى عليــه الثانــي ‪ .........‬املــدون‬\n‫علــى الصفحــة رقــم (‪ )7 - 3‬مــن ملــف التحقيــق رقــم (‪ )53‬ونصــه ( إقــرار‬\n‫واعتــراف بتاريــخ ‪1432/10/10‬ه ـ أقــر أنــا املدعــو ‪ .........‬ســوداني‬\n‫اجلنســية مبوجــب اإلقامــة رقــم (‪ ) .........‬مصدرهــا تبــوك أقــر وأعتــرف‬\n‫وبطوعــي واختيــاري غيــر مكــره أو مجبــر مــن أحــد إنــه يف يــوم الواحــد‬\n‫والعشــرين مــن رمضــان املاضــي تقريبــا وردنــي اتصــال مــن املدعــو ‪.........‬‬\n‫ســوداني اجلنســية وذلــك بعــد اإلفطــار وقــال لــي إنــه يوجــد أغنــام نعيمــي‬\n‫كثيــرة يف املزرعــة التــي يعمــل بهــا وطلــب منــي أن نقــوم بســرقتها وقلــت‬\n‫لــه ســوف أرد عليــك الحقــا ويف حينــه قلــت لــكل مــن املدعــو ‪.........‬‬\n‫واملدعــو‪ .........‬فوافــق اجلميــع واتفقنــا معــه أن نتقابــل صبــاح اليــوم التالي‬\n\n\n                                                                                        ‫‪252‬‬\n\f      ‫ليدلنــا باملزرعــة التــي يعمــل بهــا وبداخلهــا األغنــام التــي نريــد ســرقتها‬\n      ‫وبالفعــل ذهبــت صبــاح اليــوم التالــي أنــا واملدعــو ‪ .........‬بالســيارة ‪....‬‬\n      ‫العائــدة ملكيتهــا لــي علــى طريــق ‪ .........‬وكان ‪ .........‬علــى تواصــل‬\n      ‫معــي بالهاتــف اجلــوال حتــى وصلنــا إليــه بالقــرب مــن مزرعــة وقابلنــاه‬\n      ‫وأرشــدنا إلــى احلــوش املوجــودة فيــه األغنــام واتفقنــا أن نحضــر يف نفــس‬\n      ‫اليــوم مســاء لســرقتها ثــم رجعــت إلــى املزرعــة التــي أعمــل بهــا ويســكن‬\n      ‫فيهــا كل مــن املدعــو ‪ .........‬واملدعــو ‪ .........‬وهــم بــدون إقامــة ويف نفــس‬\n      ‫اليــوم ذهبــت أنــا واملدعــو ‪ .........‬واملدعــو ‪ .........‬وكان ذلــك بعــد اإلفطار‬\n      ‫بســيارتي ‪ .....‬حتــى وصلنــا إلــى القــرب مــن املزرعــة وأوقفنــا الســيارة‬\n      ‫وكان ‪ .........‬داخــل املزرعــة إلشــغال العمــال املوجوديــن لكــي نتمكــن‬\n      ‫مــن ســرقة األغنــام وكان علــى تواصــل معــي عبــر اجلــوال ثــم مشــينا‬\n      ‫علــى األقــدام حتــى وصلنــا إلــى حــوش األغنــام وفتحنــا احلــوش وشــاهدنا‬\n      ‫أعــداد كثيــرة مــن األغنــام وعنــد ذلــك عزلنــا مجموعــة كبيــرة مــن‬\n      ‫األغنــام ال أعــرف عددهــا وقمنــا بالســير بهــا علــى األقــدام حتــى خرجنــا‬\n      ‫مــن املزرعــة ونحــن نســوق األغنــام أمامنــا ووصلنــا إلــى ســيارتي ‪.....‬‬\n      ‫وركبــت أنــا الســيارة وكل مــن املدعــو ‪ .........‬واملدعــو‪ .........‬يســيرون‬\n      ‫بالغنــم علــى األقــدام وأنــا راكــب الســيارة لكــي نذهــب بالغنــم ســيرا‬\n      ‫إلــى املزرعــة التــي أعمــل بهــا يف حــي ‪ .........‬ويســكن معــي بهــا كال مــن‬\n      ‫املدعــو ‪ .........‬واملدعــو ‪ .........‬وكان ذلــك تقريبــا عنــد صــاة العشــاء‬\n      ‫ونحــن نســير بالغنــم ونريــد قطعهــا للطريــق وذلــك بالقــرب مــن مزرعــة‬\n      ‫الســيرة اصطدمــت إحــدى الســيارات العابــرة للطريــق مبجموعــة مــن‬\n      ‫الغنــم حيــث مــات مــن الغنــم عــدد ثالثــة رؤوس ونــزل صاحــب الســيارة‬\n      ‫ونظــرا لكــون كل مــن املدعــو ‪ .........‬واملدعــو ‪ .........‬بــدون إثبــات قلــت‬\n\n\n‫‪253‬‬\n\f‫لهــم واصلــوا الســير بالغنــم وأنــا ســأبقى مــع صاحــب الســيارة النتظــار‬\n‫دوريــة أمــن الطــرق وذلــك بنــاء علــى طلــب صاحــب الســيارة بحضــور‬\n‫الدوريــة للحــادث وبقيــت أنــا يف موقــع احلــادث وقلــت لصاحــب الســيارة‬\n‫أنــا املســؤول وبالفعــل ذهــب رفاقــي الذيــن معــي وســاقوا الغنــم وبعــد‬\n‫حوالــي نصــف ســاعة حضــرت دوريــة أمــن الطرق وأخذونــي أنا وصاحب‬\n‫الســيارة الــذي صــدم الغنــم إلــى املركــز وقــال لهــم صاحــب الســيارة أنــه‬\n‫مؤمــن علــى ســيارته وال يرغــب ســوى محضــر باحلادثــة ليتمكــن مــن‬\n‫إصــاح ســيارته وبعدهــا ذهــب وبقيــت يف املركــز ألنــه طلــب علــي‬\n‫إحضــار كفيــل وبالفعــل اتصلــت بأحــد األشــخاص املســتأجرين حــوش‬\n‫يف املزرعــة التــي أعمــل بهــا وطلبــت منــه احلضــور لكفالتــي وهــو يدعــى‬\n‫‪ .........‬يعمــل عســكري بالقاعــدة وال يعلــم أي شــيء عمــا حــدث ولكــن‬\n‫طلبــت منــه املســاعدة وكفلنــي ثــم ذهبــت معــه إليصالــي إلــى املزرعــة‬\n‫التــي أعمــل بهــا حيــث أنهــا تضــم مجموعــة مــن األحواش املؤجــرة للعديد‬\n‫مــن األشــخاص ووصلــت للمزرعــة وكان ذلــك مع طلــوع الفجر واتصلت‬\n‫ب‪ .........‬وقــال لــي أنهــم بالطريــق باجتاهــي وبالفعــل عنــد الســاعة‬\n‫التاســعة صباحــا تقريبــا وصلــوا بالغنــم املســروقة إلــى املزرعــة ســيرا‬\n‫باألقــدام وقمنــا بإخفاءهــا علــى الفــور بحــوش باملزرعــة وأقــر بأنــي بعــت‬\n‫مــن هــذه األغنــام عــدد واحــد وعشــرين رأســا لشــخص يدعــى ‪.........‬‬\n‫وذلــك مببلــغ تســعمائة وأربعــن ريـ‪ 940‬ــال للــرأس الواحــد وأعطانــي‬\n‫مبلــغ ســتة عشــر ألفــا وخمســمائة ريـ‪ 16500‬ــال وبقــي لــي عنــده ثالثــة‬\n‫آالف وثمامنائــة ريـ‪ 3800‬ــال لــم أســتلمها منــه وال يعلــم املشــتري عــن‬\n‫األغنــام إال أنهــا عائــدة لــي وأنــا أوصلــت األغنــام إلــى مزرعتــه ثــم بعــت‬\n‫عــدد خروفــن لشــخص يدعــى ‪ .........‬مببلــغ ثالثــة آالف ريـ‪ 3000‬ــال‬\n\n\n                                                                                       ‫‪254‬‬\n\f      ‫وبعــد ذلــك حضــر لــي شــخص يدعــى ‪ .........‬والــذي اشــترى منــي عــدد‬\n      ‫مائة واثنا عشر رأسا من األغنام مببلغ مائة وثالثة آالف ريـ‪103000‬ـال‬\n      ‫اســتلمتها نقــدا منــه وقمــت بإيصــال األغنــام إلــى مزرعتــه علــى طريــق‬\n      ‫‪ .........‬وبعــت أيضــا مــن األغنــام املســروقة عــدد اثنــا عشــر رأســا للمدعــو‬\n      ‫‪ .........‬وعــدد اثنــا عشــر رأســا للمــرأة ‪ .........‬وبــاع املدعــو ‪ .........‬عــدد اثنــا‬\n      ‫عشــر رأســا ملســتأجر باألحــواش أيضــا يدعــى ‪ .........‬وأقــر بــأن املبالــغ‬\n      ‫املاليــة بقيــت بحوزتــي وحتفظــت عليهــا حتــى نتمكــن الحقــا نحــن‬\n      ‫األربعــة املدعــو ‪ .........‬واملدعــو ‪ .........‬واملدعــو ‪ .....‬وأنــا مــن تقاســمها‬\n      ‫الحقــا وبعــد حوالــي أربعــة أو خمســة أيــام اتصــل علي املدعــو ‪ .........‬وقال‬\n      ‫لــي أن نســرق مــن الغنــم مــرة أخــرى مــن نفــس الغنــم الســابقة وكنــت‬\n      ‫وقتهــا أجلــس باملزرعــة التــي أعمــل بهــا وكان متواجــدا معــي كل مــن‬\n      ‫املدعــو ‪ .........‬واملدعــو ‪ .........‬وشــخص آخــر ســوداني يدعــى ‪ .........‬ال‬\n      ‫أعــرف بقيــة اســمه ولكــن بقيادتــه ســيارة نــوع ‪ ....‬يقــوم بتوصيــل األغنام‬\n      ‫بهــا وعنــد ذلــك قلــت للموجوديــن أن ‪ .........‬اتصــل علــي وقــال لــي أنــه‬\n      ‫يريدنــا أن نســرق مــن الغنــم مــرة أخــرى فوافــق املوجوديــن لــدي مــا عــدا‬\n      ‫‪ .........‬الــذي قــال أنــه يريــد قيمــة التوصيــل فقــط وال يريــد مــن الغنــم‬\n      ‫شــيئا وبعــد اإلفطــار ركــب كل مــن املدعــو ‪ .........‬واملدعــو ‪ .........‬مــع‬\n      ‫‪ .........‬بســيارته ‪ ....‬وأنــا ركبــت ســيارتي ‪ ....‬واجتهنــا إلــى طريــق ‪.........‬‬\n      ‫للمزرعــة التــي ســبق وســرقنا منهــا وعنــد وصولنــا بالقــرب مــن املزرعــة‬\n      ‫كان ‪ .........‬متواجــدا باملزرعــة ينســق معــي عبــر اجلــوال بإشــغال عمــال‬\n      ‫املزرعــة وعنــد وصولنــا بالقــرب مــن املزرعــة نــزل كل مــن املدعــو ‪.........‬‬\n      ‫واملدعــو ‪ .........‬واجتهــوا إلــى املزرعــة ســيرا علــى األقــدام وأنــا واملدعــو‬\n      ‫‪ .........‬بانتظارهــم وبالفعــل فتحــوا حــوش األغنــام وســرقوا عــدد مــن‬\n\n\n‫‪255‬‬\n\f‫األغنــام مــا يقــارب مائــة وتســعة وعشــرين وســاروا بهــا علــى األقــدام حتى‬\n‫أخرجوهــا إلــى خــارج املزرعــة وقابلونــا أنــا واملدعــو ‪ .........‬وقمنــا بتحميل‬\n‫األغنــام بالــ‪ ....‬علــى دفعــات إلــى املزرعــة التــي أعمــل بهــا إلــى حــي ‪.........‬‬\n‫حتــى متكنــا مــن إيصــال كامــل األغنــام وذلــك عنــد طلــوع الفجــر وقمنــا‬\n‫بإخفــاء الغنــم داخــل املزرعــة بقصــد بيعهــا الحقــا وتقاســم املبالــغ املاليــة‬\n‫بيننــا نحــن األربعــة أنــا واملدعــو ‪ .........‬واملدعــو ‪ .........‬واملدعــو ‪ .........‬أمــا‬\n‫املدعــو ‪ .........‬فأعطيتــه مبلــغ ألــف وخمســمائة ريـ‪ 1500‬ــال قيمــة توصيل‬\n‫الغنــم ثــم ذهــب إال أنــه بتاريــخ ‪1432/10/4‬ه ـ وحوالــي الســاعة احلاديــة‬\n‫عشــرة ليــا حضــر رجــال أمــن إلــى املزرعــة التــي أعمــل بهــا ويســكن‬\n‫معــي بهــا املدعــو ‪ .........‬واملدعــو ‪ .........‬وقبــض علــي ومــن ثــم اصطحابــي‬\n‫إلــى مركــز شــرطة ‪ .........‬ويف اليــوم التالــي عثــر علــى األغنــام املســروقة‬\n‫داخــل املزرعــة وعنــد ســؤالي عــن األغنــام ذكــرت لهــم أن األغنــام تعــود‬\n‫للمدعــو ‪ .........‬وال أعلــم عنهــا أي شــيء علمــا أنــه أثنــاء القبــض علــي‬\n‫كان كل مــن املدعــو ‪ .........‬واملدعــو ‪ .........‬متواجديــن يف املزرعــة‬\n‫لكنهــم اختفــوا وال أعلــم عنهــم أي شــيء وأقــر وأعتــرف بأنــي أنــا وكل‬\n‫مــن املدعــو ‪ .........‬واملدعــو‪ .........‬واملدعــو ‪ .........‬بأننــا قمنــا بســرقة‬\n‫األغنــام مرتــن مــن املزرعــة الواقعــة علــى طريــق ‪ .........‬وبتنســيق واتفــاق‬\n‫بيننــا نحــن األربعــة وأقــر بأنــي اســتلمت مبلــغ مائــة وخمســن ألــف‬\n‫ريـ‪ 150000‬ــال وموجــودة وأســتطيع التدليــل عليهــا أمــا مبلــغ حوالــي‬\n‫ســتني ألــف ريـ‪ 60000‬ــال فقمــت بتحويلــه إلــى الســودان علــى دفعــات وأن‬\n‫هــذه املبالــغ هــي محصلــة بيعــي ملجموعــة مــن األغنــام املســروقة وكنــا‬\n‫نحــن األربعــة علــى اتفــاق لتقاســمها بيننــا الحقــا وعلــى إقــراري هــذا‬\n‫جــرى التوقيــع) أ‪.‬ه ـ املقــر مبــا فيــه ‪ .........‬بصمتــه كمــا جــرى منــا‬\n\n\n                                                                                                  ‫‪256‬‬\n\f      ‫االطــاع علــى اإلقــرار املصــدق شــرعا للمدعــى عليــه األول‪ .........‬املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )6-5‬مــن ملــف التحقيــق رقــم (‪ )56‬ونصــه ( أقــر‬\n      ‫أنــا املدعــو ‪ .........‬رقــم اإلقامــة (‪ ) .........‬مــكان اإلصــدار تبــوك ســوداني‬\n      ‫اجلنســية أقــرر بطوعــي واختيــاري وبــدون إكــراه أو إجبــار مــن أحــد إنــه‬\n      ‫يف يــوم ‪1432/9/12‬ه ـ قــال لــي املدعــو ‪ .........‬أريــدك أن تعمــل يف‬\n      ‫املزرعــة التــي كان يعمــل بهــا املدعــو ‪ .........‬لكــي نقــوم بســرقة األغنــام‬\n      ‫املوجــودة هنــاك ويكــون دورك أن تســهل لنــا عمليــة الدخــول واخلــروج‬\n      ‫مــن املزرعــة وتســاعدنا يف الســرقة قــام املدعــو ‪ .........‬بعــد أن عملــت يف‬\n      ‫املزرعــة باالتصــال علــي قلــت لــه إنــي ال أعــرف أن أوصــف لــك املزرعــة‬\n      ‫قــال لــي‪ .........‬أنــا أعــرف املوقــع ومرنــي يف النهــار وكان ينتظرنــي عنــد‬\n      ‫عقــم املزرعــة بعــد ذلــك قلــت لــه هــذا هــو احلــوش الــذي يوجــد بــه األغنــام‬\n      ‫بعــد ذلــك ذهــب وبعــد ذلــك بيومــن حضــر لنــا كال مــن ‪ .........‬و‪.........‬‬\n      ‫وطلعــت قبــل صــاة العشــاء وقامــا بأخــذ األغنــام مــن احلــوش علمــا بأننــي‬\n      ‫لــم أقابلهــم ويف الصبــاح اتصــل علــي ‪ .........‬وقــال أنــه حصــل حــادث أثنــاء‬\n      ‫ســرقت األغنــام علــى طريــق عمــان وقــد مــات ثــاث رؤوس مــن األغنــام‬\n      ‫وقــد توقفــت وطلعــت مــن التوقيــف وبعــد يومــن اتصــل علــي ‪ .........‬وقــال‬\n      ‫أن عــدد األغنــام ‪ 200‬وقــد بعــت مائــة منــه علــى شــخص علــى طريــق‬\n      ‫املدينــة واملائــة األخــرى بعتهــا يف نفــس املزرعــة وبعــد حوالــي خمســة أيــام‬\n      ‫حضــر لــي يف املزرعــة كال مــن ‪ .........‬و‪ .........‬و‪ .........‬وقــد قــام ‪.........‬‬\n      ‫باالتصــال علــي وقــال لــي دع ‪ .........‬و‪ .........‬و‪ .........‬يأخــذون األغنــام‬\n      ‫وأنــا ســوف أقابلهــم وقــد كنــت متواجــدا عنــد احلــوش عندمــا قــام كال‬\n      ‫مــن ‪ .........‬و‪ .........‬و‪ .........‬بأخــذ األغنــام يف املــرة الثانيــة وبعــد ذلــك ال‬\n      ‫أعلــم أي شــيء ويف الصبــاح اكتشــف العمــال املوجوديــن يف املزرعــة‬\n\n\n‫‪257‬‬\n\f‫الســرقة وقــد قمــت باالتصــال علــى ‪ .........‬وقلــت لــه أن العمال اكتشــفوا‬\n‫الســرقة بعــد ذلــك لــم اتصــل عليــه وبعــد ذلــك قبــض علينــا وهــذا كل‬\n‫ماحصــل وعلــى ذلــك أوقــع ) أ‪.‬ه ـ املقــر مبــا فيــه ‪ .........‬بصمتــه وجــرى منا‬\n‫االطــاع علــى الدليــل الثانــي مــن أدلــة املدعــي العــام وهــي إفــادة املواطــن‬\n‫‪ .........‬املدونــة علــى الصفحــة رقــم (‪ )3‬لفــة رقــم (‪ )52‬ونصهــا (أعطنــي‬\n‫املعلومات اإلحصائية عن نفســك؟ االســم ‪ ......... .........‬ســعودي اجلنســية‬\n‫مبوجــب رقــم الســجل (‪ ) .........‬جهــة اإلصــدار تبــوك الســكن ‪.........‬‬\n‫املهنــة ‪ .........‬رقــم اجلــوال (‪ ) .........‬مــا هــي إخباريتــك بالتفصيــل؟‬\n‫أفيدكــم بأنــه وجــدت املدعــو ‪ .........‬يقومــون بســلخ نعجــة وأفــاد املدعــو‬\n‫‪ .........‬بــأن النعجــة تعرضــت للدعــس علــى طريــق ‪ .........‬وقــال ‪ .........‬بأنــه‬\n‫يوجــد لديــه حــال للبيــع وحضــرت يف الصبــاح وقمــت بشــراء خمــس‬\n‫نعــاج وخمــس رخــال وخرفــان وذلــك يــوم الثالثــاء ‪1432/9/23‬ه ـ علمــا‬\n‫بأنــي عنــد قيامــي بشــراء احلــال مــن املدعــو‪ .........‬شــاهدت داخل احلوش‬\n‫حوالــي مائتــن مــن احلــال س‪ /‬هــل تســتطيع التعــرف علــى األشــخاص‬\n‫الذيــن قامــوا ببيعــك وحتميــل احلــال؟ ج‪ /‬نعــم س‪ /‬أيــن املوقــع الــذي‬\n‫اشــتريت منــه احلــال؟ ج‪ /‬مزرعــة بحــي ‪ .........‬س‪ /‬هــل لديــك شــهود‬\n‫أثنــاء قيامــك بالشــراء؟ ج‪ /‬ال س‪ /‬هــل لديــك أقــوال أخــرى؟ ج‪ /‬ال س‪/‬‬\n‫هــل تصــادق علــى أقوالــك؟ ج‪ /‬نعم)أ‪.‬ه ـ املقــر مبــا فيــه ‪ .........‬توقيعــه‬\n‫وجــرى منــا االطــاع علــى الدليــل الثالــث مــن أدلــة املدعــي العــام وهــي‬\n‫إفــادة املواطنــة ‪ .........‬املدونــة علــى الصفحــة رقــم (‪ )8‬لفــة رقــم (‪)52‬‬\n‫ونصها(مــا هــي معلوماتــك اإلحصائيــة؟ االســم ‪ .........‬الســكن الدخــل‬\n‫غــرب ‪ .........‬رقــم اجلــوال (‪ ) .........‬مــا هــي تفاصيــل إخباريتــك؟ يف أواخــر‬\n‫رمضــان قــام املدعــو‪ .........‬ســوداني اجلنســية بعــرض مجموعــة مــن‬\n\n\n                                                                                          ‫‪258‬‬\n\f      ‫األغنــام علــي للبيــع وأفــاد بــأن احلــال تعــود ملكيتــه للمدعــو ‪.........‬‬\n      ‫وشــركاؤه وقمــت بشــراء عــدد ‪ 12‬رأســا مــن اخلرفــان مببلــغ وقــدره‬\n      ‫عشــرة آالف وثمامنائــة ريـ‪ 10800‬ــال وقــام ‪ .........‬واملدعــو‪ .........‬بتحميــل‬\n      ‫احلــال وإحضــاره إلــى احلــوش التابــع لــي س‪ /‬هــل تســتطيعني التعــرف‬\n      ‫علــى األشــخاص الذيــن قامــوا ببيــع احلــال وحتميلــه؟ نعــم س‪ /‬أيــن‬\n      ‫املوقــع الــذي اشــتريتي منــه احلــال؟ مزرعــة بحــي ‪ .........‬س‪ /‬هــل لديــك‬\n      ‫شــهود أثنــاء قيامــك بالشــراء؟ نعــم ‪ .........‬س‪/‬هــل لديــك أقــوال أخــرى؟‬\n      ‫ال س‪ /‬هــل تصادقــن علــى أقوالــك؟ نعم)أ‪.‬ه ـ املقــرة مبــا فيــه ‪.........‬‬\n      ‫بصمتهــا بحضــور الــزوج