15‬لفــة رقــم (‪ )53‬ونصهــا(س‪ /‬أعطنــي املعلومــات‬\n      ‫اإلحصائيــة عــن نفســك؟ االســم ‪ .........‬الســكن‪ .........‬احلالــة االجتماعية‬\n      ‫متــزوج رقــم الســجل (‪ ) .........‬مصدرهــا تبــوك رقــم جوالــي (‪ ) .........‬س‪/‬‬\n      ‫مــا هــي إخباريتــك مفصــا؟ أفيدكــم أنــه بتاريــخ ‪1432/9/27‬ه ـ‬\n      ‫اتصلــت علــى املدعــو ‪ .........‬وطلبــت منــه أن يقــوم بالبحــث لــي عــن فحــول‬\n      ‫مــن األغنــام حيــث أفــاد لــي بأنــه ســوف يقــوم لــي بالبحــث عــن الفحــول‬\n      ‫ثــم اتصــل بعــد ذلــك وقــال بأنــه يوجــد لديــه ســبعة فحــول فذهبــت‬\n      ‫واشــتريتي منــه عــدد اثنــن مببلــغ ثالثة أالف ريـ‪ 3000‬ــال وهذا ما حصل‬\n      ‫مفصــا س‪/‬هــل يوجــد شــهود علــى ذلــك؟ ج‪/‬ال حيــث لــم يكــن موجــودا‬\n      ‫إال املدعــو ‪ .........‬س‪/‬هــل لديــك أقــوال أخــرى؟ ج‪/‬ال س‪ /‬هــل تصــادق‬\n      ‫علــى صحــة أقوالــك؟ ج‪ /‬نعم)أ‪.‬ه ـ املقــر مبــا فيــه‪ .........‬توقيعــه وجــرى منا‬\n      ‫االطــاع علــى الدليــل الثامــن مــن أدلــة املدعــي العــام وهــي إفــادة املواطــن‬\n      ‫‪ .........‬املدونــة علــى الصفحــة رقــم (‪ )14-13‬لفــة رقــم (‪ )53‬ونصهــا (س‪/‬‬\n      ‫أعطنــي املعلومــات اإلحصائيــة عــن نفســك؟ االســم ‪ .........‬العمــر (‪)60‬‬\n      ‫عامــا الســكن حــي ‪ .........‬احلالــة املاديــة ميســورة احلالــة االجتماعيــة‬\n      ‫متــزوج رقــم الســجل (‪ ) .........‬مصدرهــا تبــوك جوالــك (‪ ) .........‬س‪/‬‬\n      ‫ماهــي إخباريتــك مفصــا؟ بتاريــخ ‪1432/9/22‬ه ـ اتصلــت بالعامــل‬\n\n\n‫‪261‬‬\n\f‫الســوداني باملزرعــة املجــاورة ملزرعتــي ‪ .........‬الســوداني وأخبرتــه بأنــي‬\n‫أرغــب يف شــراء فحــل خــروف حيــث لديــه يف املزرعــة أحــواش أغنــام‬\n‫وقــال إن شــاء اهلل ســوف ابحــث لــك ويف املســاء أفادنــي بأنــه حصــل علــى‬\n‫فحــل وســعره ألــف وســتمائة وخمســون ريـ‪ 1650‬ــال فقلــت لــه أرســله‬\n‫للمزرعــة ويف يــوم ‪1432/9/24‬ه ـ اتصــل بــي وقــال بــأن لديــه عشــرون‬\n‫نعجــة طيبــة ويريــد أن يبيعهــا بســعر تســعمائة وأربعــون ريـ‪ 940‬ــال‬\n‫فوافقــت علــى الســعر وأحضــر عشــرة يف الصبــاح وعشــرة يف املســاء‬\n‫بســعر إجمالــي ثمانيــة عشــر وثمامنائــة ريـ‪ 18800‬ــال وإجمالــي املبلــغ‬\n‫عشــرون ألفوأربعمائــة وخمســة ريـ‪ 20450‬ــال ومنهــا ســافرت إلــى املدينــة‬\n‫املنــورة حتــى أشــعرني الرائــد ‪ .........‬بــأن األغنــام التــي اشــتريتها مــن‬\n‫الســوداني مســروقة ثــم حضــر األخ ‪ .........‬ومعــه العريــف ‪ .........‬مــن قســم‬\n‫البحــث واخــذو األغنــام س‪ /‬هــل لديــك شــهود؟ العامــل املصــري ‪.........‬‬\n‫س‪/‬هــل لديــك أقــوال أخــرى؟ ج‪/‬ال س‪ /‬هــل تصــادق علــى صحــة مــا‬\n‫تقــول؟ نعم)أ‪.‬ه ـ املقــر مبــا فيــه ‪ .........‬توقيعــه وجــرى منــا االطــاع علــى‬\n‫الدليــل التاســع مــن أدلــة املدعــي العــام وهــو محضــر داللــة املتهــم‪.........‬‬\n‫علــى املبلــغ املالــي املــدون علــى الصفحــة رقــم (‪ )8‬لفــة رقــم (‪ )53‬ونصــه‬\n‫(محضــر انتقــال بتاريــخ ‪1432/10/10‬ه ـ بحضورنــا املوقعــن أدنــاه‬\n‫وبالتاريــخ أعــاه وبنــاء ملــا ذكــره املتهــم بأنــه يوجــد بحوزتــه مبلــغ مالــي‬\n‫وقدره مائة وخمســن ألف ريـ‪ 150000‬ــال وأودعه عند أحد األشــخاص‬\n‫يف املــزارع ومســتعد بإحضــاره وبنــاء عليــه جــرى االنتقــال رفــق املتهــم‬\n‫املذكــور إلــى إحــدى املــزارع الواقعــة بحــي ‪ .........‬والواقعــة يف نهايــة‬\n‫‪ .........‬وبالفعــل قابــل املتهــم الشــخص أمامنــا وطلــب منــه تســليمه األمانــة‬\n‫وقدرهــا مائــة وخمســون ألــف ريـ‪ 150000‬ــال موضوعــة داخــل كيــس‬\n\n\n                                                                                        ‫‪262‬‬\n\f      ‫وقــد مت التأكــد مــن قبلنــا مــن املبلــغ ومت عــده واتضــح أنــه يبلــغ مائــة‬\n      ‫وخمســون ألــف ريـ‪ 150000‬ــال ومت التحفــظ علــى املبلــغ املذكــور‬\n      ‫وبالواقــع نظــم احملضــر وجــرى التوقيــع ) أ‪.‬ه ـ وجــرى منــا االطــاع علــى‬\n      ‫الدليــل العاشــر مــن أدلــة املدعــي العــام وهــو محضــر داللــة املتهــم ‪.........‬‬\n      ‫علــى األغنــام املســروقة املــدون علــى الصفحــة رقــم (‪ )10‬لفــة رقــم (‪)50‬‬\n      ‫ونصهــا (محضــر انتقــال ومعاينــة بتاريــخ ‪1432/10/10‬ه ـ بحضورنــا‬\n      ‫املوقعــن أدنــاه وبالتاريــخ أعــاه وبنــاء علــى مــا ذكــره املتهــم ‪ .........‬مــن‬\n      ‫أنــه يســتطيع التدليــل علــى مــكان األغنــام املســروقة التــي باعهــا‬\n      ‫لشــخص يف مزرعــة علــى طريــق املدينــة والتــي يبلــغ عددهــا مائــة واثنــا‬\n      ‫عشــر نعيمــي كمــا ذكــر املتهــم وباالنتقــال إلــى املوقــع بالتاريــخ أعــاه‬\n      ‫اتضــح أنــه عبــارة عــن مزرعــة تقــع علــى طريــق املدينــة بعــد محطــة ‪.........‬‬\n      ‫طريــق ‪ .........‬ويف مزرعــة تعــود ملكيتهــا للمدعــو ‪ .........‬وبالدخــول إلــى‬\n      ‫املزرعــة اتضــح وجــود حــوش داخــل املزرعــة معــد لألغنــام حيــث وجــد‬\n      ‫ســكن للعمــال واســتراحة لصاحــب املزرعــة وكان موجــود بهــا أثنــاء‬\n      ‫الدخــول إليهــا شــقيق صاحــب املزرعــة ويدعــى ‪ .........‬والــذي أفــاد بــأن‬\n      ‫املزرعــة عائــدة لشــقيقة وهــو غيــر موجــود باملزرعــة وأفــاد بأنــه يوجــد‬\n      ‫عــدد مائــة واثنــا عشــر مــن األغنــام النعيمــي ســبق واشــتراها شــقيقة‬\n      ‫‪ .........‬من شــخص ســوداني ال يعرفهبمبلغ مائة وثالثة آالف وخمســمائة‬\n      ‫ريـ‪ 103500‬ــال وكان برفقتنــا أثنــاء االنتقــال واملعاينــة صاحــب األغنــام‬\n      ‫املســروقة واملبلــغ عنهــا املدعــو ‪ .........‬والــذي اســتطاع التعــرف علــى الغنم‬\n      ‫أثنــاء دخــول حــوش األغنــام وأفــاد بأنهــا مــن أغنامــه املســروقة التــي أبلــغ‬\n      ‫عنهــا ومت يف حينهــا تســليم الغنــم للمبلــغ ومت إبــاغ شــقيق صاحــب‬\n      ‫املزرعــة بإبــاغ صاحــب املزرعــة املدعــو ‪ .........‬مبراجعــة شــعبة التحريات‬\n\n\n‫‪263‬‬\n\f‫والبحــث اجلنائــي وبنــاء للواقــع نظــم هــذا احملضر)أ‪.‬ه ـ وجــرى منــا‬\n‫االطــاع علــى الدليــل احلــادي عشــر مــن أدلــة املدعــي العــام وهــو محضــر‬\n‫العــرض والتعــرف علــى املواطــن ‪ .........‬املــدون علــى الصفحــة رقــم (‪)4‬‬\n‫لفــة رقــم (‪ )52‬ونصــه (مبعرفتــي نحــن املوقعــن أدنــاه جــرى عــرض كل‬\n‫مــن املقيــم ‪ .........‬و ‪ .........‬و‪ .........‬علــى املواطــن ‪ .........‬واســتطاع التعــرف‬\n‫عليهــم بأنهــم مــن قامــوا ببيــع احلــال عليــه وحتميلــه وحفظــا للواقعــة‬\n‫جــرى نظــم هــذا احملضر)أ‪.‬ه ـ ‪ .........‬توقيعــه وجــرى منــا االطــاع علــى‬\n‫الدليــل الثانــي عشــر مــن أدلــة املدعــي العــام وهــو محضــر العــرض‬\n‫والتعــرف علــى املواطنــة‪ .........‬املــدون علــى الصفحــة رقــم (‪ )9‬لفــة رقــم‬\n‫(‪ )52‬ونصــه (مبعرفتــي أنــا املــازم ‪ .........‬ضابــط حتقيــق شــرطة ‪.........‬‬\n‫جــرى عــرض كل مــن املقيــم‪ .........‬و‪ .........‬علــى املواطنــة ‪.........‬‬\n‫واســتطاعت التعــرف عليهــم بأنهــم مــن قامــوا ببيــع احلــال وحتميلــه‬\n‫إليهــا وحفظــا للواقــع جــرى نظــم هــذا احملضــر )أ‪.‬ه ـ ‪ .........‬بصمتهــا‬\n‫بحضــور الــزوج ‪ .........‬وتوقيعــه وبعــرض أدلــة املدعــي العــام علــى املدعــى‬\n‫عليــه األول ‪ .........‬أجــاب قائــا ماجــاء يف الدليــل األول مــن إقــراري‬\n‫املصــدق شــرعا غيــر صحيــح وليــس لــي عالقــة بهــذه القضيــة أبــدا ال مــن‬\n‫قريــب وال مــن بعيــد وهــذا اإلقــرار أخــذ منــي بالقــوة واإلكــراه أمــا بقيــة‬\n‫األدلــة فــا تخصنــي وهــي تخــص املدعــى عليــه الثانــي ‪ .........‬هكــذا‬\n‫أجــاب وجــرى ســؤاله هــل لديــك بينــة علــى أن هــذا اإلقــرار أخــذ منــك‬\n‫بالقــوة واإلكــراه فأجــاب قائــا ال بينــة لــدي هكــذا أجــاب وأضــاف‬\n‫املدعــى عليــه األول ‪ .........‬قائــا إننــي مظلــوم يف هــذه القضيــة وأنــا‬\n‫أعمــل يف حــال املدعــو ‪ .........‬حتــى مت القبــض علــي بتاريــخ‬\n‫‪1432/9/27‬ه ـ ولــم ينقــص مــن احلــال أي شــي هكــذا ذكــر وبعــرض‬\n\n\n                                                                                              ‫‪264‬‬\n\f      ‫أدلــة املدعــي العــام علــى املدعــى عليــه الثانــي ‪ .........‬أجــاب قائــا مــا جــاء‬\n      ‫يف إقــراري بعضــه صحيــح وبعضــه غيــر صحيــح فلــم يــرد لــي اتصــال مــن‬\n      ‫‪ .........‬ولــم يخبرنــي بأنــه توجــد لديــه يف املزرعــة التــي يعمــل فيهــا أغنــام‬\n      ‫كثيــرة ولــم يطلــب منــي أن نقــوم بســرقتها ولــم أطلــب منــه العمــل يف‬\n      ‫مزرعــة ‪ .........‬لكــي يســهل لنــا عمليــة الدخــول للســرقة مــن املزرعــة ولــم‬\n      ‫أقــم باإلتيــان إلــى هــذه املزرعــة أبــدا وال أعلــم عــن موقعهــا وصحيــح أنــه‬\n      ‫وردنــي اتصــال مــن املدعــو عبــد ‪ .........‬يف متــام الســاعة الثالثــة فجــرا يف‬\n      ‫رمضــان ال أعلــم عــن التاريــخ وأخبرنــي بأنــه و‪ .........‬يســوقون أغنامــا‬\n      ‫لهــم وقــد قــام أحــد األشــخاص بصــدم ثالثــة مــن األغنــام وطلــب منــي أن‬\n      ‫آتــي إلــى موقــع احلــادث عنــد مزرعــة ‪ .........‬لكــي أكــون أنــا املســؤول‬\n      ‫عــن هــذه األغنــام وأنهــا عائــده لــي لكــون املدعــو ‪ .........‬و‪ .........‬ال‬\n      ‫يحمــان رخصــة إقامــة فوافقــت علــى ذلــك وقابلــت مــن قــام بصــدم‬\n      ‫األغنــام وأفهمتــه بــأن األغنــام عائــدة لــي فقــال لــي بأنــه لــن يــدع ‪.........‬‬\n      ‫و‪ .........‬يهربــان فقلــت لــه إنهمــا اليحمــان رخصــة إقامــة فقــال إذا‬\n      ‫ســأدعهما لكــي ال أقطــع نصيبهمــا وذهبــت معــه إلــى مركــز الشــرطة‬\n      ‫وكفلنــي أحــد األشــخاص وخرجــت مــن املركــز واتصلــت علــى املدعــو‬\n      ‫‪ .........‬وقــال لــي إنهمــا بالطريــق متجهــن إلــى املزرعــة التــي أعمــل فيهــا‬\n      ‫ووصــا إلــى املزرعــة يف متــام الســاعة التاســعة تقريبــا ومعهمــا األغنــام‬\n      ‫وطلبــا منــي أن أقــوم ببيعهــا لهمــا ألننــي أعــرف كثيــرا مــن األشــخاص‬\n      ‫الذيــن يرغبــون يف شــراء األغنــام فوافقــت علــى ذلــك وأخبرانــي بأنهمــا‬\n      ‫ســيعطياني أجــرة غيــر محــددة بعــد تصريــف هــذه األغنــام فقمــت ببيعها‬\n      ‫علــى األشــخاص املذكوريــن يف إقــراري باملبالــغ املذكــورة وأقــر بأننــي‬\n      ‫احتفظــت مببلــغ وقــدره مائــه وخمســون ألــف ريـ‪ 150000‬ــال عنــد صديق‬\n\n\n‫‪265‬‬\n\f‫لــي أمــا املبلــغ احملــول لدولــة الســودان وقــدره ســتون ألــف ريـ‪ 60000‬ــال‬\n‫فغيــر صحيــح وكذلــك مــا ذكرتــه يف إقــراري مــن أننــا قمنــا بســرقة‬\n‫األغنــام مرتــن فغيــر صحيــح أمــا مــا ذكــره املدعــي العــام مــن إقــرار‬\n‫املدعــى عليــه األول ‪ .........‬ضــدي فغيــر صحيــح وهــو يخصنــي وال يخصه‬\n‫ومــا ذكــره املدعــي العــام يف دليلــه الثانــي مــن إفــادة املدعــو ‪.........‬‬\n‫فصحيحــة وبعتــه اثنــي عشــر رأســا مــن الغنــم قيمــة النعجــة الواحــدة‬\n‫بتســعمائة وخمســن ريـ‪ 950‬ــال والرخلــه الواحــدة بثمامنائــة وخمســن‬\n‫ريـ‪ 850‬ــال واخلروفــن بتســعمائة ريـ‪ 900‬ــال ومــا ذكــره املدعــي العــام يف‬\n‫دليلــه الثالــث مــن إفــادة املــرأة فضيــة فصحيحــة وبعتهــا اثنــا عشــر رأســا‬\n‫مــن الغنــم ســعر الغنمــه الواحــدة تســعمائة وخمســون ريـ‪ 950‬ــال ومــا‬\n‫ذكــره املدعــي العــام يف دليلــه الرابــع من شــهادة زوج املــرأة ‪ .........‬املدعو‬\n‫‪ .........‬فصحيحــة ومــا ذكــره املدعــي العــام يف دليلــه اخلامــس مــن إفــادة‬\n‫املدعــو ‪ .........‬فصحيــح وأنــا بعتــه مائــة واثنــي عشــر رأســا مــن الغنــم‬\n‫ســعر الغنمة الواحدة بتســعمائة وعشــرين ريـ‪ 920‬ــاال وما ذكره املدعي‬\n                                                           ‫العام يف دليله السادس‬\n‫مــن إفــادة املدعــو ‪ .........‬فصحيحــة وأنــا بعتــه اثنــا عشــر رأســا مــن الغنــم‬\n‫وال أعلــم عــن ســعر الغنمــة الواحــدة ألنــي نســيت ذلــك ولكــن ال يتجــاوز‬\n‫ســعر الغنمــة الواحــدة مــن تســعمائة وعشــرين ريـ‪ 920‬ــاال إلــى تســعمائة‬\n‫وخمســن ريـ‪ 950‬ــاال ولكــن أعطانــي مقــدم أربعــة آالف ريـ‪ 4000‬ــال‬\n‫فقــط ومــا ذكــره املدعــي العــام يف دليلــه الســابع مــن إفــادة املدعــو‬\n‫‪ .........‬فصحيحــة وبعتــه فحلــن مببلــغ وقــدره ثالثة آالف ريـ‪ 3000‬ــال وما‬\n‫ذكــره املدعــي العــام يف دليلــه الثامــن مــن إفــادة املدعــو ‪ .........‬فصحيحة‬\n‫وبعتــه فحــا وعشــرون نعجــة ســعر الفحــل بألــف وســتمائة وخمســن‬\n\n\n                                                                                          ‫‪266‬‬\n\f      ‫ريـ‪ 1650‬ــال وســعر النعجــة الواحــدة بتســعمائة وأربعــن ريـ‪ 940‬ــاال‬\n      ‫وأعطانــي مبلــغ وقــدره ســتة عشــر ألفــا وخمســمائة ريـ‪ 16500‬ــاال وبقــي‬\n      ‫يف ذمتــه لــي مبلــغ وقــدره ثالثــة آالف وثمامنائــة ريـ‪ 3800‬ــاال ومــا ذكــره‬\n      ‫املدعــي العــام يف دليلــه التاســع وهــو محضــر الداللــة علــى املبلــغ الــذي‬\n      ‫ســلمته لشــخص أمانــة عنــده وقــدره مائــة وخمســون ألــف ريـ‪ 150000‬ــال‬\n      ‫فصحيــح منهــا مبلــغ وقــدره تســعة آالف ريـ‪ 9000‬ــال عائــدة لــي ومبلــغ‬\n      ‫وقــدره مائــة وواحــد وأربعــون ألــف ريـ‪ 141000‬ــال قيمــة هــذه األغنــام‬\n      ‫املذكــورة ومــا ذكــره املدعــي العــام يف دليلــه العاشــر مــن أننــي قمــت‬\n      ‫بالداللــة علــى األغنــام املذكــورة فصحيــح وتفاجــأت أن هــذه األغنــام‬\n      ‫مســروقة ومــا ذكــره املدعــي العــام يف دليلــه احلــادي عشــر مــن محضــر‬\n      ‫العــرض والتعــرف علــي مــن قبــل املواطــن ‪ .........‬فصحيــح ومــا ذكــره‬\n      ‫املدعــي العــام يف دليلــه الثانــي عشــر مــن محضــر العــرض والتعــرف علــي‬\n      ‫مــن قبــل املــرأة ‪ .........‬فصحيــح هكــذا أجــاب وأضــاف املدعــى عليــه‬\n      ‫الثانــي ‪ .........‬قائــا إننــي أعمــل يف اململكــة العربيــة الســعودية منــذ ســتة‬\n      ‫عشــر عاما وأعلم عن أنظمتها وال ميكن لي أن أقوم بالســرقة وحســبي‬\n      ‫اهلل علــى مــن قــام بالتســبب فينــي هكــذا ذكــر وجــرى ســؤال جميــع‬\n      ‫األطــراف هــل لديهــم مــا يريــدون إضافتــه يف هــذه القضيــة فأجابــوا‬\n      ‫قائلــن ليــس لدينــا ســوى مــا قدمنــا ونطلــب احلكــم يف هــذه القضيــة‬\n      ‫هكــذا أجابــوا عليــه فقــد رفعــت اجللســة للدراســة والتأمــل ويف جلســة‬\n      ‫أخــرى حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليهمــا وأضــاف‬\n      ‫املدعــى عليــه الثانــي ‪ .........‬قائــا إننــي قــد قمــت باإلقــرار علــى نفســي‬\n      ‫بقيامــي بســرقة األغنــام املوصوفــة يف الدعــوى وكان ذلــك بســبب مــا‬\n      ‫أصابنــي مــن الضــرب والتعذيــب وهــذا اإلقــرار أخــذ منــي بالقــوة وال بينــة‬\n\n\n‫‪267‬‬\n\f‫لــي علــى ذلــك وأنــا متراجــع عنــه هكــذا ذكــر فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وإلقــرار املدعــى عليــه األول ‪ .........‬املصــدق شــرعا مــن‬\n‫أنــه مكــن وســهل عمليــة ســرقة األغنــام املوصوفــة يف الدعــوى للمدعــى‬\n‫عليــه الثانــي ‪ .........‬ومــن معــه وأقــر بأنــه كان موجــود أثنــاء الســرقة‬\n‫وأنــه قــد تراجــع عــن هــذا اإلقــرار لكونــه أخــذ منــه بالقــوة وال بينــة لــه‬\n‫علــى ذلــك وإلقــرار املدعــى عليــه الثانــي ‪ .........‬املصــدق شــرعا مــن أنــه‬\n‫قــام بســرقة هــذه األغنــام املوصوفــة يف الدعــوى ومعــه صاحبيــه ‪.........‬‬\n‫و‪ .........‬مبســاعدة املدعــى عليــه األول ‪ .........‬وإقــراره ببيــع هــذه األغنــام‬\n‫املســروقة وحفــظ ثمنهــا لديــه لكــي يتمكــن هــو واملدعــى عليــه األول‬\n‫‪ .........‬ومــن معهمــا مــن تقاســم ثمنهــا الحقــا وأنــه قــد تراجــع عــن هــذا‬\n‫اإلقــرار لكونــه أخــذ منــه بالقــوة وال بينــة لــه علــى ذلــك وإقــراره بأنــه قــد‬\n‫قــام بتحويــل جــزء مــن املبلــغ وقــدره ســتون ألــف ‪ 60000‬ريــال إلــى بلــده‬\n‫خوفــا مــن أخــذ املــال منــه وقــد تراجــع عــن هــذا اإلقــرار لوجــود املبلــغ‬\n‫كامــا اخلــاص بقيمــة هــذه األغنــام املســروقة وقــدره مائــة وخمســون‬\n‫ألــف ريـ‪ 150000‬ــال مخبــأ مــع شــخص آخــر ولــم يقــم بتحويــل جــزء‬\n‫منــه إلــى بلــده وألن رجوعهمــا عــن هــذا اإلقــرار شــبهة يــدرأ بهــا احلــد‬\n‫لقــول النبــي صلــى اهلل عليــه وســلم (ادرؤوا احلــدود بالشــبهات) وملــا نقلــه‬\n‫صاحــب الشــرح الكبيــر (‪ )136/10‬عــن األوزاعــي مــا نصــه (وإن رجــع‬\n‫عــن الســرقة أو الشــرب ضــرب دون احلد)أ‪.‬ه ـ لــذا فقــد حكمنــا مبــا يلــي‬\n‫أوال‪ :‬إثبــات مــا أســند إلــى املدعــى عليــه األول‪ .........‬مــن مســاعدة املدعى‬\n‫عليــه الثانــي ‪ .........‬ومــن معــه للدخــول إلــى املزرعــة وســرقة األغنــام منهــا‬\n‫املوصوفــة يف الدعــوى وقررنــا تعزيــره لقــاء ذلــك بســجنه ثــاث ســنوات‬\n‫وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات بــن كل دفعــة وأخــرى‬\n\n\n                                                                                           ‫‪268‬‬\n\f      ‫خمســة عشــر يومــا ثانيــا‪ :‬إثبــات مــا أســند إلــى املدعــى عليــه الثانــي‬\n      ‫‪ .........‬مــن قيامــه بســرقة األغنــام املوصوفــة يف الدعــوى وقررنــا تعزيــره‬\n      ‫لقــاء ذلــك بســجنه أربــع ســنوات وجلــده أربعمائــة جلــدة مفرقــة علــى‬\n      ‫ثمــان دفعــات بــن كل دفعــة وأخــرى خمســة عشــر يومــا ثالثا‪:‬صرفنــا‬\n      ‫النظــر عــن طلــب املدعــي العــام احلكــم علــى املدعــى عليــه الثانــي ‪.........‬‬\n      ‫بالعقوبــة املنصــوص عليهــا باملــادة السادســة عشــر مــن نظــام مكافحــة‬\n      ‫غســل األمــوال لعــدم موجبهــا هكــذا حكمنــا وبعــرض احلكــم علــى‬\n      ‫املدعــي العــام واملدعــى عليهمــا اعترضــوا عليــه وطلبــوا متييــزه مــع تقــدمي‬\n      ‫الئحــة اعتراضيــة فأجيــب إلــى طلبهــم وســلم لهــم صــورة مــن القــرار‬\n      ‫الشــرعي يف هــذه اجللســة بتاريــخ ‪1433/6/17‬ه ـ وأفهمناهــم بــأن لــه‬\n      ‫مــدة أقصاهــا ثالثــون يومــا مــن هــذا التاريــخ فــإذا انقضــت املــدة ولــم‬\n      ‫يقدمــوا اعتراضهــم فإنــه يســقط حقهــم يف االعتــراض وســيتم رفــع‬\n      ‫كامــل املعاملــة إلــى مقــام محكمــة االســتئناف املوقــرة باجلــوف لتدقيــق‬\n      ‫احلكــم حســب املتبــع ففهمــوا ذلــك واختتمــت اجللســة يف متــام الســاعة‬\n      ‫الواحــدة وللبيــان حــرر يف ‪1433/6/17‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                                                                 ‫محمــد ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء ‪1433/11/2‬ه ـ فقــد وردتنــا‬\n      ‫املعاملــة مــن مقــام محكمــة االســتئناف املوقــرة بتبــوك مبوجــب‬\n      ‫خطــاب فضيلــة رئيســها رقــم ‪ 331478856‬يف ‪1433/9/6‬ه ـ وبرفقــه‬\n      ‫القــرار الصــادر مــن الدائــرة اجلزائيــة اخلماســية رقــم ‪ 33396816‬يف‬\n      ‫‪1433/8/28‬ه ـ ونــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة وأوراق املعاملــة لوحــظ مــا يلــي أوال ‪ :‬لــم يحكــم‬\n      ‫أصحــاب الفضيلــة بــدرء حــد الســرقة عــن املدعــى عليــه الثانــي مــع‬\n\n\n‫‪269‬‬\n\f‫تســبيبهم بــدرء احلــد ثانيــا ‪ :‬احلكــم قليــل يف حــق املدعــى عليهمــا ال‬\n‫ســيما مــع إقراريهمــا اللذيــن رجعــا عنهمــا واملصدقــن شــرعا ملالحظــة‬\n‫مــا ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم)أ‪.‬هـ قاضــي اســتئناف‪.........‬‬\n‫موقــع علــى األصــل ومجــاز ولوجاهــة مــا رأه أصحــاب الفضيلــة فقــد‬\n‫حكمنــا بــدرء حــد الســرقة عــن املدعــى عليهمــا كمــا حكمنــا بزيــادة‬\n‫عقوبــة املدعــى عليهمــا ســنتني لــكل واحــد منهمــا بحيــث يصبــح‬\n‫مجمــوع ســجن املدعــى عليــه األول ‪ .........‬خمــس ســنوات ومجمــوع ســجن‬\n‫املدعــى عليــه الثانــي‪ ..............‬ســت ســنوات وبعرضــه علــى املدعــي العــام‬\n‫واملدعــى عليهمــا قــرروا اعتراضهــم عليــه مكتفــن مبا قدمــوا من لوائح‬\n‫اعتراضيــة وأمرنــا بإحلاقــه يف الضبــط وصورتــه ويف القــرار ثــم إرســال‬\n‫كامــل املعاملــة إلــى محكمــة االســتئناف املوقــرة بتبــوك إلكمــال‬\n‫الزمهــا واختتمــت اجللســة يف متــام الســاعة الثامنــة وثالثــن دقيقــة وللبيــان‬\n          ‫حــرر يف ‪1433/11/2‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم األربعــاء ‪1434/1/21‬ه ـ افتتحــت اجللســة‬\n‫الســابعة يف متام الســاعة ‪ 08 : 30‬فقد وردتنا املعاملة من مقام محكمة‬\n‫االســتئناف املوقــرة بتبــوك مبوجــب خطــاب فضيلــة رئيســها رقــم‬\n‫‪ 332090823‬يف ‪1434/1/6‬ه ـ وبرفقــه القــرار الصــادر مــن الدائــرة‬\n‫اجلزائيــة اخلماســية رقــم ‪ 342635‬يف ‪1434/1/5‬ه ـ ونــص احلاجــة منــه‬\n‫(وبدراســة القــرار وصــورة ضبطــه ولوائحــه االعتراضيــة وأوراق املعاملــة‬\n‫وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة القضــاة علــى قــرار‬\n‫الدائــرة رقــم ‪ 33396816‬وتاريــخ ‪1433/8/28‬ه ـ لوحــظ مــا يلــي أوال‪:‬‬\n‫إن مــا حكــم بــه أصحــاب الفضيلــة علــى املدعــى عليهمــا مــا زال قليــا‬\n\n\n                                                                                      ‫‪270‬‬\n\f      ‫ســيما عقوبــة اجللــد نظــرا خلطــورة جرمهمــا وكونــه جرمــا منظمــا مــن‬\n      ‫عصابــة وكثــرة عــدد األغنــام املســروقة وكثــرة مبالــغ وأقيــام بيعهــا لهــا‬\n      ‫وقــد تكــررت منهمــا الســرقة حســبما يف اعترافهمــا كمــا أن املدعــى‬\n      ‫عليــه ‪ .........‬هــو صاحــب الــدور الرئيــس يف عمليــة تســهيل الســرقة وهــو‬\n      ‫يعمــل يف املزرعــة ولــواله ملــا حصلــت فهــو يحتــاج إلــى تشــديد العقوبــة‬\n      ‫عليــه ثانيــا‪ :‬صــرف أصحــاب الفضيلــة النظــر عــن مطالبــة املدعــي‬\n      ‫العــام تطبيــق العقوبــة املنصوصــة يف نظــام مكافحــة غســل األمــوال‬\n      ‫عــن املدعــى عليــه الثانــي ‪ .........‬وهــذا محــل نظــر ألنــه جــاء باعترافــه‬\n      ‫املصــدق شــرعا قيامــه بتحويــل ســتني ألــف ‪ 60000‬ريــال لبلــده الســودان‬\n      ‫مــن محصلــة أقيــام تلــك األغنــام املســروقة ورجوعــه عــن ذلــك ال يقبل ألن‬\n      ‫رجوعــه عنــه يف جانــب الســرقة لألغنــام لــم يقبــل منــه ألن كليهمــا يف‬\n      ‫جانــب الرجــوع عــن موجــب التعزيــر فــا يعــد شــبهة يف إســقاط اإلقــرار‬\n      ‫ســيما وأن املبلــغ الــذي قــام بتحويلــه ليــس ضمــن املبلــغ الــذي وضعــه عنــد‬\n      ‫أحــد األشــخاص وقــدره مائــة وخمســون ألــف ريـ‪ 150000‬ــال ثالثــا‪ :‬لــم‬\n      ‫يــوص أصحــاب الفضيلــة بإبعــاد املدعــي عليهمــا عــن البــاد بعــد انتهــاء‬\n      ‫محكوميتهمــا ومنعهمــا مــن العــودة إال فيمــا تقضــى بــه تعليمــات احلــج‬\n      ‫والعمــرة وذلــك خلطورتهمــا وحتقــق أذاهمــا ملالحظــة مــا ذكــر وإكمــال‬\n      ‫الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمد‬\n      ‫وآلــه وصحبــه وســلم)أ‪.‬هـ ولوجاهــة مــا رآه أصحــاب الفضيلــة فقــد‬\n      ‫حكمنــا بزيــادة عقوبــة ســجن املدعــى عليهمــا األول ‪ .........‬ملــدة ســنتني‬\n      ‫بحيــث يصبــح مجمــوع ســجنه ســبع ســنوات والثانــي ‪ .........‬ملــدة ســنة‬\n      ‫بحيــث يصبــح مجمــوع ســجنه ســبع ســنوات كمــا رجعنــا عــن حكمنــا‬\n      ‫بصــرف النظــر عــن طلــب املدعــي العــام تطبيــق العقوبــة املنصــوص‬\n\n\n‫‪271‬‬\n\f‫عليهــا باملــادة السادســة عشــرة مــن نظــام مكافحــة غســل األمــوال علــى‬\n‫املدعــى عليــه الثانــي ‪ .........‬وحكمنــا بتغرميــه مبلــغ وقــدره مائــة ألــف‬\n‫ريـ‪ 100000‬ــال يدفعهــا خلزينــة الدولــة كمــا أننــا نوصــي بإبعــاد املدعــى‬\n‫عليهمــا عــن البــاد بعــد انتهــاء محكوميتهمــا ومنعهمــا مــن العــودة إال‬\n‫فيمــا تقضــي بــه تعليمــات احلــج والعمــرة هــذا جوابنــا وبعــرض احلكــم‬\n‫علــى املدعــي العــام قــرر اعتراضــه عليــه مكتفيــا مبــا قدمــه مــن الئحــة‬\n‫اعتراضيــة وقــررا املدعــى عليهمــا قناعتهمــا بــه ولئــا يخفــى جــرى‬\n‫إحلاقــه يف ضبطــه وســيجري إحلاقــه يف القــرار وصورتــه وســيتم بعــث‬\n‫كامــل املعاملــة إلــى مقــام محكمــة االســتئناف حســب املتبــع واختتمــت‬\n‫اجللســة يف متــام الســاعة ‪ 09 : 00‬وللبيــان حــرر يف ‪1434/1/21‬ه ـ وصلــى‬\n                                               ‫اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم االثنــن ‪1434/3/23‬ه ـ وبنــاء علــى رجــوع‬\n‫املعاملــة مــن مقــام محكمــة االســتئناف املوقــرة بتبــوك مبوجــب خطــاب‬\n‫رئيســها رقــم ‪ 34422686‬يف ‪1434/3/16‬ه ـ وبرفقــه القــرار الصــادر‬\n‫مــن الدائــرة اجلزائيــة اخلماســية رقــم ‪ 3460112‬يف ‪1434/3/11‬ه ـ‬\n‫واملتضمــن املوافقــة علــى احلكــم باألكثريــة وللبيــان حــرر يف‬\n                   ‫‪1434/3/23‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n\n\n\n\n                                                                                    ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":239,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d1e3f954895deb4f30d28823c4de15a0f4fe726a2605745c98ead8f6a6d095d9","normalized_text_hash":"40d298b19d89e19038b5039abfa30b08080943068c2ade9b27302b29f74b72f2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p239-33303859"},{"id":"952c1e62-b2ab-51a7-8c00-d5b2d468209c","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة عدة منازل -سرقة عدة منازل -دخول منازل ا -ترويع ساكنني -وجود سوابق قضائية -تقرير قصاص أثر- لي محضر تصرف بالقيمة -تعرف طفلة على جاني -طلب إقامة حد سرقة -درء حد السرقة لعدم اكتمال البينة املوجبة للحد -تشديد عقوبة .","document_number":"33290357","case_number":"33171844","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة ويف يوم االثنن املوافق1433/03/28ه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/10","year":"1434","subject":"سرقة -انتهاك حرمة عدة منازل -سرقة عدة منازل -دخول منازل ا -ترويع ساكنني -وجود سوابق قضائية -تقرير قصاص أثر- لي محضر تصرف بالقيمة -تعرف طفلة على جاني -طلب إقامة حد سرقة -درء حد السرقة لعدم اكتمال البينة املوجبة للحد -تشديد عقوبة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33290357:‬تاريخه ‪1433/6/10:‬هـ‬\n                        ‫رقم الدعوى‪33171844:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 33386166‬تاريخه‪1433/8/20 :‬ه‬\n\n\n\n      ‫ســرقة‪ -‬انتهــاك حرمــة عــدة منــازل ‪ -‬ســرقة عــدة منــازل ‪ -‬دخــول منــازل‬\n      ‫ا‪ -‬ترويــع ســاكنني‪ -‬وجــود ســوابق قضائيــة ‪ -‬تقريــر قصــاص أثــر‪-‬‬      ‫ليـ ً‬\n      ‫محضــر تصــرف بالقيمــة‪ -‬تعــرف طفلــة علــى جانــي‪ -‬طلــب إقامــة‬\n      ‫حــد ســرقة‪ -‬درء حــد الســرقة لعــدم اكتمــال البينــة املوجبــة للحــد‬\n                                                                 ‫‪ -‬تشــديد عقوبــة ‪.‬‬\n\n\n\n\n                                ‫انعقد اإلجماع على أن احلدود تدرأ بالشبهات‪.‬‬\n\n\n\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه بانتهــاك حرمــة عــدة منــازل‬\n      ‫ا وترويــع ســاكنيها وكســر دوالب خشــبي‬                 ‫وســرقتها ودخولهــا لي ـ ً‬\n      ‫وســرقة مبلــغ مالــي مــن شــنطة بالســتيكية بداخلــه وســرقة مبلــغ مالــي‬\n      ‫ا يف منزلــه‪ ،‬وطلــب إقامــة حــد‬    ‫مــن جيــب ثــوب شــخص أثنــاء نومــه لي ـ ً‬\n      ‫الســرقة علــى املدعــى عليــه‪،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ‬\n      ‫مــن أحــد املواطنــن يفيــد أنــه شــاهد املدعــى عليــه وهــو يســرق منزلــه‪،‬‬\n      ‫وجــدت ســوابق علــى املدعــى عليه‪،‬أنكر املدعى عليــه الدعوى‪،‬أحضر‬\n      ‫املدعــي العــام شــهود تعرفــوا علــى املدعــى عليــه أثنــاء قيامــه بالســرقة‬\n      ‫ودخــول املنــازل‪ ،‬وجــود تقريــر قصــاص األثــر بانطبــاق أثــر املدعــى عليــه‬\n\n‫‪273‬‬\n\f‫مــع أثــر شــخص حــايف األقــدام بداخــل حوش أحــد املواقع الــذي تعرضت‬\n‫للســرقة‪ ،‬تقريــر ناظــري القضيــة أن بينــة املدعــي العــام ال يثبــت بهــا‬\n‫احلــد لعــدم اكتمالهــا‪،‬مت درء حــد الســرقة عــن املدعــى عليه‪،‬وقضــت‬\n‫بتعزيــر املدعــى عليــه بالســجن واجللــد‪ ،‬طلــب محكمــة االســتئناف‬\n‫زيــادة التعزيــر خلطــورة مــا أقــدم عليــه وكثــرة ســوابقه‪ ،‬مت زيــادة تعزيــر‬\n         ‫املدعــى عليــه ‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد لدينــا نحن كل مــن ‪.....‬و‪.......‬و‪ .......‬قضاة الدائرة‬\n‫اجلنائيــة الثانيــة يف احملكمــة العامــة ببريــدة ويف يــوم االثنــن‬\n‫املوافق‪1433/03/28‬ه ـ افتتحــت اجللســة بنــاء علــى املعاملــة الــواردة‬\n‫للمحكمــة مــن رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام بالقصيــم‬\n‫برقــم ه ـ ص ‪ 4738/6/1‬يف ‪1433/3/7‬ه ـ احملالــة لنــا من فضيلة رئيس‬\n‫احملكمــة برقــم‪33171844‬يف ‪1433/3/8‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 33437714‬يف‪1433/3/7‬ه ـ وعليــه حضــر املدعــي العــام ‪ .......‬قائــا‬\n‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة القصيــم فإننــي‬\n‫أدعــي علــى ‪ 32 .....‬عام ـ ًا ســعودي بالســجل املدنــي رقــم ‪ ......‬أعــزب‪،‬‬\n‫عاطــل‪ ،‬يقيــم يف بلــدة ‪ ......‬املقبــوض عليــه بتاريــخ ‪1432/11/25‬ه ـ وال‬\n‫زال موقوفـ ًا يف ســجن بريــدة مبوجــب أمــر متديــد التوقيــف رقــم ‪....‬وتاريــخ‬\n‫‪1432/1/12‬ه ـ الصــادر مــن صاحــب الســمو امللكــي أميــر منطقــة‬\n‫القصيــم‪ .‬وإنــه بتاريــخ ‪1432/10/3‬ه ـ ويف الســاعة ‪ 8.30‬ص تقــدم‬\n‫املواطــن‪ ......‬ملركــز شــرطة الشماســية ببــاغ مفــاده أنــه يف الســاعة‬\n‫ا قــام املدعــى عليــه بالدخــول إلــى منزلــه الواقــع‬   ‫الثانيــة والنصــف لي ـ ً‬\n\n                                                                                       ‫‪274‬‬\n\f      ‫ببلــدة ‪ ......‬وســرق محفظتــه والتــي حتــوي مبلغ ـ ًا وقــدره ســتمائة ريــال‬\n      ‫ورخصــة ســير وبطاقــة األحــوال الوطنيــة وصرافتــن واحــدة لبنــك ‪...‬‬\n      ‫واألخــرى لبنــك ‪. ....‬وبســماع أقــوال املواطــن ‪ ...... /‬أفــاد انــه يف الســاعة‬\n      ‫الثانيــة والنصــف مــن صبــاح يــوم اخلميــس ‪1432/10/3‬ه ـ قــام شــخص‬\n      ‫ـرأى‬\n       ‫بتســلق ســور املنــزل الواقــع ببلــدة ‪ .......‬ودخــل غرفــة النــوم علــى مـ ً‬\n      ‫منــه ولــم يســتطع فعــل شــيء لــه خلوفــه وهــو شــخص طويــل القامــة ابيــض‬\n      ‫البشــرة ورأســه بــه صلــع ويرتــدي قميصـ ًا لونــه بنــي فأخــذ محفظتــه مــن‬\n      ‫ثوبــه والتــي حتــوي مبلغ ـ ًا قــدره ســتمائة ريــال ورخصــة ســير وبطاقــة‬\n      ‫األحــوال الوطنيــة وصرافتــن واحــدة لبنــك ‪ .....‬واألخــرى لبنــك ‪.....‬‬\n      ‫‪.‬ومبعاينــة منــزل املواطــن‪ ...... /‬الواقــع ببلــدة ‪ ......‬اتضــح وجــود آثــار‬\n      ‫أقــدام داخــل املنــزل أثبــت قصــاص األثــر عائديتهــا للمدعــى عليــه ولــم‬\n      ‫يتضح وجود آثار عنف أو تكســير يف املنزل‪ .‬وبتاريخ ‪1432/11/11‬هـ‬\n      ‫ويف الســاعة الثامنــة وأربعــن دقيقــة صباحـ ًا تقــدم املواطــن ‪ ....../‬ملركز‬\n      ‫شــرطة الشماســية ببــاغ مفــاده مشــاهدته لشــخص داخــل منزلــه الواقــع‬\n      ‫ببلــدة ‪ ......‬وقــد متكــن مــن الهــرب جلهــة غيــر معلومــة ومــن احملتمــل أنــه‬\n      ‫ينــوي الســرقة‪ .‬وبســماع أقــوال املواطــن‪ ...... /‬أفــاد أنــه يف الســاعة‬\n      ‫ا مــن يــوم الســبت ‪1432/11/10‬ه ـ وأثنــاء جلوس‬          ‫العاشــرة والنصــف ليـ ً‬\n      ‫أهلــه يف فنــاء املنــزل لتنــاول العشــاء دخــل أحــد األطفال املنزل فشــاهدت‬\n      ‫شــخص ًا يف الــدرج فطلــب منهــا أن ال تخبــر أحد ًا فعادت الطفلة وأخبرت‬\n      ‫أهلهــا فلمــا شــاهدهم هــرب وكان يقول(هجــو هجــو) فاتضــح أن‬\n      ‫برفقتــه اثنــان آخــران أحدهمــا هــرب مــن البــاب واآلخــر مــن فــوق الســور‬\n      ‫وأفــاد أن الشــخص الــذي متــت مشــاهدته يف املنــزل يلبــس بدلــة جنــز‬\n      ‫وأصلــع الــرأس مــن اخللــف وطويــل القامــة ونحيــل اجلســم كمــا أفــاد أنــه‬\n\n\n‫‪275‬‬\n\f‫يف ليلــة احلادثــة لديهــم ضيــف مــن اجلنســية الســورية يدعــى( ‪ )......‬شــاهد‬\n‫املدعــى عليــه وكان يظــن أنــه مــن أهــل البيت ويعرف أوصافــه‪ .‬ومبعاينة‬\n‫منــزل املواطــن‪ ..... /‬والواقــع ب‪.....‬اتضــح أنــه يقــع داخــل مزرعــة نخيــل‬\n‫ولــم يتضــح أي آثــار تكســير أو أشــياء أخــرى تفيــد التحقيــق‪ .‬وبتاريــخ‬\n‫‪1432/11/25‬ه ـ ويف متــام الســاعة السادســة صباح ـ ًا ورد بــاغ لغرفــة‬\n‫العمليــات مــن املواطــن‪ ........ /‬مفــاده قيــام شــخص بدخول منزله وســرقة‬\n‫مبلــغ قــدره خمســن ألــف ريــال ‪.‬وباالنتقــال مــن قبــل الدوريــات األمنيــة‬\n‫حــال تلقيهــا البــاغ مت القبــض علــى املدعــى عليــه وبحوزتــه مبلغـ ًا وقــدره‬\n‫اثنــان وعشــرون ألــف ريــال (مت تســليمها لصاحبهــا) وجــوال بــاك بيــري‬\n‫وجــوال نوكيــا مــن نــوع الكشــاف وبســماع أقــوال املواطــن‪ ..... /‬أفــاد‬\n‫أنــه يف حوالــي الســاعة اخلامســة والنصــف مــن صبــاح يــوم األحــد‬\n‫‪1432/11/25‬ه ـ أفــاق علــى صيــاح والدتــه واســتنجادها وعنــد خروجــه‬\n‫مــن غرفتــه شــاهد شــخص ًا يدفــع والدتــه ويخــرج مــن املنــزل فقــام‬\n‫باللحــاق بــه ومتابعتــه ومطاردتــه خــارج املنــزل حتــى مت القبــض عليــه مــن‬\n‫قبــل الدوريــات األمنيــة كمــا أفــاد أنــه افتقــد مبلغـ ًا قــدره خمســن ألــف‬\n‫ريــال كان قــد وضعهــا يف الــدوالب يف إحــدى غــرف املنــزل (املقلــط)‬\n‫وأنــه أثنــاء هروبــه تــرك حــذاءه وقطعــة بالســتكية تابعــة جلوالــه وقــد‬\n‫ُسـ ِـرق مــن املنــزل مجوهــرات وجــوال ومبلغ ـ ًا قــدره ألــف ومائتــي ريــال‬\n‫قبــل حوالــي أســبوعني ومبعاينــة منــزل املواطــن‪ ...... /‬والواقــع ببلــدة ‪......‬‬\n‫اتضــح مــن خــال األثــر والتــي أثبــت قصــاص األثــر عائديتهــا للمدعــى‬\n‫عليــه وأنــه حــاول تســور املنــزل مــن اجلهــة اجلنوبيــة الغربيــة بوضعــه قطعــة‬\n‫خشــبية للصعــود عليهــا ولــم يســتطع كمــا شــوهدت لــه آثــار كثيــرة يف‬\n‫املوقــع بعدهــا اجتــه لزاويــة املنــزل الشــمالية وتســور اجلــدار الشــمالي عــن‬\n\n\n                                                                                        ‫‪276‬‬\n\f      ‫طريــق البــاب ومــن ثــم دخــل لفنــاء املنــزل حيــث لوحــظ نزولــه علــى‬\n      ‫إطــارات ســيارة كانــت موجــودة يف املنــزل بجانــب اجلــدار وشــوهدت‬\n      ‫آثــاره حــايف القدمــن داخــل ســور املنــزل متجهـ ًا ملكان الســرقة ومبعاينة‬\n      ‫الغرفــة التــي حدثــت بهــا الســرقة اتضــح أنهــا يف مقدمــة املنــزل ويوجــد‬\n      ‫فيهــا دوالب خشــبي عرضــه متــر وارتفاعــه متريــن ويوجــد داخلــه شــنطة‬\n      ‫حديديــة ومالبــس وقــد لوحــظ آثــار عنــف علــى الــدوالب كمــا وجــد يف‬\n      ‫الغرفــة حــذاء وجعبــة جــوال أفــاد أصحــاب املســكن عائديتهــا للمدعــى‬\n      ‫عليــه حيــث تركهــا أثنــاء العــراك مــع والــدة املدعــي كمــا متــت متابعــة‬\n      ‫آثــار املدعــى عليــه والطــرق التــي ســلكها بعــد خروجــه مــن املنــزل حتــى‬\n      ‫مت القبــض عليــه كمــا مت البحــث يف كل املواقــع التــي يحتمــل أنــه‬\n      ‫ســلكها للبحــث عــن اجلــزء املتبقــي مــن املبلــغ املســروق ولــم يعثــر علــى‬\n      ‫شــيء‪ .‬وبضبــط أقــوال الشــاهد املقيــم‪ ..... /‬ســوري اجلنســية برخصــة‬\n      ‫اإلقامــة رقــم(‪ ).......‬أفــاد أنــه كان مدعــو ًا وأهلــه لوليمــة عشــاء عنــد‬\n      ‫املواطــن ‪ ........‬فشــاهد املدعــى عليــه داخــل املنــزل وكان يظــن أنــه مــن‬\n      ‫أهــل املنــزل وعندمــا قالــت ربــة املنزل(حرامي)هــرب وكان يلبــس بدلــة‬\n      ‫بنيــة اللــون وبنطــا ًال أســود ويوجــد بــه صلــع يف منتصــف الــرأس مــن‬\n      ‫األعلــى وهــو طويــل ونحيــف ويســتطيع التعــرف عليــه لــو رآه‪ .‬وبضبــط‬\n      ‫أقــوال الشــاهد‪ ...... /‬بالســجل املدنــي رقم(‪).......‬ويســكن بلــدة ‪......‬‬\n      ‫أفــاد انــه بعــد صــاة الفجــر مــن يــوم األحــد ‪1432/11/25‬ه ـ كان‬\n      ‫جالس ـ ًا عنــد بــاب منزلــه فشــاهد املدعــى عليــه يركــض مــع الشــارع‬\n      ‫املقابــل ملنزلــه مــن الشــمال باجتــاه اجلنــوب ويلبــس بنطــا ًال أســود وبدلــة‬\n      ‫رصاصيــة وهــو نحيــف وطويــل وحليتــه خليجيــة وشــاربه خفيــف وتوجــد‬\n      ‫بــه صلعــة يف منتصــف الــرأس وصلعــة يف آخــره وعندمــا شــاهده خفــف‬\n\n\n‫‪277‬‬\n\f‫الركــض وأخــذ يهــرول فمــر مــن الطريــق املدعــي ‪ .......‬بســيارته مــن نــوع‬\n‫‪ .......‬وكان مســرع ًا فشـ ّـك يف الوضــع واجتــه للجهــة الغربيــة مــن املنــزل‬\n‫وشــاهد املتهــم واقــف عنــد بــاب اســتراحة مجــاورة لــه ويضــع يديــه يف‬\n‫جيبوبــه بعدمــا قــام برمــي أحجــار يف حــوش أغنــام قريــب منــه ثــم توجــه‬\n‫املدعــى عليــه ملنــزل ‪ .....‬فحضــر املدعــي لديــه وســأله هل شــاهد شــخص ًا‬\n‫مـ ّـر مــن هنــا فأخبــره أنــه شــاهده فركــب مــع املدعــي وتوجهــا ملنــزل ‪.....‬‬\n‫فشــاهد املدعــى عليــه جالسـ ًا عنــده فاتصــل ‪ ......‬علــى الشــرطة ثــم ذهبــا‬\n‫فأنزلــه املدعــي عنــد منزلــه فصعــد علــى الســطح ملراقبــة املدعــى عليــه‬\n‫فركــب املدعــى عليــه مــع ‪ ........‬واجتهــا لشــرق البلــد فاتصــل علــى‬\n‫املدعــي ‪ ....‬والشــاهد ‪ .....‬وأخبرهمــا بذلــك‪ .‬وبضبــط أقــوال الشــاهد ‪/‬‬\n‫‪ ......‬ســعودي بالســجل املدنــي رقم(‪).......‬ويســكن بلــدة ‪ ......‬أفــاد أنــه‬\n‫بعــد صــاة الفجــر مــن يــوم األحــد ‪1432/11/25‬ه ـ شــاهد املدعــى عليه‬\n‫يركــض مــع الشــارع املقابــل ملنــزل الشــاهد ‪ ........‬وكان يرتــدي بنطــا ًال‬\n‫أســود وبدلــة رصاصيــة وال يســتطيع حتديــد أوصافــه لبعــده عنــه كمــا‬\n‫شــاهد املدعــي ‪ ......‬يالحقــه فركــب ســيارته وحلــق بــه لينظــر مــا الــذي‬\n‫يجــري فوجــد‪ .....‬ومعــه الشــاهد ‪ .....‬متوقــف بالقــرب مــن منــزل ‪......‬‬\n‫والــذي يقــف بجوارهــا املدعــى عليــه يتحــدث مــع ‪ .....‬وابنــه ‪ ....‬فوقــف‬\n‫عندهــم فذكــر لــه ‪ .....‬أن املدعــى عليــه ســرق مــن عندهــم وملــا اقتــرب‬\n‫منــه عــرف أنــه املدعــى عليــه للمعرفــة الســابقة بينهمــا ثــم رجــع ملنزلــه‬\n‫فاتصــل بــه املدعــي‪ .....‬وأخبــره أن املدعــى عليــه ركــب مــع ‪ ....‬علــى‬\n‫ســيارته مــن نــوع ‪ ......‬وطلــب منــه مراقبتهمــا فتحــرك للبحــث عنهمــا‬\n‫فوجــد املتهــم عنــد بــاب منــزل ‪ ....‬فتوقــف عنــده وسـلّم عليــه والحــظ عليه‬\n‫عالمــات االرتبــاك فســأله عــن ســبب تواجــده يف هــذا املــكان فأخبــره‬\n\n\n                                                                                       ‫‪278‬‬\n\f      ‫أنــه عنــد بــاب منــزل عمــه وســأله هــل هنــاك شــيء حصــل يف البلــد فــرد‬\n      ‫عليــه أنــه جــاءه قائــد ســيارة مــن نــوع ‪ ......‬يســأله عــن غنــم بعــد ذلــك‬\n      ‫حضــرت الدوريــات وقبضــت عليــه ‪.‬وباســتجواب املدعــى عليــه أفــاد أنــه‬\n      ‫يعــرف املدعــي حيــث أنــه يصلــي معهــم يف املســجد ويعــرف مســكنه‬\n      ‫كونــه جارهــم وعالقتــه فيــه للســام فقــط ونفــى معرفتــه باملدعــي‪/‬‬\n      ‫‪ ......‬وأفــاد أنــه ال يعرفــه وليــس لــه اختــاط بأحــد مــن أهــل ‪،......‬‬\n      ‫ومبناقشــته عــن دخولــه ملنــزل املدعــي ‪ ....‬وســرقته املبالــغ املاليــة أفــاد أن‬\n      ‫حضــوره لبلــدة ‪ ......‬مــن أجــل أخــذ الســيارة مــن عمــه لكــون ســيارته‬\n      ‫متعطلــة وأن املبالــغ التــي وجــدت بحوزتــه هــي مــن عملــه حيــث أنــه يبيــع‬\n      ‫ويشــتري يف ســوق اخلضــار ويجمــع احلديــد مــن احملــارق و ليــس لديــه‬\n      ‫حســابات بنكيــة يــودع فيهــا وبعــرض املدعــى عليــه علــى الشــهود مــع‬\n      ‫مجموعــة آخريــن للتعــرف عليه كلٌ على حدة اســتطاع املقيم الســوري‪/‬‬\n      ‫‪ ......‬والــذي كان يف منــزل املدعــي‪ ...../‬وقــت احلادثــة و الطفلــة‪...... /‬‬\n      ‫التــوت ووالــدة املدعــي‪ .......... /‬املواطنــة‪ ..../‬التعــرف عليــه وانتهــى‬\n      ‫التحقيــق بقــرار االتهــام املؤيــد بقــرار جلنــة إدارة الهيئــة رقــم(‪/432‬ص)‬\n      ‫لعــام ‪1433‬ه ـ إلــى اتهــام ‪ ............‬بانتهــاك حرمــة عــدة منــازل ودخولهــا‬\n      ‫ا وترويــع ســاكنيها وكســر دوالب خشــبي وســرقة خمســن ألــف‬                    ‫لي ـ ً‬\n      ‫ريــال مــن شــنطة بالســتيكية بداخلــه وســرقة ســتمائة ريــال مــن جيــب‬\n      ‫ا يف منزلــه وذلــك لألدلــة والقرائــن التاليــة‪:‬‬   ‫ثــوب شــخص أثنــاء نومــه ليـ ً‬\n      ‫‪/1‬شــهادة الشــهود املدونــة علــى الصفحــات رقــم (‪ )13-9-8‬مــن دفتــري‬\n      ‫التحقيــق املرفــق لفــة (‪/2 .)4-3‬محضــر القبــض املــدون علــى الصفحــة‬\n      ‫رقــم (‪ )1‬مــن دفتــر التحقيــق املرفــق لفــة (‪/3 )1‬محضــري املعاينــة‬\n      ‫املدونــن علــى الصفحتــن (‪ )11-3‬مــن دفتــري التحقيــق املرفقــن لفــة‬\n\n\n‫‪279‬‬\n\f‫(‪/4 .)6-1‬شــهادة قصــاص األثــر املدونــة علــى الصفحــات رقــم (‪-10‬‬\n‫‪ )2-16‬مــن دفتــري التحقيــق املرفقــن لفــة (‪/5.)2-6‬محضــر القبــض‬\n‫والتفتيــش املــدون علــى الصفحــة (‪ )6‬مــن دفتــر التحقيــق املرفــق لفــة‬\n‫(‪/6)1‬مــا جــاء يف أقــوال املــرأة ‪ ....‬املــدون علــى الصفحــة (‪ )15‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــة (‪/7.)1‬تعرف الشــهود عليه املدونــة على الصفحات‬\n‫رقــم (‪ )3-13‬مــن دفتــري التحقيــق لفــة رقــم (‪.)5-2‬وبالبحــث عــن‬\n‫ســوابقه اتضــح أن لديــه ســت ســوابق أربــع منهــا ســرقات ودخــول منــازل‬\n‫وســابقتي حيــازة مخــدرات وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو‬\n‫ســرقة مــال محتــرم مــن حــرزه بعــد هتكــه يزيــد علــى النصــاب ال شــبهة‬\n‫لــه فيــه وطالــب بــه صاحبــه واســتناد ًا للمادتــن‪ )129 ،126( :‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n‫بحــد الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة‪،‬‬\n‫ا وترويــع النســاء واألطفــال‬    ‫وتعزيــره لقــاء دخولــه منــازل أخــرى لي ـ ً‬\n‫والتشــديد عليــه لقــاء تعــدد ســوابقه‪ .‬علم ـ ًا بــأن احلــق اخلــاص مــازال‬\n‫قائمــا‪ .‬وبــاهلل التوفيــق ‪.‬هــذا وقــد حضــر ‪ ......‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪.......‬املولــود بتاريــخ ‪1400/3/19‬ه ـ واملكلــف شــرعا وذلــك برفقــة‬\n‫اخلفيــر ‪ ......‬وبســؤال املدعــى عليــه عــن دعــوى املدعــي العــام اجــاب قائــا‬\n‫مــا ذكــره املدعــي العــام غيــر صحيــح وبعــرض ذلــك علــى املدعــي العــام‬\n‫قــال الصحيــح مــا جــاء يف دعــواي ولــدي البينــة علــى ذلــك واطلــب مهلــة‬\n‫الحضارهــا ورفعــت اجللســة ليــوم االثنــن املوافــق ‪1433/4/12‬ه ـ ويف‬\n‫املوعــد احملــدد حضــر املدعــي العــام وقد أحضر معه ‪ .....‬ســوري اجلنســية‬\n‫برخصــة اإلقامــة رقــم ‪ ........‬وطلــب ســماع مــا لديــه وبســؤاله عمــا لديــه‬\n\n\n                                                                                      ‫‪280‬‬\n\f      ‫قــال أشــهد بــأن املدعــى عليــه وهــو ‪ .......‬وقــد تعرفــت عليــه يف الشــرطة‬\n      ‫وأنــه قبــل خمســة أشــهر تقريبــا كنــت انــا وزوجتــي وأوالدي يف ضيافــة‬\n      ‫‪ ........‬يف بيتــه ب ـ ‪ ......‬لزيــارة زوجــة ‪.....‬وهــي بنــت عمتــي وأثنــاء ذلــك‬\n      ‫شــاهدت املدعــى عليــه يف البيــت البســا بدلــة ويوجد بــه صلع يف منتصف‬\n      ‫الــرأس مــن األعلــى وهــو طويــل ونحيــف وكان واضعــا يــده علــى جنبــه‬\n      ‫كأن معــه ســاحا أبيضــا ولــم أشــاهد ذلــك لكن شــكل حاله مســتعد‬\n      ‫للمقاومــة ثــم إننــي ســألت بنــت عمتــي عــن هــذا الشــخص فقالــت ال‬\n      ‫أعرفــه ثــم صوتــت بقولهــا حرامــي فلحقــت بــه وخــرج مــن البيــت وقــد‬\n      ‫رأتــه ابنتــي ‪ .....‬ذات العشــر ســنوات وهــي يف درج املنــزل فقــال لهــا‬\n      ‫اســكتي ويشــير بإصبعــه علــى فمــه فلمــا قالــت املــرأة حرامــي حلقــت بــه‬\n      ‫ثــم هــرب الــى املزرعــة وهــو يقــول هجــو جاءنــا وكان ذلــك بعــد الســاعة‬\n      ‫‪12.00‬ليــا ثــم إننــي تعرفــت عليــه بعــد ذلــك عنــد الشــرطة ولــم أكــن‬\n      ‫أعرفــه قبــل ذلــك كمــا تعرفــت عليــه ابنتــي ‪ ...‬واملدعــى عليــه لــم أره‬\n      ‫كســر شــيئا أو ســرق شــيئا مــن املنــزل هــذا مــا لــدي وبــه أشــهد هــذا‬\n      ‫وقــد جــرى تعديلــه التعديــل الشــرعي يف ضبطــه‪ .‬وبعــرض ذلــك علــى‬\n      ‫املدعــي العــام قــال لــدي زيــادة بينــة ورفعــت اجللســة لعــرض الشــاهد‬\n      ‫وشــهادته علــى املدعــى عليــه واحضــار معدلــن للشــاهد‪ .‬ويف يــوم االثنــن‬\n      ‫املوافــق ‪1433/04/19‬ه ـ افتتحــت اجللســة وفيها حضــر أطراف الدعوى‬\n      ‫وقــد أحضــر املدعــي العــام معــه كال مــن ‪ .......‬ســعودي بالســجل املدنــي‬\n      ‫رقــم ‪ .........‬و‪ .....‬ســعودي بالســجل املدنــي رقــم ‪......‬و‪........‬ســعودي‬\n      ‫بالســجل املدنــي رقــم ‪......‬و‪......‬ســعودي بالســجل املدنــي رقــم ‪........‬وطلــب‬\n      ‫ســماع مــا لديهــم وبســؤالهم شــهد األول ‪ ......‬قائــا انــه يف شــهر ذي‬\n      ‫القعــدة مــن عــام ‪1432‬ه ـ رأيــت املدعــى عليــه ‪ .......‬الســاعة السادســة‬\n\n\n‫‪281‬‬\n\f‫صباحــا كان يريــد ان يتماســك مــع اخــي ‪ ....‬وكان ‪ .....‬يريــد اخــذ اللــي‬\n‫معــه وكان معــه كيــس او قمــاش فافلــت منــه وهــرب خــارج البيــت‬\n‫وكان ذلــك بعــد اســتغاثة والدتــي بقولهــا( احلرامــي )وقــد ســرق مبلغــا‬\n‫مــن املــال ثــم حلقنــا بــه انــا واخــي واخــذ يتنقــل يف احلــارة حتــى حضــرت‬\n‫الشــرطة ومت القبــض عليــه واســتلمت الشــرطة مــا معــه مــن املــال وكان‬\n‫مقــدار مــا اســتلمته الشــرطة هــو اثنــان وعشــرون الــف ريــال بالرغــم مــن‬\n‫ان املبلــغ املســروق مــن بيتنــا كان فــوق اخلمســن الــف ريــال كمــا ان‬\n‫منزلنــا تعــرض لســرقة ســابقة بنفــس طريقــة الســرقة لكننــا لــم نشــاهد‬\n‫احــدا هــذا مــا لــدي وبــه اشــهد كمــا شــهد الثانــي ‪ .......‬قائــا انــه بعــد‬\n‫صــاة الفجــر مــن يــوم األحد‪1432/11/25‬ه ـ كنــت جالسـ ًا عنــد بــاب‬\n‫منزلــي فشــاهدت املدعــى عليــه ‪ .....‬يركــض مــع الشــارع املقابــل ملنزلنــا‬\n‫مــن الشــمال باجتــاه اجلنــوب ويلبــس بنطــا ًال أســود وبدلــة رصاصيــة وهــو‬\n‫نحيــف وطويــل وحليتــه خليجيــة وتوجــد بــه صلعــة يف منتصــف الــرأس‬\n‫وصلعــة يف آخــره وعندمــا شــاهدته خفــف الركــض وأخــذ يهــرول فمــر‬\n‫مــن الطريــق صديقــي ‪ .......‬بســيارته مــن نــوع ‪ .......‬وكان مســرع ًا فشـ ّـك‬\n‫يف الوضــع ثــم عــاد ‪ .....‬وركبــت معــه واجتهــت للجهــة الغربيــة مــن املنــزل‬\n‫وشــاهدنا املتهــم واقــف عنــد بــاب اســتراحة شــباب مجــاورة لــه ويضــع‬\n‫يديــه يف جيبــه بعدمــا قــام برمــي مــا معــه داخــل احلــوش ثــم اخــذ أحجــار‬\n‫ورمــى بهــا يف حــوش أغنــام قريــب منــه ثــم توجــه املدعــى عليــه ملنــزل ‪.....‬‬\n‫فحضــرت انــا و‪ ....‬وســألناهما هــل شــاهدا غنمــا ضائعــة فقــال املدعــى‬\n‫عليــه نعــم رايتهــا اول الصبــح وكان املدعــى عليــه جالس ـ ًا عنــد ‪.....‬‬\n‫فاتصــل ‪....‬علــى الشــرطة ثــم ذهبنــا واحضرنــا والــدة ‪ .....‬فتعرفــت علــى‬\n‫املدعــى عليــه ثــم انزلنــي ‪ ....‬يف البيــت وصعــدت علــى الســطح ملراقبــة‬\n\n\n                                                                                       ‫‪282‬‬\n\f      ‫املدعــى عليــه فركــب املدعــى عليــه مــع ‪ ......‬واجتهــا لشــرق البلــد الــى‬\n      ‫مدرســة االوالد فاتصلــت علــى ‪ ....‬وكــذا علــى ‪ .....‬وأخبرتهمــا بذلــك‬\n      ‫هــذا مــا لــدي وبــه أشــهد كمــا شــهد الثالــث ‪ ......‬قائــا أنــه بعــد صــاة‬\n      ‫الفجــر مــن يــوم األحــد ‪1432/11/25‬ه ـ شــاهد املدعــى عليــه يركــض‬\n      ‫مــع الشــارع املقابــل ملنــزل الشــاهد ‪ .....‬وكان يرتــدي بنطــا ًال أســود‬\n      ‫وبدلــة رصاصيــة كمــا شــاهد املدعــي ‪ .......‬يالحقــه فركــب ســيارته‬\n      ‫وحلــق بــه لينظــر مــا الــذي يجــري فوجــد‪ ......‬ومعــه الشــاهد ‪ ........‬متوقــف‬\n      ‫بالقــرب مــن منــزل ‪ ......‬والــذي يقــف بجوارهــا املدعــى عليــه يتحــدث مــع‬\n      ‫‪ .....‬وابنــه ‪ .....‬فوقــف عندهــم فذكــر لــه ‪ .....‬أن املدعــى عليــه ســرق مــن‬\n      ‫عندهــم وملــا اقتــرب منــه عــرف أنــه املدعــى عليــه للمعرفــة الســابقة‬\n      ‫بينهمــا ثــم رجــع ملنزلــه فاتصــل بــه املدعــي ‪....‬وأخبــره أن املدعــى عليــه‬\n      ‫ركــب مــع ‪ ...‬علــى ســيارته مــن نــوع ‪ ......‬وطلــب منــه مراقبتهمــا فتحــرك‬\n      ‫للبحــث عنهمــا فوجــد املتهــم عنــد بــاب منــزل ‪ .....‬فتوقــف عنــده وس ـلّم‬\n      ‫عليــه والحــظ عليــه عالمــات االرتبــاك فســأله عــن ســبب تواجــده يف‬\n      ‫هــذا املــكان فأخبــره أنــه عنــد بــاب منــزل عمــه وســأله هــل هنــاك شــيء‬\n      ‫حصــل يف البلــد فــرد عليــه أنــه جــاءه قائــد ســيارة مــن نــوع ‪ .....‬يســأله عــن‬\n      ‫غنــم بعــد ذلــك حضــرت الدوريــات وقبضــت عليــه كمــا شــهد الرابــع‬\n      ‫‪ ......‬قائــا انــه بتاريــخ ‪1432/11/25‬ه ـ بعــد صــاة الفجــر ســمعت‬\n      ‫صــوت غريــب يف اجلهــة اجلنوبيــة مــن منزلنــا وذهبــت مســرعا الــى نفــس‬\n      ‫الصــوت ورأيــت املدعــى عليــه ‪ .....‬مشــتبكا مــع الوالــدة كان يحــاول‬\n      ‫الفــرار منهــا وانفلــت منهــا وحلقــت بــه داخــل احلــارة وضيعتــه بــن البيــوت‬\n      ‫ثــم وجــدت ‪ .....‬فســالته هــل مــر احــد مــن هنــا فأجــاب نعــم اننــي رأيــت‬\n      ‫شــخصا يركــض وبعــد ان رآنــي بــداء يهــرول وســالته ايــن ذهــب فقــال‬\n\n\n‫‪283‬‬\n\f‫ذهــب الــى بيــت ‪ .....‬خلــف بيــت ‪ ....‬ثــم توقــف عنــد بيــت ‪ .....‬وكنــت‬\n‫اراقبــه ثــم ذهــب الــى اجلهــة اجلنوبيــة مــن منــزل ‪ .....‬وجلــس بجانبــه ثــم‬\n‫ذهبــت انــا و‪ ....‬اليــه وســألته مجــرد اســتدراج وتأخيــره حلــن حضــور‬\n‫الشــرطة وبعــد ذلــك اجتــه مــع ‪ ......‬الــى منــزل ‪ ....‬وحضــرت الشــرطة ومت‬\n‫القبــض عليــه هــذا مــا لــدي وبــه اشــهد‪ .‬هكــذا شــهدوا وجــرى تعديلهــم‬\n‫التعديــل الشــرعي يف ضبطه‪0‬وبعــرض ذلــك علــى املدعــى عليــه قــال مــا‬\n‫اقــول اال حســبي اهلل عليهــم ثــم ســألناه هــل تعــرف الشــهود فامتنــع عــن‬\n‫اجلــواب ثــم ســألناه عــن الشــهادة فقــال غيــر صحيحــة وصحيــح حضــر‬\n‫بعــض الشــهود وكنــت جالســا عنــد ‪ .....‬وســألوا ‪ ...‬وال اعلــم عــن مــاذا‬\n‫وكانــوا تهجمــوا علــي قبــل ذلــك عنــد التوقيــف واثنــاء ذلــك حضــر ‪....‬‬\n‫املذكــور بعاليــه ونظــر الــى املدعــى عليــه وقــال هــذا هــو الــذي رايتــه‬\n‫وقــت احلادثــة واشــهد عليــه فيمــا تقــدم ذكــره وبعــرض ذلك علــى املدعى‬\n‫عليــه قــال ال اعــرف هــذا الشــاهد اال اننــي قابلتــه يف مركــز الشــرطة‬\n‫بالشماســية فلــم يتعــرف علــي وشــهادته غيــر صحيحــة وحيــث االمــر‬\n‫ســألنا املدعــي العــام هــل لديــه زيــادة بينــة فقــال نعــم يف املعاملــة واطلــب‬\n‫االطــاع عليهــا‪ .‬ويف يــوم الثالثــاء املوافق‪1433/05/11‬ه ـ حضــر‬\n‫املعدلــون للشــهود ومرصــودة أســماءهم وشــهادتهم بالزكيــة يف الضبط‪.‬‬\n‫ثــم جــرى ســؤال املدعــي العــام هــل لديــك زيــادة بينــة أجــاب ليــس لــدي‬\n‫ســوى مــا قدمــت ورفعــت اجللســة للتأمــل‪ .‬ويف يــوم اإلثنــن‬\n‫املوافق‪1433/05/24‬ه ـ حضــر املدعــي العــام واملدعــى عليــه ثــم جــرى‬\n‫اطالعنــا علــى املعاملــة ومنهــا مــا جــاء يف محضــر املعاينــة علــى صفحــة‬\n‫‪3‬لفــة(‪ )1‬املتضمــن ‪:‬أن املدعــى عليــه حــاول تســور منــزل ‪ .........‬مــن اجلهــة‬\n‫اجلنوبيــة الغربيــة بوضعــه قطعــة خشــبية للصعــود عليهــا ولــم يســتطع‬\n\n\n                                                                                         ‫‪284‬‬\n\f      ‫كمــا شــوهدت لــه آثــار كثيــرة يف املوقــع بعدهــا اجتــه لزاويــة املنــزل‬\n      ‫الشــمالية وتســور اجلــدار الشــمالي عــن طريــق البــاب ومــن ثــم دخــل لفنــاء‬\n      ‫املنــزل حيــث لوحــظ نزولــه علــى إطــارات ســيارة كانــت موجــودة يف‬\n      ‫املنــزل بجانــب اجلــدار وشــوهدت آثــاره حــايف القدمــن داخــل ســور املنــزل‬\n      ‫متجهـ ًا ملــكان الســرقة ومبعاينــة الغرفــة التــي حدثــت بها الســرقة اتضح‬\n      ‫أنهــا يف مقدمــة املنــزل ويوجــد فيهــا دوالب خشــبي عرضــه متــر وارتفاعه‬\n      ‫متريــن ويوجــد داخلــه شــنطة حديديــة ومالبــس وقــد لوحــظ آثــار عنــف‬\n      ‫علــى الــدوالب كمــا وجــد يف الغرفــة حــذاء وجعبــة جــوال أفــاد أصحــاب‬\n      ‫املســكن عائديتهــا للمدعــى عليــه حيــث تركهــا أثنــاء العــراك مــع‬\n      ‫والــدة املدعــي كمــا متــت متابعــة آثــار املدعــى عليــه والطــرق التــي‬\n      ‫ســلكها بعــد خروجــه مــن املنــزل حتــى مت القبــض عليه كمــا مت البحث‬\n      ‫يف كل املواقــع التــي يحتمــل أنــه ســلكها للبحــث عــن اجلــزء املتبقــي مــن‬\n      ‫املبلــغ املســروق ولــم يعثــر علــى شــيء كمــا أنــه جــرى معاينــة املوقــع مــن‬\n      ‫قبــل املختصــن باألدلــة اجلنائيــة وقصــاص االثــر‪ .‬وعلــى صفحة‪2‬لفــة(‪)2‬‬\n      ‫إقــرار قصــاص األثــر املتضمــن‪ :‬وبعــد وصولنــا الــى املوقــع شــاهدت اثــر‬\n      ‫شــخص حــايف االقــدام بداخــل احلــوش وخارجــه ومت تطبيقهــا علــى املتهــم‬\n      ‫‪ ............‬واملوقــوف لــدى شــرطة الشماســية وتنطبــق اآلثــار علــى اآلثــار‬\n      ‫املوجــودة باحلــوش وخــارج احلــوش وعلــى هــذا جــرى التوقيــع مــن ‪..........‬‬\n      ‫‪.‬وعلــى صفحة‪16‬لفــة(‪ )6‬محضــر قصــاص االثــر اقــر انــا قصــاص االثــر‬\n      ‫‪ .......‬انــه مت مشــاهدة اثــار املتهــم ‪ ........‬املوجــود لــدى الســجن العــام‬\n      ‫ببريــدة ومت تطبيــق اثــاره واتضــح انهــا تنطبــق علــى اآلثــار التــي ســبق وان‬\n      ‫عاينتهــا يف منــزل املخبــر ‪ .........‬هــذا مــا لــدي وعليــه جــرى التوقيــع كمــا‬\n      ‫جــرى االطــاع علــى مــا جــاء يف محضــر القبــض والتفتيــش علــى لفــة(‪)1‬‬\n\n\n‫‪285‬‬\n\f‫ص‪ 6‬وفيــه ‪:‬يف يــوم االحــد ‪1432/11/25‬ه ـ الســاعة السادســة صباحــا‬\n‫ويف بلــدة ‪ ......‬ألقــي القبــض علــى املدعــى عليــه وبتفتيشــه عثــر علــى مبلــغ‬\n‫اثنــن وعشــرون الــف ريــال وبعــرض ذلــك علــى املدعــى عليــه قــال مــا‬\n‫ذكــر غيــر صحيــح وصحيــح انــه قبــض علــي بالتاريــخ املذكــور قريبــا‬\n‫مــن الســاعة الســابعة صباحــا وكان معــي املبلــغ املذكــور وانــا الــذي‬\n‫اخرجــت مــا معــي مــن االغــراض ومنهــا املبلــغ املذكــور وذلــك لــدى‬\n‫مركــز الشــرطة عندمــا طلــب منــي ضابــط اخلفــر واملبلــغ يخصنــي‬\n‫وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح مــا جــاء يف دعــواي‬\n‫واكتفــي مبــا تق ــدم ورفعــت اجللســة لدراســة مــا مت ضبطــه‪0‬ويف يــوم‬\n‫االثنــن املوافق‪1433/06/09‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام واملدعــى عليــه فبعــد ســماعنا لدعــوى املدعي العــام وإجابة املدعى‬\n‫عليــه واالطــاع علــى أوراق املعاملــة وبعــد تأمــل القضيــة ودراســتها‬\n‫وحيــث أنكــر املدعــى عليــه الدعــوى وقــد طلــب املدعــي العــام إقامــة‬\n‫حــد الســارق وحيــث إن مــا قدمــه مــن بينــة ال يثبــت بهــا احلــد لعــدم‬\n‫اكتمــال البينــة ونظــرا لعــدم توفــر شــروط إقامــة احلــد وألن إنــكار‬\n‫املدعــى عليــه للدعــوى شــبهة يــدرأ بهــا احلــد وقــد انعقــد اإلجمــاع علــى أن‬\n‫احلــدود تــدرأ بالشــبهات غيــر أن املدعــى عليــه يســتحق العقوبــة التعزيرية‬\n‫الرادعــة لــذا قررنــا مــا يلــي ‪ -:‬اوال‪ :‬درأنــا حــد الســارق عــن املدعــى عليــه‬\n‫لعــدم اكتمــال البينــة املوجبــة للحــد ‪ .‬ثانيــا‪ :‬نظــرا لتوجــه التهمــة القويــة‬\n‫ضــد املدعــى عليــه وذلــك ملــا جــاء يف شــهادة الشــهود املعدلــن شــرعا مــن‬\n‫رؤيــة املدعــى عليــه داخــل البيــت وتعرفهــم عليــه وملــا تضمنــه محضــر‬\n‫قصــاص األثــر ومحضــر املعاينــة املرصــودة بعاليــه وملــا تضمنــه محضــر‬\n‫القبــض والتفتيــش املــدون بعاليــه ونظــرا لتكــرر ســوابق املدعــى عليــه‬\n\n\n                                                                                         ‫‪286‬‬\n\f      ‫حيــث ســجل عليــه اربــع تهــم يف ســرقات ودخــول منــازل وحيــث ان مــا‬\n      ‫فعلــه املدعــى عليــه محــرم شــرعا وفيــه انتهــاك حلرمــة مــال الغيــر لــذا‬\n      ‫قررنــا تعزيــر املدعــى عليــه ‪ .........‬وذلــك بالســجن ملــدة ســبع ســنوات تبــدأ‬\n      ‫مــن تاريــخ إيقافــه الواقــع يف ‪1432/11/25‬ه ـ وجلــده تســعمائة جلــدة‬\n      ‫مفرقــة علــى ثمانيــة عشــرة فتــرة مقــدار كل دفعــة خمســن جلــدة علنــا‬\n      ‫يف مــكان عــام بــن كل دفعــة وأخــرى عشــرة أيــام ‪ .‬ثالثـاً‪ :‬يؤخــذ التعهد‬\n      ‫علــى املدعــى عليــه بعــدم العــودة ملثــل ذلــك فــإن عــاد فســوف يعــرض‬\n      ‫نفســه لعقوبــة أشــد مــن ذلــك هــذا مــا ظهــر لنــا يف كل مــا تق ــدم وبــه‬\n      ‫حكمنــا وبعــرض احلكــم علــى أطــراف الدعــوى قــرر املدعــى عليــه‬\n      ‫قناعتــه باحلكــم وامــا املدعــي العــام فقــرر عــدم القناعــة وطلــب رفعــه‬\n      ‫حملكمــة االســتئناف مــع تقــدمي الئحــة اعتراضيــة فأجيــب لطلبــه وعليــه‬\n      ‫مراجعتنــا بتاريــخ ‪1433/6/11‬ه ـ الســتالم نســخة مــن احلكــم يقــدم‬\n      ‫بعدهــا مــا لديــه خــال مــدة ثالثــن يومــا وإن تأخــر عــن املــدة املذكــورة‬\n      ‫فســيتم تطبيــق التعليمــات اخلاصــة بذلــك ‪ ،‬وبــاهلل التوفيــق ‪ .‬حــرر يف‬\n      ‫‪1433/06/09‬ه ـ ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                    ‫وسلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لدينــا نحــن قضــاة الدائــرة اجلنائيــة الثانيــة يف‬\n      ‫احملكمــة العامــة ببريــدة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة برقــم ‪ ............‬املشــار إليهــا بعاليــه ويف يــوم اإلثنــن‬\n      ‫املوافق‪1433/10/09‬ه ـ افتتحــت اجللســة الســاعة ‪09.30‬ص وفيهــا‬\n      ‫حضــر املدعــى عليــه ‪ ......‬وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالقصيــم برقــم ‪ 331493564‬يف ‪1433/9/2‬ه ـ ومشــفوعها قــرار‬\n      ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة املختصــة بتدقيــق القضايــا‬\n\n\n‫‪287‬‬\n\f‫اخلماســية مبحكمــة االســتئناف رقــم ‪ 33386166‬يف ‪1433/8/20‬ه ـ‬\n‫املتضمــن وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن‬\n‫مــا حكــم بــه أصحــاب الفضيلــة علــى املدعــى عليــه مــن تعزيــر بالســجن‬\n‫قليــل خلطــورة مــا أقــدم عليــه وكونــه جمــع يف هــذه القضيــة أربــع قضايــا‬\n‫خطيــرة وقــوة القرائــن ووجــود ســت ســوابق عليــه أربــع منهــا ســرقة‬\n‫األمــر الــذي يــدل علــى اســتهتاره وعــدم مباالتــه وجرأتــه وأنــه البــد مــن‬\n‫جــزاء الــرادع لــه ولغيــره ممــن تســول لــه نفســه ســلوك مثــل مســلكه‬\n‫كمــا لوحــظ أنــه هنــاك اختــاف يف القــرار والضبــط يف قناعــة املدعــى‬\n‫عليــه فالبــد مــن التصحيــح وعــدم اطــاع أحــد القضــاة املشــتركني‬\n‫علــى الالئحــة املقدمــة مــن املدعــى العــام وتوقيعــه والبــد مــن ذلــك فعلــى‬\n‫أصحــاب الفضيلــة مالحظــة مــا ذكــر وإجــراء مــا يلــزم نحــوه ثــم إعــادة‬\n‫املعاملــة إلكمــال الزمهــا أ‪.‬ه ـ ‪ .‬وعليــه جنيــب أصحــاب الفضيلــة ‪.‬ونقــول‬\n‫نظــرا ملــا ذكــر وبعــد التأمــل يف ذلــك فقــد قررنــا زيــادة عقوبــة املدعــى‬\n‫عليــه ‪ ..........‬بالســجن ملــدة ســنتني إضافــة ملــا ســبق بحيــث يســجن ملــدة‬\n‫تســع ســنوات مــع اجللــد املوضــح بعاليــه وبــه حكمنــا وبعــرض احلكــم‬\n‫علــى املدعــى عليــه قــرر عــدم القناعــة باحلكــم مــع تقــدمي الئحــة‬\n‫اعتراضيــة فأجيــب لطلبــه وعليــه جــرى تســليمه صــورة مــن القــرار يف‬\n‫هــذه اجللســة وامــا بخصــوص عــدم اطــاع أحــد القضــاة املشــتركني‬\n‫علــى الالئحــة املقدمــة مــن املدعــى العــام وتوقيعــه فقــد جــرى إكمــال‬\n‫الــازم حيــال ذلــك مــن قبــل فضيلــة القاضــي املشــارك وأمــا بخصــوص‬\n‫القناعــة فقــد قــرر املدعــى عليــه عــدم القناعــة وهــو منهيــا للخــاف‬\n‫الواقــع ســهوا وبــاهلل التوفيــق ‪ .‬حــرر يف ‪ 1433/10/09‬ه ـ ‪ ،‬وصلــى اهلل‬\n                                ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪0‬‬\n\n\n                                                                                      ‫‪288‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لدينــا نحــن قضــاة الدائــرة اجلنائيــة الثانيــة يف‬\n      ‫احملكمــة العامــة ببريــدة ويف يــوم األربعــاء املوافــق ‪1434/1/21‬ه ـ‬\n      ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالقصيــم برقــم ‪ 331493564‬وتاريــخ ‪1433/9/2‬ه ـ ومشــفوعاتها‬\n      ‫(قــرار تصديــق ) صــادر مــن قضــاة الدائــرة اخلماســية املختصــة بتدقيــق‬\n      ‫القضايــا اخلماســية يف احملكمــة املشــار إليهــا برقــم ‪ 33386166‬وتاريــخ‬\n      ‫‪1433/8/20‬ه ـ املتضمــن ‪ ( :‬املصادقــة علــى احلكــم ) ولــذا جــرى‬\n      ‫احلاقــه‪ .‬وبــاهلل التوفيــق ‪ .‬حــرر يف ‪ 1434/01/21‬هــ‪ .‬وصلــى اهلل علــى‬\n                                          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪0‬‬\n      ‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n      ‫بتدقيــق القضايــا اخلماســية مبحكمــة االســتئناف مبنطقــة القصيــم‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بـبـري ــدة‬\n      ‫ب ــرق ـ ـ ـ ــم ‪ 331654124‬وتـاري ـ ــخ ‪1433/11/16‬ه ـ املرفــق بهــا القــرار‬\n      ‫رقــم ‪ 33290357‬وتاريــخ ‪1433/6/10‬ه ـ الصــادر مــن صاحب الفضيلة‬\n      ‫الشــيخ ‪ ........‬القاضــي باحملكمــة باالشــتراك مــع صاحبــي الفضيلــة‬\n      ‫الشــيخ ‪ ........‬مســاعد رئيــس احملكمــة والشــيخ ‪ ..........‬القاضــي بهــا‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ...........‬التهامــه بانتهــاك حرمــة عــدة‬\n      ‫ا وترويــع ســاكنيها والســرقة منهــا وقــد تضمــن‬         ‫منــازل ودخولهــا لي ـ ً‬\n      ‫القــرار حكــم أصحــاب الفضيلــة بــدرء حــد الســارق عــن املدعــى عليــه‬\n      ‫لعــدم اكتمــال البينــة املوجبــة للحــد ولتوجــه التهمــة القويــة نحــو املدعــى‬\n      ‫عليــه قــرروا تعزيــره بالســجن واجللــد علــى النحــو املفصــل يف القــرار وقــد‬\n      ‫ســبق منــا دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n      ‫ـاء‬\n       ‫مــا أجــاب بــه أصحــاب الفضيلــة وأحلقــوه بالقــرار وصــورة ضبطــه بنـ ً‬\n\n‫‪289‬‬\n\f‫علــى قرارنــا رقــم ‪ 33386166‬وتاريــخ ‪1433/8/20‬ه ـ قررنــا املصادقــة‬\n‫علــى مــا حكــم بــه أصحــاب الفضيلــة بعــد اإلجراء األخيــر واهلل املوفق‪،‬‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪290‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":273,"source_page_end":290,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"58294dfcb1d7af2a4fe3470f0b6cda292e8b90541f991257aee0c045a4f5d215","normalized_text_hash":"c0e4a9b7416c82ac956556187720e3568662e75d1f92e5a139630207123eb294","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p273-33290357"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
